window.__X_NEWS__ = {"updated_at": "2026-10-21 16:11 Asia/Shanghai", "updated_at_iso": "2026-10-21T08:11:33Z", "count": 92, "domains": ["科技", "商业", "中国", "国际", "体育", "娱乐", "科学"], "items": [{"id": "2112613033243721837", "domain": "科技", "title_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development", "title_zh": "OpenAI 收购 Orchestra Bio，加速药物研发", "hook_en": "Scientists juggling drug trials now have AI agents watching timelines and spotting delays, like a failed manufacturing batch that could derail everything.", "hook_zh": "创业四周年那天，Ashoka Rajendra 得知 OpenAI 将把团队收入麾下。", "summary_en": "OpenAI announced on October 20, 2026, its acquisition of Orchestra Bio, folding the startup's team and technology into its Rosalind AI suite for life sciences. The platform lets scientists delegate tasks like study monitoring and delay flagging to AI agents, helping teams respond quickly and advance discoveries into patient treatments. Founder Ashoka Rajendra, who started the company four years ago, expressed excitement about scaling the mission at OpenAI, with President Greg Brockman calling it a promising step toward accelerating drug development. The deal builds on partnerships with firms like Novo Nordisk and Moderna, amid growing AI interest in biology from investors and other labs.", "summary_zh": "OpenAI 收购 Orchestra Bio，将其生物制药协作工具与面向生物、化学的 Rosalind AI 模型结合，推动发现更快转化为疗法。", "body_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development.\n\nScientists juggling drug trials now have AI agents watching timelines and spotting delays, like a failed manufacturing batch that could derail everything.\n\nOpenAI announced on October 20, 2026, its acquisition of Orchestra Bio, folding the startup's team and technology into its Rosalind AI suite for life sciences.\n\nThe platform lets scientists delegate tasks like study monitoring and delay flagging to AI agents, helping teams respond quickly and advance discoveries into patient treatments. Founder Ashoka Rajendra, who started the company four years ago, expressed excitement about scaling the mission at OpenAI, with President Greg Brockman calling it a promising step toward accelerating drug development. The deal builds on partnerships with firms like Novo Nordisk and Moderna, amid growing AI interest in biology from investors and other labs.", "body_zh": "OpenAI 收购 Orchestra Bio，加速药物研发。\n\n创业四周年那天，Ashoka Rajendra 得知 OpenAI 将把团队收入麾下。\n\nOpenAI 收购 Orchestra Bio，将其生物制药协作工具与面向生物、化学的 Rosalind AI 模型结合，推动发现更快转化为疗法。\n\n综合以上信息，OpenAI 收购 Orchestra Bio，加速药物研发一事持续引发关注。", "url": "https://x.com/i/trending/2112613033243721837", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-21T07:40:33.000Z"}, {"id": "2112188369618784335", "domain": "科技", "title_en": "DHS Orders Civilian Agencies to Remove DeepSeek AI Products", "title_zh": "美国土安全部要求民事机构清除 DeepSeek 产品", "hook_en": "DeepSeek's low-cost, high-performance AI tools have won fans worldwide, but now U.S. civilian agencies must cut ties over security worries tied to its China base.", "hook_zh": "联邦民事机构接到明确指令：因涉华安全风险，须从系统中移除相关中国 AI 工具。", "summary_en": "The Department of Homeland Security issued an order under Docket No. DHS-2026-0628, requiring all civilian federal agencies to remove DeepSeek products from their IT systems and halt purchases of them or related third-party services. The move cites risks like Chinese government access to servers, potential data collection on U.S. users, and security vulnerabilities in the applications. Effective immediately with Federal Register publication on October 20, 2026, the order excludes defense and national security systems but allows justified exceptions. It highlights U.S. concerns in the AI race with China, even as DeepSeek's efficient models and open-source efforts draw praise from users.", "summary_zh": "美国国土安全部于 10 月 20 日下令，要求联邦民事机构从 IT 系统中移除所有 DeepSeek 产品、关联方及相关第三方服务，并停止后续采购。关切包括公司总部位于中国、数据可能移交中国当局、收集个人信息，以及对美国人实施恶意软件或情报搜集的风险。此举凸显美中 AI 博弈；DeepSeek 最新 V4.1 因在日常硬件上的速度与效率仍受关注。命令仅适用于民事机构，可有例外。", "body_en": "DHS Orders Civilian Agencies to Remove DeepSeek AI Products.\n\nDeepSeek's low-cost, high-performance AI tools have won fans worldwide, but now U.S. civilian agencies must cut ties over security worries tied to its China base.\n\nThe Department of Homeland Security issued an order under Docket No.DHS-2026-0628, requiring all civilian federal agencies to remove DeepSeek products from their IT systems and halt purchases of them or related third-party services.\n\nThe move cites risks like Chinese government access to servers, potential data collection on U.S.users, and security vulnerabilities in the applications. Effective immediately with Federal Register publication on October 20, 2026, the order excludes defense and national security systems but allows justified exceptions.It highlights U.S. concerns in the AI race with China, even as DeepSeek's efficient models and open-source efforts draw praise from users.", "body_zh": "美国土安全部要求民事机构清除 DeepSeek 产品。\n\n联邦民事机构接到明确指令：因涉华安全风险，须从系统中移除相关中国 AI 工具。\n\n美国国土安全部于 10 月 20 日下令，要求联邦民事机构从 IT 系统中移除所有 DeepSeek 产品、关联方及相关第三方服务，并停止后续采购。关切包括公司总部位于中国、数据可能移交中国当局、收集个人信息，以及对美国人实施恶意软件或情报搜集的风险。\n\n此举凸显美中 AI 博弈；DeepSeek 最新 V4.1 因在日常硬件上的速度与效率仍受关注。命令仅适用于民事机构，可有例外。", "url": "https://x.com/i/trending/2112188369618784335", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T06:46:44.000Z"}, {"id": "2112637284642349105", "domain": "科技", "title_en": "OpenAI Extends Prompt Caching to 12 Hours and Forever for Subscribers", "title_zh": "OpenAI 将提示词缓存延长至 12 小时", "hook_en": "Developers building long-running AI agents just got a game-changer: OpenAI's prompt caching now lasts up to 12 hours in the API and indefinitely for logged-in Codex and Work users.", "hook_zh": "开发长时运行智能体的工程师午休或开会后无需再重算上下文：共享指令最长可保温 12 小时。", "summary_en": "The update, shared by Tibo Sottiaux on day 16 of OpenAI's 28-day series, lets users reuse processed prompt prefixes like system instructions and tools, slashing input costs and speeding up responses for models such as gpt-6-astra, gpt-6.1-sol, and gpt-6-luna. In the API, a 12-hour cache option costs more upfront but saves on repeated reads, while Codex and Work subscribers enjoy permanent caching with no expiration or penalties. Developers cheered the news, with one calling it the 'biggest ship of the 28 days' and others marveling at the 'forever' cache for cost-conscious, always-on workflows.", "summary_zh": "OpenAI 更新 API，允许开发者以更低输入价将提示前缀缓存 12 小时，成本最高可降约 90%，并加快响应。已登录的 Codex 与 Work 用户可获无限期缓存。以 gpt-6-astra 等为例，缓存读取约每百万 token 1 美元，标准价约 10 美元，12 小时写入约 25 美元。该变更自 10 月 20 日生效，利于间歇式工作流，持久智能体场景的节省也令开发者振奋。", "body_en": "OpenAI Extends Prompt Caching to 12 Hours and Forever for Subscribers.\n\nDevelopers building long-running AI agents just got a game-changer: OpenAI's prompt caching now lasts up to 12 hours in the API and indefinitely for logged-in Codex and Work users.\n\nThe update, shared by Tibo Sottiaux on day 16 of OpenAI's 28-day series, lets users reuse processed prompt prefixes like system instructions and tools, slashing input costs and speeding up responses for models such as gpt-6-astra, gpt-6.1-sol, and gpt-6-luna.\n\nIn the API, a 12-hour cache option costs more upfront but saves on repeated reads, while Codex and Work subscribers enjoy permanent caching with no expiration or penalties. Developers cheered the news, with one calling it the 'biggest ship of the 28 days' and others marveling at the 'forever' cache for cost-conscious, always-on workflows.", "body_zh": "OpenAI 将提示词缓存延长至 12 小时。\n\n开发长时运行智能体的工程师午休或开会后无需再重算上下文：共享指令最长可保温 12 小时。\n\nOpenAI 更新 API，允许开发者以更低输入价将提示前缀缓存 12 小时，成本最高可降约 90%，并加快响应。已登录的 Codex 与 Work 用户可获无限期缓存。\n\n以 gpt-6-astra 等为例，缓存读取约每百万 token 1 美元，标准价约 10 美元，12 小时写入约 25 美元。该变更自 10 月 20 日生效，利于间歇式工作流，持久智能体场景的节省也令开发者振奋。", "url": "https://x.com/i/trending/2112637284642349105", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T06:02:59.000Z"}, {"id": "2112630070984802593", "domain": "科技", "title_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations", "title_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天", "hook_en": "Ever needed to tuck away a sensitive ChatGPT chat before handing over your screen? OpenAI's new Locked Chats feature makes that simple with a quick PIN lock.", "hook_zh": "把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 就能搞定。", "summary_en": "Users can now move eligible chats into a protected \"Locked chats\" section, hidden from history and search until unlocked via a four-digit PIN, Face ID, Touch ID, or device unlock on web, desktop, and mobile. It keeps personal talks or surprise plans private when sharing devices, rolling out today across all plans including Free, Plus, Pro, Business, Enterprise, and Edu. Locked chats stay separate from regular memory, but pre-locked memories remain, and the feature skips temporary chats, archived ones, group chats, shared links, scheduled tasks, or meeting recordings—with no end-to-end encryption or changed retention rules.", "summary_zh": "用户可将聊天移入受保护区域，需 PIN、Face ID 或 Touch ID 解锁才可见；功能将覆盖免费到企业版各档套餐。", "body_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations.\n\nEver needed to tuck away a sensitive ChatGPT chat before handing over your screen? OpenAI's new Locked Chats feature makes that simple with a quick PIN lock.\n\nUsers can now move eligible chats into a protected \"Locked chats\" section, hidden from history and search until unlocked via a four-digit PIN, Face ID, Touch ID, or device unlock on web, desktop, and mobile.\n\nIt keeps personal talks or surprise plans private when sharing devices, rolling out today across all plans including Free, Plus, Pro, Business, Enterprise, and Edu. Locked chats stay separate from regular memory, but pre-locked memories remain, and the feature skips temporary chats, archived ones, group chats, shared links, scheduled tasks, or meeting recordings—with no end-to-end encryption or changed retention rules.", "body_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天。\n\n把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 就能搞定。\n\n用户可将聊天移入受保护区域，需 PIN、Face ID 或 Touch ID 解锁才可见；功能将覆盖免费到企业版各档套餐。\n\n综合以上信息，OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天一事持续引发关注。", "url": "https://x.com/i/trending/2112630070984802593", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-20T23:00:11.000Z"}, {"id": "2112176711844458620", "domain": "科技", "title_en": "Anthropic Commits Shares to Public Benefit Fund", "title_zh": "Anthropic 将股份拨入公益基金", "hook_en": "Anthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.", "hook_zh": "Anthropic 承诺拿出 5% 股份用于公益，被视作对 AI「丰裕」承诺的回应。", "summary_en": "The AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline. Combined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "summary_zh": "公益基金起步拟配置 5% 股份（待批准）；叠加此前承诺，约 20% 股份将用于非营利捐赠与就业冲击援助。", "body_en": "Anthropic Commits Shares to Public Benefit Fund.\n\nAnthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.\n\nThe AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline.\n\nCombined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "body_zh": "Anthropic 将股份拨入公益基金。\n\nAnthropic 承诺拿出 5% 股份用于公益，被视作对 AI「丰裕」承诺的回应。\n\n公益基金起步拟配置 5% 股份（待批准）；叠加此前承诺，约 20% 股份将用于非营利捐赠与就业冲击援助。\n\nAnthropic 承诺拿出 5% 股份用于公益，被视作对 AI「丰裕」承诺的回应。\n\n综合以上信息，Anthropic 将股份拨入公益基金一事持续引发关注。", "url": "https://x.com/i/trending/2112176711844458620", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:34:55.000Z"}, {"id": "2112525486228156479", "domain": "科技", "title_en": "DeepSeek V4.1 Flash Outperforms OpenAI's GPT-6 Sol on Cybersecurity Benchmarks", "title_zh": "DeepSeek V4.1 Flash 在网络安全基准上胜过 OpenAI GPT-6 Sol", "hook_en": "In simulated corporate networks, DeepSeek V4.1 Flash 1017 completed more multi-step offensive cybersecurity objectives than a restricted version of OpenAI’s GPT-6 Sol. This open-weight model from China delivered results at lower cost, even using more tokens.", "hook_zh": "在模拟企业网络中，DeepSeek V4.1 Flash 1017 完成的多步进攻性网络安全目标多于受限版 OpenAI GPT-6 Sol。这款来自中国的开源权重模型成本更低，即便消耗更多 token。", "summary_en": "Vals AI's benchmarks show DeepSeek V4.1 Flash 1017, released around October 17, excelling in agentic tasks with a 1-million-token context window and open MIT-licensed weights on Hugging Face. It achieved strong scores like 42.7 objectives in its own harness and runs locally on hardware like two NVIDIA DGX Spark systems, with developers calling the speed a potential national security risk. MiniMax M3.1 Flash competes closely, offering lower costs on coding and visual tasks, as reactions blend excitement over affordable frontier performance with caution about dual-use cyber capabilities now openly available.", "summary_zh": "Vals AI 基准显示，约 10 月 17 日发布的 DeepSeek V4.1 Flash 1017 在智能体任务上表现突出，具备 100 万 token 上下文，并以 MIT 许可在 Hugging Face 开放权重。它在自有评测中取得如 42.7 个目标等强成绩，可在两台 NVIDIA DGX Spark 等硬件上本地运行，有开发者称其速度构成潜在国家安全风险。MiniMax M3.1 Flash 紧随其后，在编程与视觉任务上成本更低。舆论既兴奋于可负担的前沿性能，也警惕现已公开可用的双用途网络能力。", "body_en": "DeepSeek V4.1 Flash Outperforms OpenAI's GPT-6 Sol on Cybersecurity Benchmarks.\n\nIn simulated corporate networks, DeepSeek V4.1 Flash 1017 completed more multi-step offensive cybersecurity objectives than a restricted version of OpenAI’s GPT-6 Sol. This open-weight model from China delivered results at lower cost, even using more tokens.\n\nVals AI's benchmarks show DeepSeek V4.1 Flash 1017, released around October 17, excelling in agentic tasks with a 1-million-token context window and open MIT-licensed weights on Hugging Face.\n\nIt achieved strong scores like 42.7 objectives in its own harness and runs locally on hardware like two NVIDIA DGX Spark systems, with developers calling the speed a potential national security risk. MiniMax M3.1 Flash competes closely, offering lower costs on coding and visual tasks, as reactions blend excitement over affordable frontier performance with caution about dual-use cyber capabilities now openly available.", "body_zh": "DeepSeek V4.1 Flash 在网络安全基准上胜过 OpenAI GPT-6 Sol。\n\n在模拟企业网络中，DeepSeek V4.1 Flash 1017 完成的多步进攻性网络安全目标多于受限版 OpenAI GPT-6 Sol。这款来自中国的开源权重模型成本更低，即便消耗更多 token。\n\nVals AI 基准显示，约 10 月 17 日发布的 DeepSeek V4.1 Flash 1017 在智能体任务上表现突出，具备 100 万 token 上下文，并以 MIT 许可在 Hugging Face 开放权重。它在自有评测中取得如 42.7 个目标等强成绩，可在两台 NVIDIA DGX Spark 等硬件上本地运行，有开发者称其速度构成潜在国家安全风险。", "url": "https://x.com/i/trending/2112525486228156479", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T17:46:45.000Z"}, {"id": "2112595601669919101", "domain": "科技", "title_en": "OpenAI Quiets Support for AI Chip Export Limits to China", "title_zh": "OpenAI 对限制对华出口 AI 芯片的立场明显降温", "hook_en": "OpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.", "hook_zh": "OpenAI 曾大力推动美国严格限制先进 AI 芯片输往中国，如今却基本不再发声。", "summary_en": "Last year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion. Critics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "summary_zh": "去年 OpenAI 曾游说限制英伟达处理器流向有北京背景的实验室；知情人士称公司已停止相关倡议。这一转向有利于英伟达，也与其 2025 年一项重大基础设施合作相呼应。", "body_en": "OpenAI Quiets Support for AI Chip Export Limits to China.\n\nOpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.\n\nLast year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S.interests.\n\nCapitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion. Critics like Samuel Hammond call it shortsighted for U.S.AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy.Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "body_zh": "OpenAI 对限制对华出口 AI 芯片的立场明显降温。\n\nOpenAI 曾大力推动美国严格限制先进 AI 芯片输往中国，如今却基本不再发声。\n\n去年 OpenAI 曾游说限制英伟达处理器流向有北京背景的实验室；知情人士称公司已停止相关倡议。这一转向有利于英伟达，也与其 2025 年一项重大基础设施合作相呼应。\n\n综合以上信息，OpenAI 对限制对华出口 AI 芯片的立场明显降温一事持续引发关注。", "url": "https://x.com/i/trending/2112595601669919101", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:34:14.000Z"}, {"id": "2112386205996245100", "domain": "科技", "title_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development", "title_zh": "奥特曼勾勒先进 AI 安全发展的三条路径", "hook_en": "Sam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.", "hook_zh": "萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。", "summary_en": "Last week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures. The talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "summary_zh": "上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "body_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development.\n\nSam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.\n\nLast week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures.\n\nThe talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "body_zh": "奥特曼勾勒先进 AI 安全发展的三条路径。\n\n萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。\n\n上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。\n\n谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "url": "https://x.com/i/trending/2112386205996245100", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T14:10:55.000Z"}, {"id": "2112540739628630161", "domain": "科技", "title_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors", "title_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片", "hook_en": "Amazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.", "hook_zh": "大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。", "summary_en": "The company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake. This comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "summary_zh": "公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "body_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors.\n\nAmazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.\n\nThe company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake.\n\nThis comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "body_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片。\n\n大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。\n\n公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。\n\n有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "url": "https://x.com/i/trending/2112540739628630161", "category": "News", "topics": ["Business & Finance", "Stocks", "Technology", "AI"], "updated_at": "2026-10-20T13:52:24.000Z"}, {"id": "2111803212139569662", "domain": "科技", "title_en": "DeepSeek-V4.1-Flash Tops Coding Leaderboards at Fraction of Cost", "title_zh": "DeepSeek-V4.1-Flash 登顶编程榜，成本仅为对手零头", "hook_en": "DeepSeek AI just dropped an updated open model that climbed to the top of coding leaderboards, outpacing pricier rivals while running smoothly on home setups.", "hook_zh": "DeepSeek 发布更新开源模型，冲上编程排行榜前列，表现压过更贵对手，且能在家用设备上流畅运行。", "summary_en": "Released on October 17, DeepSeek-V4.1-Flash-1017 earned the #1 spot among open models on Arena.ai's Code Arena: WebDev leaderboard with 1,670 points, ranking #12 overall ahead of Claude Opus 5 (High) and close to GPT-6 Sol (Max)—all at one-tenth the cost of competitors like Kimi K3 (Max). The 552B-parameter model, with MIT-licensed weights on Hugging Face, also hit #11 in Agent Arena, showing gains in success rates and reliability. Developers quickly optimized it for local use via Unsloth quantizations and DeepSeek's open-source DeepInfer framework, making frontier-level coding and agent performance accessible and affordable.", "summary_zh": "10 月 17 日发布的 DeepSeek-V4.1-Flash-1017 在 Arena.ai 的 Code Arena: WebDev 开源模型榜夺得第一，得分 1670，总榜第 12，领先 Claude Opus 5（High），接近 GPT-6 Sol（Max），成本约为 Kimi K3（Max）等竞品的十分之一。该 5520 亿参数模型以 MIT 许可在 Hugging Face 开放权重，亦在 Agent Arena 排第 11，成功率与稳定性提升。开发者迅速用 Unsloth 量化与 DeepSeek 开源 DeepInfer 框架做本地优化，使前沿级编程与智能体能力更易获得、更便宜。", "body_en": "DeepSeek-V4.1-Flash Tops Coding Leaderboards at Fraction of Cost.\n\nDeepSeek AI just dropped an updated open model that climbed to the top of coding leaderboards, outpacing pricier rivals while running smoothly on home setups.\n\nReleased on October 17, DeepSeek-V4.1-Flash-1017 earned the #1 spot among open models on Arena.ai's Code Arena: WebDev leaderboard with 1,670 points, ranking #12 overall ahead of Claude Opus 5 (High) and close to GPT-6 Sol (Max)—all at one-tenth the cost of competitors like Kimi K3 (Max).\n\nThe 552B-parameter model, with MIT-licensed weights on Hugging Face, also hit #11 in Agent Arena, showing gains in success rates and reliability. Developers quickly optimized it for local use via Unsloth quantizations and DeepSeek's open-source DeepInfer framework, making frontier-level coding and agent performance accessible and affordable.", "body_zh": "DeepSeek-V4.1-Flash 登顶编程榜，成本仅为对手零头。\n\nDeepSeek 发布更新开源模型，冲上编程排行榜前列，表现压过更贵对手，且能在家用设备上流畅运行。\n\n10 月 17 日发布的 DeepSeek-V4.1-Flash-1017 在 Arena.ai 的 Code Arena: WebDev 开源模型榜夺得第一，得分 1670，总榜第 12，领先 Claude Opus 5（High），接近 GPT-6 Sol（Max），成本约为 Kimi K3（Max）等竞品的十分之一。该 5520 亿参数模型以 MIT 许可在 Hugging Face 开放权重，亦在 Agent Arena 排第 11，成功率与稳定性提升。", "url": "https://x.com/i/trending/2111803212139569662", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T11:32:56.000Z"}, {"id": "2112496630352281688", "domain": "科技", "title_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage", "title_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心", "hook_en": "Microsoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.", "hook_zh": "得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。", "summary_en": "Nscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity. UK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong. Nscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "summary_zh": "Nscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。Nscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "body_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage.\n\nMicrosoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.\n\nNscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity.\n\nUK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong.Nscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "body_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心。\n\n得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。\n\nNscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。\n\nNscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "url": "https://x.com/i/trending/2112496630352281688", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T10:54:58.000Z"}, {"id": "2112339042494742975", "domain": "科技", "title_en": "ChatGPT Slides Gains Real-Time Team Collaboration", "title_zh": "ChatGPT 幻灯片上线实时团队协作", "hook_en": "Imagine teams and AI agents editing the same presentation slide by slide, with comments flying in real time. OpenAI just made that a reality inside ChatGPT.", "hook_zh": "团队与 AI 智能体可逐页同编演示文稿、实时评论。OpenAI 已把这一能力带进 ChatGPT。", "summary_en": "OpenAI launched real-time collaboration for ChatGPT Slides, allowing Pro, Business, and Enterprise users to share decks, edit together, leave comments, and let ChatGPT apply feedback instantly. Features include direct tweaks to text, charts, images, and shapes, starting from conversations or files, with exports to PowerPoint or Google Slides. OpenAI's Platon Mazarakis shared pride in building a multiplayer editor from the start, while users like Emily Dahin called multi-human-agent work magical for future coworking. The rollout began around October 16, 2026, positioning ChatGPT as a strong rival to tools like Canva and Figma.", "summary_zh": "OpenAI 为 ChatGPT Slides 推出实时协作，Pro、Business 与 Enterprise 用户可共享幻灯片、一起编辑、留言，并由 ChatGPT 即时应用反馈。功能支持直接改文字、图表、图片与形状，可从对话或文件起步，并导出到 PowerPoint 或 Google 幻灯片。OpenAI 的 Platon Mazarakis 称从一开始就按多人编辑器来做；用户 Emily Dahin 则形容多人与智能体协作「神奇」，面向未来共事。功能约自 2026 年 10 月 16 日起推开，使 ChatGPT 更有力对标 Canva、Figma 等工具。", "body_en": "ChatGPT Slides Gains Real-Time Team Collaboration.\n\nImagine teams and AI agents editing the same presentation slide by slide, with comments flying in real time. OpenAI just made that a reality inside ChatGPT.\n\nOpenAI launched real-time collaboration for ChatGPT Slides, allowing Pro, Business, and Enterprise users to share decks, edit together, leave comments, and let ChatGPT apply feedback instantly.\n\nFeatures include direct tweaks to text, charts, images, and shapes, starting from conversations or files, with exports to PowerPoint or Google Slides. OpenAI's Platon Mazarakis shared pride in building a multiplayer editor from the start, while users like Emily Dahin called multi-human-agent work magical for future coworking. The rollout began around October 16, 2026, positioning ChatGPT as a strong rival to tools like Canva and Figma.", "body_zh": "ChatGPT 幻灯片上线实时团队协作。\n\n团队与 AI 智能体可逐页同编演示文稿、实时评论。OpenAI 已把这一能力带进 ChatGPT。\n\nOpenAI 为 ChatGPT Slides 推出实时协作，Pro、Business 与 Enterprise 用户可共享幻灯片、一起编辑、留言，并由 ChatGPT 即时应用反馈。功能支持直接改文字、图表、图片与形状，可从对话或文件起步，并导出到 PowerPoint 或 Google 幻灯片。\n\nOpenAI 的 Platon Mazarakis 称从一开始就按多人编辑器来做；用户 Emily Dahin 则形容多人与智能体协作「神奇」，面向未来共事。功能约自 2026 年 10 月 16 日起推开，使 ChatGPT 更有力对标 Canva、Figma 等工具。", "url": "https://x.com/i/trending/2112339042494742975", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-20T00:30:15.000Z"}, {"id": "2112281282239664552", "domain": "科技", "title_en": "NVIDIA Runs Record 104-Qubit Quantum Simulation on JUPITER Supercomputer", "title_zh": "英伟达在 JUPITER 超算上完成创纪录 104 量子比特模拟", "hook_en": "NVIDIA researchers pushed classical computing to mimic a fault-tolerant quantum system with 104 qubits—the largest simulation yet—using thousands of GPUs in Germany.", "hook_zh": "英伟达研究人员用德国数千块 GPU，推动经典计算模拟容错量子系统，达 104 量子比特——迄今最大规模。", "summary_en": "On Europe’s JUPITER supercomputer at the Jülich Supercomputing Centre, NVIDIA simulated a 104-qubit fault-tolerant quantum processor with 8,192 GH200 GPUs, including realistic hardware noise that past efforts overlooked. The simulation validated magic state cultivation, a method that slashes physical qubit needs by about 90 percent, guiding error mitigation for drug discovery, financial modeling, and materials science. CEO Jensen Huang highlighted how such digital twins of factories will let workers design AI cars and robotic plants virtually first. This bridges GPU simulations with real quantum hardware, de-risking development and speeding practical machines.", "summary_zh": "在于利希超算中心的欧洲 JUPITER 超算上，英伟达用 8192 块 GH200 GPU 模拟了 104 量子比特容错量子处理器，并纳入以往常被忽略的真实硬件噪声。模拟验证了「魔法态培育」方法，可将物理量子比特需求削减约 90%，为药物发现、金融建模与材料科学的误差缓解提供指引。CEO 黄仁勋强调，此类工厂数字孪生可让工人先虚拟设计 AI 汽车与机器人产线。此举衔接 GPU 模拟与真实量子硬件，降低开发风险并加速实用化。", "body_en": "NVIDIA Runs Record 104-Qubit Quantum Simulation on JUPITER Supercomputer.\n\nNVIDIA researchers pushed classical computing to mimic a fault-tolerant quantum system with 104 qubits—the largest simulation yet—using thousands of GPUs in Germany.\n\nOn Europe’s JUPITER supercomputer at the Jülich Supercomputing Centre, NVIDIA simulated a 104-qubit fault-tolerant quantum processor with 8,192 GH200 GPUs, including realistic hardware noise that past efforts overlooked.\n\nThe simulation validated magic state cultivation, a method that slashes physical qubit needs by about 90 percent, guiding error mitigation for drug discovery, financial modeling, and materials science. CEO Jensen Huang highlighted how such digital twins of factories will let workers design AI cars and robotic plants virtually first.This bridges GPU simulations with real quantum hardware, de-risking development and speeding practical machines.", "body_zh": "英伟达在 JUPITER 超算上完成创纪录 104 量子比特模拟。\n\n英伟达研究人员用德国数千块 GPU，推动经典计算模拟容错量子系统，达 104 量子比特——迄今最大规模。\n\n在于利希超算中心的欧洲 JUPITER 超算上，英伟达用 8192 块 GH200 GPU 模拟了 104 量子比特容错量子处理器，并纳入以往常被忽略的真实硬件噪声。模拟验证了「魔法态培育」方法，可将物理量子比特需求削减约 90%，为药物发现、金融建模与材料科学的误差缓解提供指引。\n\nCEO 黄仁勋强调，此类工厂数字孪生可让工人先虚拟设计 AI 汽车与机器人产线。此举衔接 GPU 模拟与真实量子硬件，降低开发风险并加速实用化。", "url": "https://x.com/i/trending/2112281282239664552", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-19T20:43:59.000Z"}, {"id": "2112190704650748351", "domain": "科技", "title_en": "Tenstorrent Raises $1.5 Billion at $6.2 Billion Valuation", "title_zh": "Tenstorrent 融资 15 亿美元，估值升至 62 亿美元", "hook_en": "Tenstorrent's CEO Jim Keller summed up their edge simply: 'We built one architecture and sell it at every size.' The startup just backed that vision with a massive funding round.", "hook_zh": "CEO Jim Keller 称优势很简单：「我们做一套架构，按各种规模卖。」本轮大额融资为这一愿景加油。", "summary_en": "The AI chip company, founded in Toronto and now in Santa Clara, California, secured $1.5 billion in Series E funding led by Trace Capital and Innovation X, boosting its valuation from $2.6 billion to $6.2 billion. Investors like ARK Invest, Fidelity, and Tether joined in to fuel volume production of Galaxy servers, which pack dozens of RISC-V AI chips for running open-weight models in chatbots and video tools. Tenstorrent positions its scalable, open hardware as a flexible alternative to Nvidia dominance, with plans to license designs to partners including Samsung and LG. Earlier takeover interest from Intel and Qualcomm was passed up to stay independent.", "summary_zh": "这家源自多伦多、现总部位于加州圣克拉拉的 AI 芯片公司完成由 Trace Capital 与 Innovation X 领投的 E 轮 15 亿美元融资，估值由 26 亿升至 62 亿美元。ARK、Fidelity、Tether 等跟投，用于 Galaxy 服务器量产——机内可装数十颗 RISC-V AI 芯片，服务聊天机器人与视频工具中的开源权重模型。公司将可扩展开源硬件定位为英伟达之外的灵活选项，并计划向三星、LG 等授权设计；此前曾拒绝英特尔与高通收购意向以保持独立。", "body_en": "Tenstorrent Raises $1.5 Billion at $6.2 Billion Valuation.\n\nTenstorrent's CEO Jim Keller summed up their edge simply: 'We built one architecture and sell it at every size.' The startup just backed that vision with a massive funding round.\n\nThe AI chip company, founded in Toronto and now in Santa Clara, California, secured $1.5 billion in Series E funding led by Trace Capital and Innovation X, boosting its valuation from $2.6 billion to $6.2 billion.\n\nInvestors like ARK Invest, Fidelity, and Tether joined in to fuel volume production of Galaxy servers, which pack dozens of RISC-V AI chips for running open-weight models in chatbots and video tools. Tenstorrent positions its scalable, open hardware as a flexible alternative to Nvidia dominance, with plans to license designs to partners including Samsung and LG.Earlier takeover interest from Intel and Qualcomm was passed up to stay independent.", "body_zh": "Tenstorrent 融资 15 亿美元，估值升至 62 亿美元。\n\nCEO Jim Keller 称优势很简单：「我们做一套架构，按各种规模卖。」本轮大额融资为这一愿景加油。\n\n这家源自多伦多、现总部位于加州圣克拉拉的 AI 芯片公司完成由 Trace Capital 与 Innovation X 领投的 E 轮 15 亿美元融资，估值由 26 亿升至 62 亿美元。ARK、Fidelity、Tether 等跟投，用于 Galaxy 服务器量产——机内可装数十颗 RISC-V AI 芯片，服务聊天机器人与视频工具中的开源权重模型。\n\n公司将可扩展开源硬件定位为英伟达之外的灵活选项，并计划向三星、LG 等授权设计；此前曾拒绝英特尔与高通收购意向以保持独立。", "url": "https://x.com/i/trending/2112190704650748351", "category": "News", "topics": ["Technology", "Business & Finance", "AI"], "updated_at": "2026-10-19T19:40:19.000Z"}, {"id": "2112474388268249592", "domain": "商业", "title_en": "JPMorgan Deposits $38 Million Toward Nigeria Merchant Banking License", "title_zh": "摩根大通存入约 3800 万美元，推进尼日利亚商人银行牌照", "hook_en": "JPMorgan Chase just took a big step in Nigeria by depositing 50 billion naira with the central bank—a move that could unlock new services for big businesses there.", "hook_zh": "摩根大通向尼日利亚央行存入 500 亿奈拉，向为大企业拓展新服务迈出关键一步。", "summary_en": "The deposit meets a key capital requirement under Nigeria's banking rules, paving the way for a full merchant banking license that would let JPMorgan expand into corporate lending, trade finance, and capital markets. The bank already advises on major deals from its Lagos office and could get approval by late 2026 or early 2027, though nothing is guaranteed. Nigerians are split: some see it as a boost for investment and jobs in capital markets, while others wonder how it helps everyday people amid poverty, noting it targets corporations rather than retail customers.", "summary_zh": "该存款满足尼日利亚银行业规则下的重要资本要求，为完整商人银行牌照铺路，使摩根大通可扩展公司贷款、贸易融资与资本市场业务。银行已从拉各斯办公室顾问重大交易，或于 2026 年底至 2027 年初获批，但并无保证。尼日利亚舆论分化：有人视为对投资与资本市场就业的提振，也有人质疑在贫困背景下对普通人帮助有限，指出其面向企业而非零售客户。", "body_en": "JPMorgan Deposits $38 Million Toward Nigeria Merchant Banking License.\n\nJPMorgan Chase just took a big step in Nigeria by depositing 50 billion naira with the central bank—a move that could unlock new services for big businesses there.\n\nThe deposit meets a key capital requirement under Nigeria's banking rules, paving the way for a full merchant banking license that would let JPMorgan expand into corporate lending, trade finance, and capital markets.\n\nThe bank already advises on major deals from its Lagos office and could get approval by late 2026 or early 2027, though nothing is guaranteed. Nigerians are split: some see it as a boost for investment and jobs in capital markets, while others wonder how it helps everyday people amid poverty, noting it targets corporations rather than retail customers.", "body_zh": "摩根大通存入约 3800 万美元，推进尼日利亚商人银行牌照。\n\n摩根大通向尼日利亚央行存入 500 亿奈拉，向为大企业拓展新服务迈出关键一步。\n\n该存款满足尼日利亚银行业规则下的重要资本要求，为完整商人银行牌照铺路，使摩根大通可扩展公司贷款、贸易融资与资本市场业务。银行已从拉各斯办公室顾问重大交易，或于 2026 年底至 2027 年初获批，但并无保证。\n\n尼日利亚舆论分化：有人视为对投资与资本市场就业的提振，也有人质疑在贫困背景下对普通人帮助有限，指出其面向企业而非零售客户。", "url": "https://x.com/i/trending/2112474388268249592", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T07:47:31.000Z"}, {"id": "2112771431633502285", "domain": "商业", "title_en": "Nifty Faces Selling Pressure After Holiday Gap-Up Open", "title_zh": "节后高开后 Nifty 遭遇抛压", "hook_en": "Nifty kicked off post-Dussehra trading with a hopeful gap-up, but sellers quickly stepped in, pulling it back amid choppy swings.", "hook_zh": "排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。", "summary_en": "The index closed Monday at 22,888.95, down 1.11 percent, then opened near 23,016 and hit a high of 23,120.90 before retreating toward 22,700-22,800. Technical traders like those using SweeGlu Elliott Wave spotted selling in the 23,060-23,175 range, eyeing downside to 22,560-22,478, while Ashish H Kyal noted volatility between key zones and Mahesh Khandelwal anticipated a reversal to 24,000-plus from a 22,500 base. Elevated Brent crude at $110 per barrel added inflation worries, as Jio Platforms IPO and Q2 earnings spurred selective IT buying amid broader profit booking.", "summary_zh": "指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "body_en": "Nifty Faces Selling Pressure After Holiday Gap-Up Open.\n\nNifty kicked off post-Dussehra trading with a hopeful gap-up, but sellers quickly stepped in, pulling it back amid choppy swings.\n\nThe index closed Monday at 22,888.95, down 1.11 percent, then opened near 23,016 and hit a high of 23,120.90 before retreating toward 22,700-22,800.\n\nTechnical traders like those using SweeGlu Elliott Wave spotted selling in the 23,060-23,175 range, eyeing downside to 22,560-22,478, while Ashish H Kyal noted volatility between key zones and Mahesh Khandelwal anticipated a reversal to 24,000-plus from a 22,500 base. Elevated Brent crude at $110 per barrel added inflation worries, as Jio Platforms IPO and Q2 earnings spurred selective IT buying amid broader profit booking.\n\nThe index closed Monday at 22,888.95, down 1.11 percent, then opened near 23,016 and hit a high of 23,120.90 before retreating toward 22,700-22,800. Technical traders like those using SweeGlu Elliott Wave spotted selling in the 23,060-23,175 range, eyeing downside to 22,560-22,478, while Ashish H Kyal noted volatility between key zones and Mahesh Khandelwal anticipated a reversal to 24,000-plus from a 22,500 base. Elevated Brent crude at $110 per barrel added inflation worries, as Jio Platforms IPO and Q2 earnings spurred selective IT buying amid broader profit booking.", "body_zh": "节后高开后 Nifty 遭遇抛压。\n\n排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。\n\n指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。\n\n布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "url": "https://x.com/i/trending/2112771431633502285", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T07:36:09.000Z"}, {"id": "2112796521959985524", "domain": "商业", "title_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals", "title_zh": "美国资本市场连创纪录：巨额IPO与债券齐发", "hook_en": "From SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.", "hook_zh": "从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。", "summary_en": "The Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile. SoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "summary_zh": "《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "body_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals.\n\nFrom SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.\n\nThe Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile.\n\nSoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.\n\nThe Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile. SoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "body_zh": "美国资本市场连创纪录：巨额IPO与债券齐发。\n\n从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。\n\n《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。\n\n观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "url": "https://x.com/i/trending/2112796521959985524", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T06:46:48.000Z"}, {"id": "2112795003680342391", "domain": "商业", "title_en": "S&P 500's Top 15 Stocks Hit Record 46.7% Share", "title_zh": "标普 500 前 15 大股权重创纪录达 46.7%", "hook_en": "A handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.", "hook_zh": "少数科技巨头主导整个标普 500，仅英伟达就占指数市值约 7.5%。买宽基基金的普通投资者未必意识到自己有多依赖这些龙头。", "summary_en": "The 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak. Nvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%. The top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs. While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "summary_zh": "标普 500 最大的 15 只股票合计占指数总市值创纪录的 46.7%，远超 2000 年互联网泡沫顶峰时的 27.2%。英伟达以 7.5% 居首，苹果 7.1%、Alphabet 5.9%、微软 5.6%，四家合计 26.1%。前五名市值相当于后 434 家之和，引发对热门指数基金与 ETF「分散」成色的质疑。有人强调龙头现金流强劲，也有人警告一旦放缓，被动组合将承压。", "body_en": "S&P 500's Top 15 Stocks Hit Record 46.7% Share.\n\nA handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.\n\nThe 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak.\n\nNvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%. The top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs.While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "body_zh": "标普 500 前 15 大股权重创纪录达 46.7%。\n\n少数科技巨头主导整个标普 500，仅英伟达就占指数市值约 7.5%。买宽基基金的普通投资者未必意识到自己有多依赖这些龙头。\n\n标普 500 最大的 15 只股票合计占指数总市值创纪录的 46.7%，远超 2000 年互联网泡沫顶峰时的 27.2%。英伟达以 7.5% 居首，苹果 7.1%、Alphabet 5.9%、微软 5.6%，四家合计 26.1%。\n\n前五名市值相当于后 434 家之和，引发对热门指数基金与 ETF「分散」成色的质疑。有人强调龙头现金流强劲，也有人警告一旦放缓，被动组合将承压。", "url": "https://x.com/i/trending/2112795003680342391", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-21T06:39:54.000Z"}, {"id": "2112410028070092998", "domain": "商业", "title_en": "Auto Loan Delinquencies Hit 14-Year Highs Amid Soaring Payments", "title_zh": "汽车贷款拖欠率创 14 年新高，月供飙升", "hook_en": "Families face $765 monthly car payments, stretching loans to eight years just to hold onto aging vehicles nearing 13 years old.", "hook_zh": "许多家庭月供约 765 美元，贷款拉长至八年，只为保住车龄将近 13 年的旧车。", "summary_en": "America's $1.7 trillion auto loan market shows rising stress, with one in five borrowers behind—the highest since 2010—and subprime delinquencies nearing 6 percent. New car payments have jumped from $550 in 2019, pushing buyers toward longer terms where over 30 percent of recent subprime loans won't end until cars are over 12 years old. Personal accounts highlight the pain, like $950 payments plus $350 insurance on top of maxed-out home equity and grocery bills, while older cars mean repossessions recover little of the debt. Though lenders have tightened standards, high balances and negative equity leave the market vulnerable.", "summary_zh": "美国约 1.7 万亿美元汽车贷款市场压力上升：五分之一借款人拖欠——为 2010 年以来最高，次级拖欠率接近 6%。新车月供已从 2019 年的约 550 美元抬升，买家倾向更长期限，逾 30% 近期次级贷款要到车龄超 12 年才还清。个人叙述可见负担之重，如月供 950 美元外加保险 350 美元，叠加已透支的房屋净值与食品开支；车龄偏高也使收回车辆难覆盖欠债。虽贷款机构已收紧标准，高余额与负权益仍令市场脆弱。", "body_en": "Auto Loan Delinquencies Hit 14-Year Highs Amid Soaring Payments.\n\nFamilies face $765 monthly car payments, stretching loans to eight years just to hold onto aging vehicles nearing 13 years old.\n\nAmerica's $1.7 trillion auto loan market shows rising stress, with one in five borrowers behind—the highest since 2010—and subprime delinquencies nearing 6 percent.\n\nNew car payments have jumped from $550 in 2019, pushing buyers toward longer terms where over 30 percent of recent subprime loans won't end until cars are over 12 years old. Personal accounts highlight the pain, like $950 payments plus $350 insurance on top of maxed-out home equity and grocery bills, while older cars mean repossessions recover little of the debt. Though lenders have tightened standards, high balances and negative equity leave the market vulnerable.", "body_zh": "汽车贷款拖欠率创 14 年新高，月供飙升。\n\n许多家庭月供约 765 美元，贷款拉长至八年，只为保住车龄将近 13 年的旧车。\n\n美国约 1.7 万亿美元汽车贷款市场压力上升：五分之一借款人拖欠——为 2010 年以来最高，次级拖欠率接近 6%。新车月供已从 2019 年的约 550 美元抬升，买家倾向更长期限，逾 30% 近期次级贷款要到车龄超 12 年才还清。\n\n个人叙述可见负担之重，如月供 950 美元外加保险 350 美元，叠加已透支的房屋净值与食品开支；车龄偏高也使收回车辆难覆盖欠债。虽贷款机构已收紧标准，高余额与负权益仍令市场脆弱。", "url": "https://x.com/i/trending/2112410028070092998", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T00:09:25.000Z"}, {"id": "2112266057628913774", "domain": "商业", "title_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade", "title_zh": "对冲基金十年最快速度抛售科技股", "hook_en": "Hedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.", "hook_zh": "对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。", "summary_en": "Through October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week. Semiconductors bore the brunt, making up 57% of U.S. tech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S. Treasurys amid a negative risk-appetite signal.", "summary_zh": "截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "body_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade.\n\nHedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.\n\nThrough October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week.Semiconductors bore the brunt, making up 57% of U.S.\n\ntech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S.Treasurys amid a negative risk-appetite signal.", "body_zh": "对冲基金十年最快速度抛售科技股。\n\n对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。\n\n截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。\n\n投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "url": "https://x.com/i/trending/2112266057628913774", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:07:55.000Z"}, {"id": "2111921386319208960", "domain": "商业", "title_en": "Bank of America Hit with $1.2 Billion Penalty for Anti-Money Laundering Failures", "title_zh": "美国银行因反洗钱失误被罚约 12 亿美元", "hook_en": "Treasury Secretary Scott Bessent made it clear: even giant banks must follow anti-money laundering rules, or face serious consequences.", "hook_zh": "财政部长斯科特·贝森特表态明确：即便是巨型银行，也必须遵守反洗钱规则，否则后果严重。", "summary_en": "On October 13, the U.S. Treasury Department fined Bank of America over $1.2 billion for willfully violating the Bank Secrecy Act, including failing to report suspicious activity on more than $5 billion in transactions tied to Chinese money laundering networks and southwest border illicit finance. Additional penalties came from the Office of the Comptroller of the Currency ($750 million, credited against the main fine) and the Office of Foreign Assets Control ($11.6 million) for sanctions breaches involving Iran, Russia, narcotics, and terrorism. Bank of America admitted the violations and pledged ongoing investments in compliance, while whistleblower Everett Stern and online voices called for individual prosecutions beyond the penalties.", "summary_zh": "10 月 13 日，美国财政部以故意违反《银行保密法》为由，对美国银行处以逾 12 亿美元罚款，包括未报告与中国洗钱网络及西南边境非法金融相关的逾 50 亿美元可疑交易。货币监理署另处 7.5 亿美元（可抵扣主罚），海外资产控制办公室因涉及伊朗、俄罗斯、毒品与恐怖主义的制裁违规再罚 1160 万美元。美国银行承认违规并承诺持续投入合规；举报人 Everett Stern 与网上舆论呼吁在罚款之外追究个人刑责。", "body_en": "Bank of America Hit with $1.2 Billion Penalty for Anti-Money Laundering Failures.\n\nTreasury Secretary Scott Bessent made it clear: even giant banks must follow anti-money laundering rules, or face serious consequences.\n\nOn October 13, the U.S.\n\nTreasury Department fined Bank of America over $1.2 billion for willfully violating the Bank Secrecy Act, including failing to report suspicious activity on more than $5 billion in transactions tied to Chinese money laundering networks and southwest border illicit finance. Additional penalties came from the Office of the Comptroller of the Currency ($750 million, credited against the main fine) and the Office of Foreign Assets Control ($11.6 million) for sanctions breaches involving Iran, Russia, narcotics, and terrorism. Bank of America admitted the violations and pledged ongoing investments in compliance, while whistleblower Everett Stern and online voices called for individual prosecutions beyond the penalties.", "body_zh": "美国银行因反洗钱失误被罚约 12 亿美元。\n\n财政部长斯科特·贝森特表态明确：即便是巨型银行，也必须遵守反洗钱规则，否则后果严重。\n\n10 月 13 日，美国财政部以故意违反《银行保密法》为由，对美国银行处以逾 12 亿美元罚款，包括未报告与中国洗钱网络及西南边境非法金融相关的逾 50 亿美元可疑交易。货币监理署另处 7.5 亿美元（可抵扣主罚），海外资产控制办公室因涉及伊朗、俄罗斯、毒品与恐怖主义的制裁违规再罚 1160 万美元。\n\n美国银行承认违规并承诺持续投入合规；举报人 Everett Stern 与网上舆论呼吁在罚款之外追究个人刑责。", "url": "https://x.com/i/trending/2111921386319208960", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:35:13.000Z"}, {"id": "2112507803138973871", "domain": "商业", "title_en": "Fed's $1.827 Billion Treasury Purchase Lifts Stocks and Crypto", "title_zh": "美联储买入约 18.27 亿美元国债，股市与加密货币上行", "hook_en": "US stocks and cryptocurrencies climbed Tuesday after the Federal Reserve bought $1.827 billion in Treasury bills, settling the same day and fueling trader excitement.", "hook_zh": "美联储买入约 18.27 亿美元国债并当日结算后，美股与加密货币周二走高，交易员情绪升温。", "summary_en": "The New York Fed's October 19 operation accepted $1.827 billion in 4-to-12-month Treasury bills, with settlement on October 20 as part of its regular secondary-market purchases to maintain banking reserves. Bitcoin rose about 1.35% to near $82,952, while the S&P 500 gained 0.65% to around 7,741, prompting posts calling the move 'massive' and bullish for risk assets. Traders highlighted the liquidity injection ahead of more scheduled purchases through November, though some noted it mostly replaces maturing holdings rather than expanding the balance sheet.", "summary_zh": "纽约联储 10 月 19 日操作接受约 18.27 亿美元、期限 4 至 12 个月的国债，于 10 月 20 日结算，属维持银行准备金的常规二级市场买入。比特币涨约 1.35% 至近 82952 美元，标普 500 涨约 0.65% 至约 7741 点，有帖文称操作为「大规模」且利好风险资产。交易员关注 11 月前更多既定买入带来的流动性，但也有人指出其主要是替换到期持仓，并非扩张资产负债表。", "body_en": "Fed's $1.827 Billion Treasury Purchase Lifts Stocks and Crypto.\n\nUS stocks and cryptocurrencies climbed Tuesday after the Federal Reserve bought $1.827 billion in Treasury bills, settling the same day and fueling trader excitement.\n\nThe New York Fed's October 19 operation accepted $1.827 billion in 4-to-12-month Treasury bills, with settlement on October 20 as part of its regular secondary-market purchases to maintain banking reserves.\n\nBitcoin rose about 1.35% to near $82,952, while the S&P 500 gained 0.65% to around 7,741, prompting posts calling the move 'massive' and bullish for risk assets. Traders highlighted the liquidity injection ahead of more scheduled purchases through November, though some noted it mostly replaces maturing holdings rather than expanding the balance sheet.\n\nThe New York Fed's October 19 operation accepted $1.827 billion in 4-to-12-month Treasury bills, with settlement on October 20 as part of its regular secondary-market purchases to maintain banking reserves. Bitcoin rose about 1.35% to near $82,952, while the S&P 500 gained 0.65% to around 7,741, prompting posts calling the move 'massive' and bullish for risk assets. Traders highlighted the liquidity injection ahead of more scheduled purchases through November, though some noted it mostly replaces maturing holdings rather than expanding the balance sheet.", "body_zh": "美联储买入约 18.27 亿美元国债，股市与加密货币上行。\n\n美联储买入约 18.27 亿美元国债并当日结算后，美股与加密货币周二走高，交易员情绪升温。\n\n纽约联储 10 月 19 日操作接受约 18.27 亿美元、期限 4 至 12 个月的国债，于 10 月 20 日结算，属维持银行准备金的常规二级市场买入。比特币涨约 1.35% 至近 82952 美元，标普 500 涨约 0.65% 至约 7741 点，有帖文称操作为「大规模」且利好风险资产。\n\n交易员关注 11 月前更多既定买入带来的流动性，但也有人指出其主要是替换到期持仓，并非扩张资产负债表。", "url": "https://x.com/i/trending/2112507803138973871", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:09:54.000Z"}, {"id": "2112566578415849780", "domain": "商业", "title_en": "Copper Supply Shortfall Looms from 2028 Amid Surging Demand", "title_zh": "报告预警：2028 年起铜供应或现巨大缺口", "hook_en": "Copper powers electric vehicles, grids, and AI data centers, but a new report warns of massive shortages starting in 2028 as supply struggles to keep up.", "hook_zh": "铜支撑电动车、电网与 AI 数据中心，新报告警告自 2028 年起供应难以跟上，短缺或很严重。", "summary_en": "BloombergNEF projects copper demand jumping 61% to 46 million tonnes by 2050, driven by electric transport needing 11.4 million tonnes, while supply deficits could hit 20 million tonnes without new investments. Chile, the top producer with 180 million tonnes in reserves, faces slumping output from aging mines, low ore grades, weather, and accidents—potentially dropping to 5 million tonnes by 2026, the lowest in over 20 years. Prices have surged to $14,500 per tonne, with banks forecasting further rises, though closing the gap requires $332 billion and 17 years per new mine.", "summary_zh": "BloombergNEF 预计到 2050 年铜需求将升 61% 至 4600 万吨，其中电动交通约需 1140 万吨；若无新投资，供应缺口可达 2000 万吨。最大生产国智利储量约 1.8 亿吨，却因矿山老化、品位下降、天气与事故导致产量下滑，2026 年或降至 500 万吨，为二十多年来最低。价格已涨至每吨约 1.45 万美元，银行预期续涨；但填补缺口约需 3320 亿美元，且一座新矿平均要 17 年。", "body_en": "Copper Supply Shortfall Looms from 2028 Amid Surging Demand.\n\nCopper powers electric vehicles, grids, and AI data centers, but a new report warns of massive shortages starting in 2028 as supply struggles to keep up.\n\nBloombergNEF projects copper demand jumping 61% to 46 million tonnes by 2050, driven by electric transport needing 11.4 million tonnes, while supply deficits could hit 20 million tonnes without new investments.\n\nChile, the top producer with 180 million tonnes in reserves, faces slumping output from aging mines, low ore grades, weather, and accidents—potentially dropping to 5 million tonnes by 2026, the lowest in over 20 years. Prices have surged to $14,500 per tonne, with banks forecasting further rises, though closing the gap requires $332 billion and 17 years per new mine.", "body_zh": "报告预警：2028 年起铜供应或现巨大缺口。\n\n铜支撑电动车、电网与 AI 数据中心，新报告警告自 2028 年起供应难以跟上，短缺或很严重。\n\nBloombergNEF 预计到 2050 年铜需求将升 61% 至 4600 万吨，其中电动交通约需 1140 万吨；若无新投资，供应缺口可达 2000 万吨。最大生产国智利储量约 1.8 亿吨，却因矿山老化、品位下降、天气与事故导致产量下滑，2026 年或降至 500 万吨，为二十多年来最低。\n\n价格已涨至每吨约 1.45 万美元，银行预期续涨；但填补缺口约需 3320 亿美元，且一座新矿平均要 17 年。", "url": "https://x.com/i/trending/2112566578415849780", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T15:35:06.000Z"}, {"id": "2112044241161433358", "domain": "商业", "title_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures", "title_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌", "hook_en": "Japanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.", "hook_zh": "日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。", "summary_en": "Japan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities. South Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers. A South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S. tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "summary_zh": "日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "body_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures.\n\nJapanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.\n\nJapan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities.\n\nSouth Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers. A South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S.tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "body_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌。\n\n日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。\n\n日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。\n\n韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "url": "https://x.com/i/trending/2112044241161433358", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-20T12:59:35.000Z"}, {"id": "2112431560116826201", "domain": "商业", "title_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms", "title_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论", "hook_en": "Subhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.", "hook_zh": "前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。", "summary_en": "Garg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks. Critics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "summary_zh": "加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。IMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "body_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms.\n\nSubhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.\n\nGarg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks.\n\nCritics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "body_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论。\n\n前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。\n\n加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。\n\nIMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "url": "https://x.com/i/trending/2112431560116826201", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T06:36:16.000Z"}, {"id": "2112193213931102362", "domain": "商业", "title_en": "Homebuilder Sentiment Hits 14-Year Low Amid High Rates and Costs", "title_zh": "美国建商信心跌至 14 年低点，高利率与成本承压", "hook_en": "Homebuilders are feeling the squeeze like never before, with sentiment dropping to its weakest since 2012 as mortgage rates top 7 percent.", "hook_zh": "建商感受空前挤压：抵押贷款利率站上 7%，信心跌至 2012 年以来最弱。", "summary_en": "The National Association of Home Builders/Wells Fargo Housing Market Index fell to 29 in October, missing economist expectations and marking 30 straight months below the neutral 50 level. All components declined, including buyer traffic at a dismal 18, prompting a record 43 percent of builders to cut prices by an average of 6 percent while 65 percent offered incentives like rate buydowns. Higher material, labor, and energy costs, plus rates averaging 7.40 percent, are keeping buyers away, though the discounts give some negotiating power despite strained affordability.", "summary_zh": "全美住宅建筑商协会/富国银行住房市场指数 10 月降至 29，不及经济学家预期，并连续 30 个月低于荣枯线 50。各项分项均下滑，购房客流仅 18；创纪录的 43% 建商平均降价 6%，65% 提供利率补贴等激励。材料、劳动力与能源成本走高，利率均值约 7.40%，令买家却步；虽折扣带来一定议价空间，可负担性依然紧张。", "body_en": "Homebuilder Sentiment Hits 14-Year Low Amid High Rates and Costs.\n\nHomebuilders are feeling the squeeze like never before, with sentiment dropping to its weakest since 2012 as mortgage rates top 7 percent.\n\nThe National Association of Home Builders/Wells Fargo Housing Market Index fell to 29 in October, missing economist expectations and marking 30 straight months below the neutral 50 level.\n\nAll components declined, including buyer traffic at a dismal 18, prompting a record 43 percent of builders to cut prices by an average of 6 percent while 65 percent offered incentives like rate buydowns. Higher material, labor, and energy costs, plus rates averaging 7.40 percent, are keeping buyers away, though the discounts give some negotiating power despite strained affordability.\n\nThe National Association of Home Builders/Wells Fargo Housing Market Index fell to 29 in October, missing economist expectations and marking 30 straight months below the neutral 50 level. All components declined, including buyer traffic at a dismal 18, prompting a record 43 percent of builders to cut prices by an average of 6 percent while 65 percent offered incentives like rate buydowns. Higher material, labor, and energy costs, plus rates averaging 7.40 percent, are keeping buyers away, though the discounts give some negotiating power despite strained affordability.", "body_zh": "美国建商信心跌至 14 年低点，高利率与成本承压。\n\n建商感受空前挤压：抵押贷款利率站上 7%，信心跌至 2012 年以来最弱。\n\n全美住宅建筑商协会/富国银行住房市场指数 10 月降至 29，不及经济学家预期，并连续 30 个月低于荣枯线 50。各项分项均下滑，购房客流仅 18；创纪录的 43% 建商平均降价 6%，65% 提供利率补贴等激励。\n\n材料、劳动力与能源成本走高，利率均值约 7.40%，令买家却步；虽折扣带来一定议价空间，可负担性依然紧张。", "url": "https://x.com/i/trending/2112193213931102362", "category": "News", "topics": ["Business & Finance", "Real Estate"], "updated_at": "2026-10-19T21:30:31.000Z"}, {"id": "2112234396476477579", "domain": "商业", "title_en": "Nigeria's Central Bank Reforms Steady Economy Amid Trade-offs", "title_zh": "尼日利亚央行改革稳住经济，亦有取舍", "hook_en": "Economist John Olanipekun from Osun State breaks down how Nigeria's central bank turned tough reforms into real gains for everyday people.", "hook_zh": "奥孙州经济学家约翰·奥拉尼佩昆拆解尼日利亚央行如何把艰难改革转化为普通人可感的收获。", "summary_en": "Since 2023, Nigeria ended petrol subsidies, freed its foreign-exchange market, and stopped central bank deficit financing, sparking higher inflation over 30 percent and a weaker naira. The Central Bank raised its policy rate sharply to 27.5 percent and kept cash reserves at 45 percent, bringing inflation down to 15.4 percent, reserves above $50 billion, a steadier currency, and growth near 4 percent. Olanipekun explains that central banks shape bread prices, bus fares, and job chances through tools like interest rates, balancing stable prices against credit and employment risks—no easy choices.", "summary_zh": "自 2023 年起，尼日利亚取消燃油补贴、放开外汇市场并停止央行赤字融资，一度推高通胀逾 30%、奈拉走弱。央行将政策利率大幅提至 27.5%，并维持 45% 现金准备金，使通胀回落至 15.4%，外汇储备逾 500 亿美元，汇率更稳，增长约 4%。奥拉尼佩昆指出，央行通过利率等工具影响面包价格、公交票价与就业机会，需在物价稳定与信贷、就业风险间权衡——没有轻松选项。", "body_en": "Nigeria's Central Bank Reforms Steady Economy Amid Trade-offs.\n\nEconomist John Olanipekun from Osun State breaks down how Nigeria's central bank turned tough reforms into real gains for everyday people.\n\nSince 2023, Nigeria ended petrol subsidies, freed its foreign-exchange market, and stopped central bank deficit financing, sparking higher inflation over 30 percent and a weaker naira.\n\nThe Central Bank raised its policy rate sharply to 27.5 percent and kept cash reserves at 45 percent, bringing inflation down to 15.4 percent, reserves above $50 billion, a steadier currency, and growth near 4 percent. Olanipekun explains that central banks shape bread prices, bus fares, and job chances through tools like interest rates, balancing stable prices against credit and employment risks—no easy choices.\n\nSince 2023, Nigeria ended petrol subsidies, freed its foreign-exchange market, and stopped central bank deficit financing, sparking higher inflation over 30 percent and a weaker naira. The Central Bank raised its policy rate sharply to 27.5 percent and kept cash reserves at 45 percent, bringing inflation down to 15.4 percent, reserves above $50 billion, a steadier currency, and growth near 4 percent. Olanipekun explains that central banks shape bread prices, bus fares, and job chances through tools like interest rates, balancing stable prices against credit and employment risks—no easy choices.", "body_zh": "尼日利亚央行改革稳住经济，亦有取舍。\n\n奥孙州经济学家约翰·奥拉尼佩昆拆解尼日利亚央行如何把艰难改革转化为普通人可感的收获。\n\n自 2023 年起，尼日利亚取消燃油补贴、放开外汇市场并停止央行赤字融资，一度推高通胀逾 30%、奈拉走弱。央行将政策利率大幅提至 27.5%，并维持 45% 现金准备金，使通胀回落至 15.4%，外汇储备逾 500 亿美元，汇率更稳，增长约 4%。\n\n奥拉尼佩昆指出，央行通过利率等工具影响面包价格、公交票价与就业机会，需在物价稳定与信贷、就业风险间权衡——没有轻松选项。", "url": "https://x.com/i/trending/2112234396476477579", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-19T20:43:40.000Z"}, {"id": "2112810342728323293", "domain": "中国", "title_en": "China Replaces Metro Ads with Portraits of Scientists", "title_zh": "中国多地用科学家肖像替换地铁商业广告", "hook_en": "Imagine stepping into a metro station where giant screens honor scientists like hybrid rice pioneer Yuan Longping instead of flashy ads. It's a simple swap that's getting people talking about role models.", "hook_zh": "走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。", "summary_en": "China has started replacing advertisements on large public screens in metro stations, malls, and other spaces with portraits of renowned scientists such as agronomist Yuan Longping, Nobel winner Tu Youyou for malaria treatment, rocket expert Qian Xuesen, and nuclear physicist Deng Jiaxian. The initiative began in Shandong province in August 2026 and spread to cities like Zhengzhou and Chongqing, especially around national holidays, with businesses voluntarily dedicating the space to celebrate scientific achievements and inspire the next generation. Videos of these displays have sparked online conversations in places like India, where some contrast it with local public messaging and call for emulating the focus on innovation over commercial noise.", "summary_zh": "中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "body_en": "China Replaces Metro Ads with Portraits of Scientists.\n\nImagine stepping into a metro station where giant screens honor scientists like hybrid rice pioneer Yuan Longping instead of flashy ads. It's a simple swap that's getting people talking about role models.\n\nChina has started replacing advertisements on large public screens in metro stations, malls, and other spaces with portraits of renowned scientists such as agronomist Yuan Longping, Nobel winner Tu Youyou for malaria treatment, rocket expert Qian Xuesen, and nuclear physicist Deng Jiaxian.\n\nThe initiative began in Shandong province in August 2026 and spread to cities like Zhengzhou and Chongqing, especially around national holidays, with businesses voluntarily dedicating the space to celebrate scientific achievements and inspire the next generation. Videos of these displays have sparked online conversations in places like India, where some contrast it with local public messaging and call for emulating the focus on innovation over commercial noise.", "body_zh": "中国多地用科学家肖像替换地铁商业广告。\n\n走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。\n\n中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。\n\n相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "url": "https://x.com/i/trending/2112810342728323293", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T07:40:42.000Z"}, {"id": "2112121751069176000", "domain": "中国", "title_en": "India-New Zealand Free Trade Agreement Takes Effect with JCB Export Milestone", "title_zh": "印新自贸协定生效，印度制造挖掘机首批运往新西兰", "hook_en": "Union Minister Piyush Goyal flagged off the first 'Made in India' JCB excavator from Pune to New Zealand, a perfect symbol of the new trade era just hours before the deal activated.", "hook_zh": "印度部长戈亚尔为浦那产 JCB 挖掘机发往新西兰剪彩，恰逢协定生效前夕。", "summary_en": "The India-New Zealand Free Trade Agreement went live on October 20, 2026, giving 100 percent of Indian exports duty-free access to New Zealand while opening reduced-tariff paths for Kiwi businesses to over a billion Indian customers. New Zealand Prime Minister Christopher Luxon noted it will create jobs and higher wages back home, with tariff quotas protecting Indian farmers from imports like apples and kiwifruit. Leaders aim to double bilateral trade, attract $20 billion in Kiwi investment over 15 years, and provide 5,000 work visas for skilled Indians in IT and healthcare.", "summary_zh": "印度—新西兰自由贸易协定于 2026 年 10 月 20 日生效：印度对新能源出口享 100% 零关税准入，新西兰企业亦获得面向逾十亿印度消费者的降税通道。新西兰总理拉克森称将创造就业与更高工资；关税配额保护印度农民免受苹果、奇异果等进口冲击。双方目标是双边贸易翻倍，15 年内吸引 200 亿美元新西兰投资，并为 IT、医疗等技能人才提供 5000 个工作签证。", "body_en": "India-New Zealand Free Trade Agreement Takes Effect with JCB Export Milestone.\n\nUnion Minister Piyush Goyal flagged off the first 'Made in India' JCB excavator from Pune to New Zealand, a perfect symbol of the new trade era just hours before the deal activated.\n\nThe India-New Zealand Free Trade Agreement went live on October 20, 2026, giving 100 percent of Indian exports duty-free access to New Zealand while opening reduced-tariff paths for Kiwi businesses to over a billion Indian customers.\n\nNew Zealand Prime Minister Christopher Luxon noted it will create jobs and higher wages back home, with tariff quotas protecting Indian farmers from imports like apples and kiwifruit. Leaders aim to double bilateral trade, attract $20 billion in Kiwi investment over 15 years, and provide 5,000 work visas for skilled Indians in IT and healthcare.", "body_zh": "印新自贸协定生效，印度制造挖掘机首批运往新西兰。\n\n印度部长戈亚尔为浦那产 JCB 挖掘机发往新西兰剪彩，恰逢协定生效前夕。\n\n印度—新西兰自由贸易协定于 2026 年 10 月 20 日生效：印度对新能源出口享 100% 零关税准入，新西兰企业亦获得面向逾十亿印度消费者的降税通道。新西兰总理拉克森称将创造就业与更高工资；关税配额保护印度农民免受苹果、奇异果等进口冲击。\n\n双方目标是双边贸易翻倍，15 年内吸引 200 亿美元新西兰投资，并为 IT、医疗等技能人才提供 5000 个工作签证。", "url": "https://x.com/i/trending/2112121751069176000", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T05:34:28.000Z"}, {"id": "2112525483875217802", "domain": "中国", "title_en": "Apple Commits $100 Million to Pennsylvania Titanium for iPhone Duo", "title_zh": "苹果向宾州钛材商承诺最高 1 亿美元，供折叠 iPhone", "hook_en": "A family-owned titanium firm in Pennsylvania just landed a game-changing deal with Apple, supplying metal for the upcoming foldable iPhone Duo.", "hook_zh": "一家宾夕法尼亚家族企业正为苹果即将推出的折叠 iPhone 锻造钛材。", "summary_en": "Apple announced it will buy up to $100 million of titanium over three years from Perryman Company in Houston, Pennsylvania, for the grade 5 titanium enclosure in its first foldable iPhone Duo and other products. The deal, part of Apple's $600 billion U.S. manufacturing push, also expands partnerships like one with Delaware's Qnity Electronics for iPhone 18 Pro camera films. Nearly 100 components for these devices now come from suppliers across more than a dozen states, with Apple leaders crediting the partners for making the innovations possible. Supporters hailed it as proof of returning American manufacturing strength.", "summary_zh": "苹果三年内最高投入 1 亿美元，向 Perryman 公司采购含 80% 再生料的 5 级钛，用于 iPhone Duo 等产品。", "body_en": "Apple Commits $100 Million to Pennsylvania Titanium for iPhone Duo.\n\nA family-owned titanium firm in Pennsylvania just landed a game-changing deal with Apple, supplying metal for the upcoming foldable iPhone Duo.\n\nApple announced it will buy up to $100 million of titanium over three years from Perryman Company in Houston, Pennsylvania, for the grade 5 titanium enclosure in its first foldable iPhone Duo and other products.The deal, part of Apple's $600 billion U.S.\n\nmanufacturing push, also expands partnerships like one with Delaware's Qnity Electronics for iPhone 18 Pro camera films. Nearly 100 components for these devices now come from suppliers across more than a dozen states, with Apple leaders crediting the partners for making the innovations possible.Supporters hailed it as proof of returning American manufacturing strength.", "body_zh": "苹果向宾州钛材商承诺最高 1 亿美元，供折叠 iPhone。\n\n一家宾夕法尼亚家族企业正为苹果即将推出的折叠 iPhone 锻造钛材。\n\n苹果三年内最高投入 1 亿美元，向 Perryman 公司采购含 80% 再生料的 5 级钛，用于 iPhone Duo 等产品。\n\n综合以上信息，苹果向宾州钛材商承诺最高 1 亿美元，供折叠 iPhone一事持续引发关注。", "url": "https://x.com/i/trending/2112525483875217802", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T03:54:25.000Z"}, {"id": "2112405151768100963", "domain": "中国", "title_en": "Philippine Senators Push to Expel Chinese Ambassador Over Threatening Remarks", "title_zh": "菲律宾参议员推动驱逐中国大使", "hook_en": "Chinese Ambassador Jing Quan boasted that China could 'easily win' any conflict with the Philippines, igniting calls from senators to send him packing.", "hook_zh": "中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。", "summary_en": "Senators Risa Hontiveros and Erwin Tulfo filed resolutions on October 20 and the day before, urging President Marcos to declare Ambassador Jing persona non grata or request his recall from Beijing. The remarks responded to Defense Secretary Gilberto Teodoro Jr. labeling China a regional troublemaker, prompting the Chinese Embassy's taunting social media posts like 'You are now on the list' targeting critics. The Department of Foreign Affairs summoned Jing on October 19, calling his words a provocative threat amid ongoing West Philippine Sea tensions, though Marcos prefers diplomatic talks over expulsion.", "summary_zh": "参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。", "body_en": "Philippine Senators Push to Expel Chinese Ambassador Over Threatening Remarks.\n\nChinese Ambassador Jing Quan boasted that China could 'easily win' any conflict with the Philippines, igniting calls from senators to send him packing.\n\nSenators Risa Hontiveros and Erwin Tulfo filed resolutions on October 20 and the day before, urging President Marcos to declare Ambassador Jing persona non grata or request his recall from Beijing.The remarks responded to Defense Secretary Gilberto Teodoro Jr.\n\nlabeling China a regional troublemaker, prompting the Chinese Embassy's taunting social media posts like 'You are now on the list' targeting critics. The Department of Foreign Affairs summoned Jing on October 19, calling his words a provocative threat amid ongoing West Philippine Sea tensions, though Marcos prefers diplomatic talks over expulsion.", "body_zh": "菲律宾参议员推动驱逐中国大使。\n\n中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。\n\n参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。\n\n外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。", "url": "https://x.com/i/trending/2112405151768100963", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T20:16:46.000Z"}, {"id": "2112161836116132305", "domain": "中国", "title_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects", "title_zh": "中国限制全断面掘进机出口，印度基建承压", "hook_en": "India's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.", "hook_zh": "印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。", "summary_en": "China's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks. The controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "summary_zh": "中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "body_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects.\n\nIndia's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.\n\nChina's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks.\n\nThe controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.\n\nChina's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks. The controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "body_zh": "中国限制全断面掘进机出口，印度基建承压。\n\n印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。\n\n中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。\n\n印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "url": "https://x.com/i/trending/2112161836116132305", "category": "News", "topics": ["News", "Business & Finance"], "updated_at": "2026-10-20T19:24:59.000Z"}, {"id": "2112572571275370804", "domain": "中国", "title_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs", "title_zh": "日本钇供应告急，寻求美方协助应对中国出口限制", "hook_en": "Japan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.", "hook_zh": "用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。", "summary_en": "Yttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored. Japan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "summary_zh": "2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "body_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs.\n\nJapan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.\n\nYttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago.\n\nThe shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored.Japan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.\n\nYttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored. Japan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "body_zh": "日本钇供应告急，寻求美方协助应对中国出口限制。\n\n用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。\n\n2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。\n\n日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "url": "https://x.com/i/trending/2112572571275370804", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:24:35.000Z"}, {"id": "2112117626201600470", "domain": "中国", "title_en": "Rajnath Singh Addresses SCO Summit in Tajikistan on Development and Terrorism", "title_zh": "拉杰纳特·辛格在上合组织塔吉克斯坦峰会谈发展与反恐", "hook_en": "Rajnath Singh stepped off the plane in Dushanbe to a ceremonial welcome, ready to champion India's vision for progress and unity at the SCO heads meeting.", "hook_zh": "印度防长拉杰纳特·辛格抵达杜尚别接受仪式欢迎，准备在上合组织政府首脑会议上阐述印度的进步与团结愿景。", "summary_en": "India's Defence Minister Rajnath Singh attended the 25th SCO Council of Heads of Government meeting in Tajikistan on October 19-20, holding bilateral talks with Iran's Vice President, Tajikistan's Defence Minister, and Prime Minister to boost defence ties and cultural links. In his address, he showcased India's model of technology-driven development, clean energy, and women-led growth, while pushing the Chabahar port for connectivity and urging collective action against terrorism with no double standards—remarks made as Pakistan's Deputy PM sat nearby. The summit ended with a joint communiqué on trade, budgets, and a 2026-2030 action plan, highlighting India's commitment to regional peace and stability.", "summary_zh": "印度国防部长拉杰纳特·辛格于 10 月 19–20 日出席在塔吉克斯坦举行的第 25 次上合组织政府首脑理事会会议，并与伊朗副总统、塔吉克斯坦防长与总理举行双边会谈，以加强防务与人文联系。他在讲话中展示印度以技术驱动发展、清洁能源与妇女引领增长的模式，推动恰巴哈尔港连通，并敦促对恐怖主义采取无双重标准的集体行动——发言时巴基斯坦副总理亦在场。峰会发表经贸、预算与 2026–2030 行动计划等联合公报，凸显印度对地区和平稳定的承诺。", "body_en": "Rajnath Singh Addresses SCO Summit in Tajikistan on Development and Terrorism.\n\nRajnath Singh stepped off the plane in Dushanbe to a ceremonial welcome, ready to champion India's vision for progress and unity at the SCO heads meeting.\n\nIndia's Defence Minister Rajnath Singh attended the 25th SCO Council of Heads of Government meeting in Tajikistan on October 19-20, holding bilateral talks with Iran's Vice President, Tajikistan's Defence Minister, and Prime Minister to boost defence ties and cultural links.\n\nIn his address, he showcased India's model of technology-driven development, clean energy, and women-led growth, while pushing the Chabahar port for connectivity and urging collective action against terrorism with no double standards—remarks made as Pakistan's Deputy PM sat nearby. The summit ended with a joint communiqué on trade, budgets, and a 2026-2030 action plan, highlighting India's commitment to regional peace and stability.", "body_zh": "拉杰纳特·辛格在上合组织塔吉克斯坦峰会谈发展与反恐。\n\n印度防长拉杰纳特·辛格抵达杜尚别接受仪式欢迎，准备在上合组织政府首脑会议上阐述印度的进步与团结愿景。\n\n印度国防部长拉杰纳特·辛格于 10 月 19–20 日出席在塔吉克斯坦举行的第 25 次上合组织政府首脑理事会会议，并与伊朗副总统、塔吉克斯坦防长与总理举行双边会谈，以加强防务与人文联系。他在讲话中展示印度以技术驱动发展、清洁能源与妇女引领增长的模式，推动恰巴哈尔港连通，并敦促对恐怖主义采取无双重标准的集体行动——发言时巴基斯坦副总理亦在场。\n\n峰会发表经贸、预算与 2026–2030 行动计划等联合公报，凸显印度对地区和平稳定的承诺。", "url": "https://x.com/i/trending/2112117626201600470", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T18:26:45.000Z"}, {"id": "2112437946263474495", "domain": "中国", "title_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal", "title_zh": "中国跟踪靠近争议南沙礁盘的美舰", "hook_en": "Early Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.", "hook_zh": "周二早间，一艘美军濒海战斗舰驶入中方所称仙宾礁附近水域，北京派出力量抵近监控。", "summary_en": "China's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability. The Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "summary_zh": "中国人民解放军海军指责美舰「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。菲律宾反驳称该舰处于国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。事件发生在同礁附近近期船只擦碰之后，正值多国在南海存在重叠领土主张。", "body_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal.\n\nEarly Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.\n\nChina's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability.\n\nThe Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.\n\nChina's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability. The Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "body_zh": "中国跟踪靠近争议南沙礁盘的美舰。\n\n周二早间，一艘美军濒海战斗舰驶入中方所称仙宾礁附近水域，北京派出力量抵近监控。\n\n中国人民解放军海军指责美舰「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。菲律宾反驳称该舰处于国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。\n\n事件发生在同礁附近近期船只擦碰之后，正值多国在南海存在重叠领土主张。", "url": "https://x.com/i/trending/2112437946263474495", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T15:35:04.000Z"}, {"id": "2112538623471964597", "domain": "中国", "title_en": "USDA Confirms Major Soybean Export Sale to China", "title_zh": "美国农业部确认对华大豆大额出口销售", "hook_en": "Farmers and traders perked up Tuesday when the USDA announced a hefty private sale of U.S. soybeans to China—the first real sign of renewed buying after quiet months.", "hook_zh": "农业部宣布美国大豆对华私人大额成交，数月沉寂后首现明显恢复采购信号。", "summary_en": "Private exporters reported selling 612,000 metric tons of American soybeans to China for the 2026/27 marketing year, one of the largest single-day deals lately. Chinese customs data showed the first U.S. soybean arrivals in September at 360,878 tons, up from zero a year ago, though total imports fell 8% to 11.88 million tons with Brazil supplying most at 10.7 million. For January through September, U.S. exports to China dropped 34% year-over-year to 11.06 million tons, while Brazil's climbed 3.4% to 65.84 million—yet recent data points to U.S. rebounding amid improving trade conditions.", "summary_zh": "出口商报告向中国出售 61.2 万吨 2026/27 市场年美国大豆，为近期最大单日成交之一。中国海关显示 9 月首批美国大豆到港 36.0878 万吨（去年同期为零），但总进口仍降 8% 至 1188 万吨，巴西供应约 1070 万吨居首。1–9 月美国对华出口同比降 34% 至 1106 万吨，巴西升 3.4% 至 6584 万吨；近期数据则显示贸易条件改善下美国货源回升。", "body_en": "USDA Confirms Major Soybean Export Sale to China.\n\nFarmers and traders perked up Tuesday when the USDA announced a hefty private sale of U.S. soybeans to China—the first real sign of renewed buying after quiet months.\n\nPrivate exporters reported selling 612,000 metric tons of American soybeans to China for the 2026/27 marketing year, one of the largest single-day deals lately.Chinese customs data showed the first U.S.\n\nsoybean arrivals in September at 360,878 tons, up from zero a year ago, though total imports fell 8% to 11.88 million tons with Brazil supplying most at 10.7 million.For January through September, U.S. exports to China dropped 34% year-over-year to 11.06 million tons, while Brazil's climbed 3.4% to 65.84 million—yet recent data points to U.S.rebounding amid improving trade conditions.", "body_zh": "美国农业部确认对华大豆大额出口销售。\n\n农业部宣布美国大豆对华私人大额成交，数月沉寂后首现明显恢复采购信号。\n\n出口商报告向中国出售 61.2 万吨 2026/27 市场年美国大豆，为近期最大单日成交之一。中国海关显示 9 月首批美国大豆到港 36.0878 万吨（去年同期为零），但总进口仍降 8% 至 1188 万吨，巴西供应约 1070 万吨居首。\n\n1–9 月美国对华出口同比降 34% 至 1106 万吨，巴西升 3.4% 至 6584 万吨；近期数据则显示贸易条件改善下美国货源回升。", "url": "https://x.com/i/trending/2112538623471964597", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T13:42:34.000Z"}, {"id": "2112486884211650655", "domain": "中国", "title_en": "Sindh CM Secures 34 China Deals at Shanghai Conference", "title_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作", "hook_en": "Sindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.", "hook_zh": "信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。", "summary_en": "At the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province. The event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "summary_zh": "2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。支持者称这延续巴中建交 75 年的合作传统。", "body_en": "Sindh CM Secures 34 China Deals at Shanghai Conference.\n\nSindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.\n\nAt the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business.\n\nThese cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province. The event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "body_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作。\n\n信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。\n\n2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。\n\n支持者称这延续巴中建交 75 年的合作传统。", "url": "https://x.com/i/trending/2112486884211650655", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T13:25:56.000Z"}, {"id": "2112533926702936100", "domain": "中国", "title_en": "China's Philosophers Offer Fresh Take on AI and Humanity", "title_zh": "中国学者从人文传统重思 AI 与人性", "hook_en": "While Western worries center on super-smart machines outpacing us, Chinese thinkers flip the script to protect what makes us truly human.", "hook_zh": "西方忧虑超级智能超越人类时，中国思想者更强调守护人之为人的内核。", "summary_en": "Arnaud Bertrand's Substack explores how China's philosophers, sociologists, and ethicists view AI through traditions like Confucianism, emphasizing the heart-mind and benevolence over raw intelligence. Thinkers like Liu Yongmou warn against the 'machinization of humans'—technology eroding our inner qualities—while Zhao Tingyang cautions that aligning AI with human values might backfire. Drawing from ancient texts like the Zhuangzi, these ideas challenge Western fears and highlight overlooked questions as China leads in AI development.", "summary_zh": "Arnaud Bertrand 的文章梳理中国哲学家、社会学家与伦理学者如何以儒家等传统看 AI，重视「心」与仁，而非单纯智力。刘永谋等警示「人的机器化」——技术侵蚀内在品质；赵汀阳提醒让 AI 对齐人类价值也可能适得其反。借鉴《庄子》等典籍，这些观点挑战西方恐惧叙事，并在中国引领 AI 发展之际提出常被忽视的问题。", "body_en": "China's Philosophers Offer Fresh Take on AI and Humanity.\n\nWhile Western worries center on super-smart machines outpacing us, Chinese thinkers flip the script to protect what makes us truly human.\n\nArnaud Bertrand's Substack explores how China's philosophers, sociologists, and ethicists view AI through traditions like Confucianism, emphasizing the heart-mind and benevolence over raw intelligence.\n\nThinkers like Liu Yongmou warn against the 'machinization of humans'—technology eroding our inner qualities—while Zhao Tingyang cautions that aligning AI with human values might backfire. Drawing from ancient texts like the Zhuangzi, these ideas challenge Western fears and highlight overlooked questions as China leads in AI development.\n\nArnaud Bertrand's Substack explores how China's philosophers, sociologists, and ethicists view AI through traditions like Confucianism, emphasizing the heart-mind and benevolence over raw intelligence. Thinkers like Liu Yongmou warn against the 'machinization of humans'—technology eroding our inner qualities—while Zhao Tingyang cautions that aligning AI with human values might backfire. Drawing from ancient texts like the Zhuangzi, these ideas challenge Western fears and highlight overlooked questions as China leads in AI development.", "body_zh": "中国学者从人文传统重思 AI 与人性。\n\n西方忧虑超级智能超越人类时，中国思想者更强调守护人之为人的内核。\n\nArnaud Bertrand 的文章梳理中国哲学家、社会学家与伦理学者如何以儒家等传统看 AI，重视「心」与仁，而非单纯智力。刘永谋等警示「人的机器化」——技术侵蚀内在品质；赵汀阳提醒让 AI 对齐人类价值也可能适得其反。\n\n借鉴《庄子》等典籍，这些观点挑战西方恐惧叙事，并在中国引领 AI 发展之际提出常被忽视的问题。", "url": "https://x.com/i/trending/2112533926702936100", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T13:25:56.000Z"}, {"id": "2112022699237310708", "domain": "中国", "title_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery", "title_zh": "良渚论坛开幕：纪念遗址发现 90 周年", "hook_en": "Experts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.", "hook_zh": "近 60 国专家齐聚杭州，围绕约五千年历史的良渚遗址，把古代文明、现代技术与国际交流放在同一舞台。", "summary_en": "The fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming. Under the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "summary_zh": "第四届良渚论坛于 10 月 18–20 日在浙江举行，纪念列入联合国教科文组织名录的良渚遗址发现 90 周年——遗址见证早期发达社会与稻作农业。主题为「连接过去与未来」，活动包括论坛、艺术家展览、「一带一路」相关文创市集，以及博物馆用真实档案导览的 AI 眼镜。首次访华的美国考古学家称赞景色并希望研究遗址；澳大利亚策展人谈到古代良渚与今日杭州的关联；青年志愿者提供双语服务，各方呼吁加强全球遗产合作。", "body_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery.\n\nExperts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.\n\nThe fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming.\n\nUnder the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "body_zh": "良渚论坛开幕：纪念遗址发现 90 周年。\n\n近 60 国专家齐聚杭州，围绕约五千年历史的良渚遗址，把古代文明、现代技术与国际交流放在同一舞台。\n\n第四届良渚论坛于 10 月 18–20 日在浙江举行，纪念列入联合国教科文组织名录的良渚遗址发现 90 周年——遗址见证早期发达社会与稻作农业。主题为「连接过去与未来」，活动包括论坛、艺术家展览、「一带一路」相关文创市集，以及博物馆用真实档案导览的 AI 眼镜。\n\n首次访华的美国考古学家称赞景色并希望研究遗址；澳大利亚策展人谈到古代良渚与今日杭州的关联；青年志愿者提供双语服务，各方呼吁加强全球遗产合作。", "url": "https://x.com/i/trending/2112022699237310708", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T03:21:48.000Z"}, {"id": "2112244939484729640", "domain": "中国", "title_en": "DeepSeek and Huawei Team Up on AI Chips to Challenge Nvidia", "title_zh": "DeepSeek 与华为联手打造 AI 芯片挑战英伟达", "hook_en": "Huawei engineers have moved into DeepSeek's offices, working side-by-side to design chips that cut U.S. tech dependence.", "hook_zh": "华为工程师进驻 DeepSeek 办公区，并肩设计降低对美技术依赖的芯片。", "summary_en": "DeepSeek is partnering with Huawei, China's top chipmaker, to shape new AI processors and build alternatives to Nvidia's tools. They plan to use Huawei's Ascend 950DT chips for training by year's end and secure most of the Ascend 960DT supply next year. This builds on prior open-source work for Huawei's platform and reflects China's drive for a homegrown AI ecosystem, as Nvidia's China market share dips to 34 percent.", "summary_zh": "DeepSeek 正与中国龙头芯片企业华为合作，塑造新 AI 处理器并构建英伟达工具的替代方案。双方计划年底前用昇腾 950DT 训练，并争取明年大部分昇腾 960DT 供应。此举延续此前面向华为平台的开源协作，也反映中国打造本土 AI 生态的推动；英伟达在华份额已降至约 34%。", "body_en": "DeepSeek and Huawei Team Up on AI Chips to Challenge Nvidia.\n\nHuawei engineers have moved into DeepSeek's offices, working side-by-side to design chips that cut U.S. tech dependence.\n\nDeepSeek is partnering with Huawei, China's top chipmaker, to shape new AI processors and build alternatives to Nvidia's tools.They plan to use Huawei's Ascend 950DT chips for training by year's end and secure most of the Ascend 960DT supply next year.\n\nThis builds on prior open-source work for Huawei's platform and reflects China's drive for a homegrown AI ecosystem, as Nvidia's China market share dips to 34 percent.\n\nDeepSeek is partnering with Huawei, China's top chipmaker, to shape new AI processors and build alternatives to Nvidia's tools. They plan to use Huawei's Ascend 950DT chips for training by year's end and secure most of the Ascend 960DT supply next year. This builds on prior open-source work for Huawei's platform and reflects China's drive for a homegrown AI ecosystem, as Nvidia's China market share dips to 34 percent.", "body_zh": "DeepSeek 与华为联手打造 AI 芯片挑战英伟达。\n\n华为工程师进驻 DeepSeek 办公区，并肩设计降低对美技术依赖的芯片。\n\nDeepSeek 正与中国龙头芯片企业华为合作，塑造新 AI 处理器并构建英伟达工具的替代方案。双方计划年底前用昇腾 950DT 训练，并争取明年大部分昇腾 960DT 供应。\n\n此举延续此前面向华为平台的开源协作，也反映中国打造本土 AI 生态的推动；英伟达在华份额已降至约 34%。", "url": "https://x.com/i/trending/2112244939484729640", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-19T21:20:12.000Z"}, {"id": "2112290595213554074", "domain": "国际", "title_en": "Irish Lawmakers Clash Over Triple Lock Reform for Peacekeeping", "title_zh": "爱尔兰议员围绕维和「三重锁定」改革激烈交锋", "hook_en": "Taoiseach Micheál Martin fired back at critics with a sharp question: 'How dare you lecture me about Irish neutrality?' The heated Dáil exchange captured the deep divide over Ireland's military future.", "hook_zh": "总理米歇尔·马丁回击批评：「你凭什么教训我爱尔兰中立？」国会交锋凸显军方未来走向的深刻分歧。", "summary_en": "Government leaders are pushing to reform the Triple Lock, which currently requires UN Security Council, government, and Dáil approval for deploying more than 12 Irish troops on armed international missions. The change would drop the UN veto, allowing missions approved by groups like the EU or OSCE under the UN Charter, to prevent blocks by nations such as Russia or China. Opposition parties from Sinn Féin to People Before Profit call it an erosion of Ireland's cherished neutrality, demanding a referendum and decrying limited debate, while protests erupt with 'Save Neutrality' signs. The bill heads to a vote this week amid vows of resistance.", "summary_zh": "政府正推动改革「三重锁定」：目前派出逾 12 名爱尔兰军人参加武装国际任务需联合国安理会、政府与国会三重批准。改革拟取消联合国否决，允许在联合国宪章下由欧盟或欧安组织等批准的任务，以防俄中等国阻挠。新芬党至「利润面前的人民」等反对党称此侵蚀珍视的中立，要求公投并抱怨辩论不足；抗议者打出「保卫中立」标语。法案本周将付诸表决，反对声浪高涨。", "body_en": "Irish Lawmakers Clash Over Triple Lock Reform for Peacekeeping.\n\nTaoiseach Micheál Martin fired back at critics with a sharp question: 'How dare you lecture me about Irish neutrality?' The heated Dáil exchange captured the deep divide over Ireland's military future.\n\nGovernment leaders are pushing to reform the Triple Lock, which currently requires UN Security Council, government, and Dáil approval for deploying more than 12 Irish troops on armed international missions.\n\nThe change would drop the UN veto, allowing missions approved by groups like the EU or OSCE under the UN Charter, to prevent blocks by nations such as Russia or China. Opposition parties from Sinn Féin to People Before Profit call it an erosion of Ireland's cherished neutrality, demanding a referendum and decrying limited debate, while protests erupt with 'Save Neutrality' signs.The bill heads to a vote this week amid vows of resistance.", "body_zh": "爱尔兰议员围绕维和「三重锁定」改革激烈交锋。\n\n总理米歇尔·马丁回击批评：「你凭什么教训我爱尔兰中立？」国会交锋凸显军方未来走向的深刻分歧。\n\n政府正推动改革「三重锁定」：目前派出逾 12 名爱尔兰军人参加武装国际任务需联合国安理会、政府与国会三重批准。改革拟取消联合国否决，允许在联合国宪章下由欧盟或欧安组织等批准的任务，以防俄中等国阻挠。\n\n新芬党至「利润面前的人民」等反对党称此侵蚀珍视的中立，要求公投并抱怨辩论不足；抗议者打出「保卫中立」标语。法案本周将付诸表决，反对声浪高涨。", "url": "https://x.com/i/trending/2112290595213554074", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T03:31:29.000Z"}, {"id": "2112525487796805640", "domain": "国际", "title_en": "Turkey Submits Mecca Defense Pact with Saudi Arabia and Pakistan for Ratification", "title_zh": "土耳其提交与沙特、巴基斯坦的麦加防务协定供批准", "hook_en": "In the holy city of Mecca, leaders from Turkey, Saudi Arabia, and Pakistan signed a pact promising mutual defense—like one for all and all for one.", "hook_zh": "在圣城麦加，土耳其、沙特与巴基斯坦领导人签署互保协定——进攻一方即进攻全体。", "summary_en": "The Mecca Joint Defence Agreement, inked in August by Presidents Erdoğan, Crown Prince Mohammed bin Salman, and Prime Minister Shehbaz Sharif, commits the three nations to treat an attack on one as an attack on all. It includes weapons support, intelligence sharing, joint production, tech research, and military drills, overseen by a committee of their foreign and defense ministers for a 10-year term. Separately, Turkey's defense minister heads to Qatar on October 21 for a four-nation deal with Qatar, Pakistan, and Indonesia on defense industry cooperation, covering tech transfer, training, and joint weapons development described as the Muslim world's largest such effort. These steps aim to boost collective deterrence and regional stability amid security talks.", "summary_zh": "麦加联合防务协定由埃尔多安总统、王储穆罕默德·本·萨勒曼与谢巴兹·谢里夫总理于 8 月签署，三国承诺视对一方攻击为对全体攻击，涵盖武器支援、情报共享、联合生产、技术研发与军演，由外长与防长委员会监督，为期 10 年。另据悉土耳其防长 10 月 21 日赴卡塔尔，推进与卡塔尔、巴基斯坦、印尼的四国防务产业合作，涵盖技术转让、训练与联合武器研发，被描述为穆斯林世界规模最大的此类努力，旨在提升集体威慑与地区稳定。", "body_en": "Turkey Submits Mecca Defense Pact with Saudi Arabia and Pakistan for Ratification.\n\nIn the holy city of Mecca, leaders from Turkey, Saudi Arabia, and Pakistan signed a pact promising mutual defense—like one for all and all for one.\n\nThe Mecca Joint Defence Agreement, inked in August by Presidents Erdoğan, Crown Prince Mohammed bin Salman, and Prime Minister Shehbaz Sharif, commits the three nations to treat an attack on one as an attack on all.\n\nIt includes weapons support, intelligence sharing, joint production, tech research, and military drills, overseen by a committee of their foreign and defense ministers for a 10-year term. Separately, Turkey's defense minister heads to Qatar on October 21 for a four-nation deal with Qatar, Pakistan, and Indonesia on defense industry cooperation, covering tech transfer, training, and joint weapons development described as the Muslim world's largest such effort. These steps aim to boost collective deterrence and regional stability amid security talks.", "body_zh": "土耳其提交与沙特、巴基斯坦的麦加防务协定供批准。\n\n在圣城麦加，土耳其、沙特与巴基斯坦领导人签署互保协定——进攻一方即进攻全体。\n\n麦加联合防务协定由埃尔多安总统、王储穆罕默德·本·萨勒曼与谢巴兹·谢里夫总理于 8 月签署，三国承诺视对一方攻击为对全体攻击，涵盖武器支援、情报共享、联合生产、技术研发与军演，由外长与防长委员会监督，为期 10 年。另据悉土耳其防长 10 月 21 日赴卡塔尔，推进与卡塔尔、巴基斯坦、印尼的四国防务产业合作，涵盖技术转让、训练与联合武器研发，被描述为穆斯林世界规模最大的此类努力，旨在提升集体威慑与地区稳定。", "url": "https://x.com/i/trending/2112525487796805640", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T21:20:13.000Z"}, {"id": "2112442700796690870", "domain": "国际", "title_en": "Online Debate Heats Up Over Ukraine's Status as U.S. Ally", "title_zh": "网上热议：乌克兰算不算美国「盟友」", "hook_en": "Congresswoman Madeleine Dean called Ukraine a key ally amid Washington's cooling ties with Kyiv. Conservative voices fired back, questioning any formal bond.", "hook_zh": "众议员马德琳·迪安称乌克兰为关键盟友，时值华盛顿与基辅关系趋冷。保守派反驳：双方并无正式同盟纽带。", "summary_en": "The argument centers on whether Ukraine counts as a U.S. ally, with no mutual defense treaty, NATO membership, or Major Non-NATO Ally designation. Posts clash over history too: Ukraine inherited Soviet nukes in 1991, gave them up under the 1994 Budapest Memorandum for security promises from the U.S., U.K., and Russia—but those pledges didn't stop invasions in 2014 or 2022. Recent tensions spiked in mid-October 2026 when President Trump criticized Zelenskyy, eased Russia sanctions, and pushed for peace, cooling U.S.-Ukraine relations and fueling views of Ukraine as either a vital partner or a non-ally in a pricey proxy war.", "summary_zh": "争论焦点是乌克兰是否算美国盟友——并无共同防务条约、北约成员身份或「主要非北约盟友」指定。历史亦成焦点：乌克兰 1991 年继承苏联核弹，1994 年《布达佩斯备忘录》下弃核换取美英俄主权承诺，但承诺未能阻止 2014 与 2022 年入侵。2026 年 10 月中旬特朗普批评泽连斯基、放宽对俄制裁并推动和谈，美乌关系降温，助长「关键伙伴」与「昂贵代理人战争中的非盟友」两极看法。", "body_en": "Online Debate Heats Up Over Ukraine's Status as U.S. Ally.\n\nCongresswoman Madeleine Dean called Ukraine a key ally amid Washington's cooling ties with Kyiv. Conservative voices fired back, questioning any formal bond.\n\nThe argument centers on whether Ukraine counts as a U.S.ally, with no mutual defense treaty, NATO membership, or Major Non-NATO Ally designation.\n\nPosts clash over history too: Ukraine inherited Soviet nukes in 1991, gave them up under the 1994 Budapest Memorandum for security promises from the U.S., U.K., and Russia—but those pledges didn't stop invasions in 2014 or 2022. Recent tensions spiked in mid-October 2026 when President Trump criticized Zelenskyy, eased Russia sanctions, and pushed for peace, cooling U.S.-Ukraine relations and fueling views of Ukraine as either a vital partner or a non-ally in a pricey proxy war.", "body_zh": "网上热议：乌克兰算不算美国「盟友」。\n\n众议员马德琳·迪安称乌克兰为关键盟友，时值华盛顿与基辅关系趋冷。保守派反驳：双方并无正式同盟纽带。\n\n争论焦点是乌克兰是否算美国盟友——并无共同防务条约、北约成员身份或「主要非北约盟友」指定。历史亦成焦点：乌克兰 1991 年继承苏联核弹，1994 年《布达佩斯备忘录》下弃核换取美英俄主权承诺，但承诺未能阻止 2014 与 2022 年入侵。\n\n2026 年 10 月中旬特朗普批评泽连斯基、放宽对俄制裁并推动和谈，美乌关系降温，助长「关键伙伴」与「昂贵代理人战争中的非盟友」两极看法。", "url": "https://x.com/i/trending/2112442700796690870", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T20:56:58.000Z"}, {"id": "2112558002708648142", "domain": "国际", "title_en": "Zelensky's 2025 Warning on Russia Resurfaces Amid Skepticism", "title_zh": "泽连斯基 2025 年对俄警告旧片段再热传，质疑声四起", "hook_en": "A 2025 clip of Ukrainian President Volodymyr Zelensky warning that a U.S. NATO exit means certain Russian occupation of Europe has people online pushing back hard.", "hook_zh": "一段 2025 年泽连斯基警告「美国退出北约等于俄必占欧洲」的视频再度流传，网上反驳激烈。", "summary_en": "In a February 16, 2025, NBC Meet the Press interview, Zelensky told host Kristen Welker that European NATO forces lack enough brigades to match Russia's military, predicting a 100 percent risk of occupation starting with smaller ex-Soviet NATO states if the U.S. withdraws. The resurfaced excerpt drew skeptical reactions, with comments calling it 'bullshit,' pointing to supposed contradictions about Russia's struggles in Ukraine, and labeling it hyperbolic or a plea for more aid. The discussion highlights ongoing divides over Russian threats, NATO roles, and Western support for Ukraine as debates on assistance levels persist.", "summary_zh": "在 2025 年 2 月 16 日 NBC《Meet the Press》采访中，泽连斯基对主持人克里斯滕·韦尔克表示，欧洲北约部队旅级规模不足以匹敌俄军，若美国撤离，从前苏联地区较小北约成员国开始被占领的风险是「百分之百」。旧片段再传后招来怀疑评论，有人称「胡扯」，指俄在乌战场吃力等「矛盾」，或指其夸张、旨在索要更多援助。讨论凸显俄威胁、北约角色与西方援乌水平等持续分歧。", "body_en": "Zelensky's 2025 Warning on Russia Resurfaces Amid Skepticism.\n\nA 2025 clip of Ukrainian President Volodymyr Zelensky warning that a U.S. NATO exit means certain Russian occupation of Europe has people online pushing back hard.\n\nIn a February 16, 2025, NBC Meet the Press interview, Zelensky told host Kristen Welker that European NATO forces lack enough brigades to match Russia's military, predicting a 100 percent risk of occupation starting with smaller ex-Soviet NATO states if the U.S.withdraws.\n\nThe resurfaced excerpt drew skeptical reactions, with comments calling it 'bullshit,' pointing to supposed contradictions about Russia's struggles in Ukraine, and labeling it hyperbolic or a plea for more aid. The discussion highlights ongoing divides over Russian threats, NATO roles, and Western support for Ukraine as debates on assistance levels persist.", "body_zh": "泽连斯基 2025 年对俄警告旧片段再热传，质疑声四起。\n\n一段 2025 年泽连斯基警告「美国退出北约等于俄必占欧洲」的视频再度流传，网上反驳激烈。\n\n在 2025 年 2 月 16 日 NBC《Meet the Press》采访中，泽连斯基对主持人克里斯滕·韦尔克表示，欧洲北约部队旅级规模不足以匹敌俄军，若美国撤离，从前苏联地区较小北约成员国开始被占领的风险是「百分之百」。旧片段再传后招来怀疑评论，有人称「胡扯」，指俄在乌战场吃力等「矛盾」，或指其夸张、旨在索要更多援助。\n\n讨论凸显俄威胁、北约角色与西方援乌水平等持续分歧。", "url": "https://x.com/i/trending/2112558002708648142", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:59:26.000Z"}, {"id": "2112592169139855608", "domain": "国际", "title_en": "Hungary Blocks Ukraine and Moldova EU Accession Steps", "title_zh": "匈牙利阻挠乌克兰与摩尔多瓦入盟下一阶段谈判", "hook_en": "Just days after Ukraine passed a law protecting its Hungarian-speaking minority, Hungary halted the next phase of EU talks for both Ukraine and Moldova, leaving diplomats puzzled by the silence.", "hook_zh": "乌克兰刚通过保护匈牙利语少数族裔法律数日，匈牙利即叫停下乌、摩入盟下一阶段，令外交官困惑于其沉默。", "summary_en": "At a meeting of EU technical experts on October 20, Hungary objected to advancing the final two negotiating clusters on green agenda, sustainable connectivity, resources, agriculture, and cohesion, while the other 26 member states supported the move. This follows recent progress, including Ukraine's minority protections law on October 12 and a meeting between Prime Minister Péter Magyar and President Volodymyr Zelenskyy to reset ties, which allowed earlier clusters to open. The block revives questions about Hungary's stance on EU enlargement, as unanimity is required, and observers note frustration over the unexplained decision despite outreach efforts.", "summary_zh": "在 10 月 20 日欧盟技术专家会议上，匈牙利反对推进绿色议程、可持续互联、资源、农业与凝聚等最后两个谈判集群，其余 26 国支持。此前乌克兰 10 月 12 日通过少数族裔保护法，总理彼得·毛扎尔与泽连斯基会晤以重置关系，曾使更早集群得以开启。阻挠再度引发对匈牙利入盟立场的质疑：需全体一致，观察人士对在外联努力后仍无解释的决定感到沮丧。", "body_en": "Hungary Blocks Ukraine and Moldova EU Accession Steps.\n\nJust days after Ukraine passed a law protecting its Hungarian-speaking minority, Hungary halted the next phase of EU talks for both Ukraine and Moldova, leaving diplomats puzzled by the silence.\n\nAt a meeting of EU technical experts on October 20, Hungary objected to advancing the final two negotiating clusters on green agenda, sustainable connectivity, resources, agriculture, and cohesion, while the other 26 member states supported the move.\n\nThis follows recent progress, including Ukraine's minority protections law on October 12 and a meeting between Prime Minister Péter Magyar and President Volodymyr Zelenskyy to reset ties, which allowed earlier clusters to open. The block revives questions about Hungary's stance on EU enlargement, as unanimity is required, and observers note frustration over the unexplained decision despite outreach efforts.", "body_zh": "匈牙利阻挠乌克兰与摩尔多瓦入盟下一阶段谈判。\n\n乌克兰刚通过保护匈牙利语少数族裔法律数日，匈牙利即叫停下乌、摩入盟下一阶段，令外交官困惑于其沉默。\n\n在 10 月 20 日欧盟技术专家会议上，匈牙利反对推进绿色议程、可持续互联、资源、农业与凝聚等最后两个谈判集群，其余 26 国支持。此前乌克兰 10 月 12 日通过少数族裔保护法，总理彼得·毛扎尔与泽连斯基会晤以重置关系，曾使更早集群得以开启。\n\n阻挠再度引发对匈牙利入盟立场的质疑：需全体一致，观察人士对在外联努力后仍无解释的决定感到沮丧。", "url": "https://x.com/i/trending/2112592169139855608", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:18:54.000Z"}, {"id": "2112341331209265163", "domain": "国际", "title_en": "Leaked Canada-EU Draft Fuels Alberta Oil Sector Backlash", "title_zh": "加欧协议草案泄露，阿尔伯塔油气界反弹", "hook_en": "Just days after Alberta voters chose to stay in Canada, a leaked draft agreement with the EU has residents fuming over what they see as a snub to their vital oil industry.", "hook_zh": "阿尔伯塔选民刚投票留在加拿大数日，泄露的对欧协议草案被指冷落本省关键石油业，引发不满。", "summary_en": "The nine-page document, sent to Brussels in September and analyzed in a Western Standard column on October 19, pushes regulatory alignment on low-carbon energy sources like LNG, hydro, solar, wind, and nuclear, with no mention of Alberta's conventional oil. Critics call it a move that hands resource control to the EU and imposes green standards, especially amid Prime Minister Mark Carney's outreach to Europe during U.S. trade tensions. This comes right after Alberta's October 19 referendum, where 76% voted to remain in Canada, spotlighting ongoing clashes between provincial energy interests and federal climate goals.", "summary_zh": "这份 9 页文件 9 月送往布鲁塞尔，10 月 19 日《Western Standard》专栏分析称其推动在 LNG、水电、太阳能、风电与核能等低碳能源上的监管对齐，却未提及阿尔伯塔常规石油。批评者称此举把资源控制交给欧盟并强加绿色标准，尤其时值总理马克·卡尼在对美贸易紧张中加强联欧。事件紧随阿尔伯塔 10 月 19 日公投——76% 投票留在加拿大——凸显省能源利益与联邦气候目标冲突。", "body_en": "Leaked Canada-EU Draft Fuels Alberta Oil Sector Backlash.\n\nJust days after Alberta voters chose to stay in Canada, a leaked draft agreement with the EU has residents fuming over what they see as a snub to their vital oil industry.\n\nThe nine-page document, sent to Brussels in September and analyzed in a Western Standard column on October 19, pushes regulatory alignment on low-carbon energy sources like LNG, hydro, solar, wind, and nuclear, with no mention of Alberta's conventional oil.\n\nCritics call it a move that hands resource control to the EU and imposes green standards, especially amid Prime Minister Mark Carney's outreach to Europe during U.S.trade tensions. This comes right after Alberta's October 19 referendum, where 76% voted to remain in Canada, spotlighting ongoing clashes between provincial energy interests and federal climate goals.", "body_zh": "加欧协议草案泄露，阿尔伯塔油气界反弹。\n\n阿尔伯塔选民刚投票留在加拿大数日，泄露的对欧协议草案被指冷落本省关键石油业，引发不满。\n\n这份 9 页文件 9 月送往布鲁塞尔，10 月 19 日《Western Standard》专栏分析称其推动在 LNG、水电、太阳能、风电与核能等低碳能源上的监管对齐，却未提及阿尔伯塔常规石油。批评者称此举把资源控制交给欧盟并强加绿色标准，尤其时值总理马克·卡尼在对美贸易紧张中加强联欧。\n\n事件紧随阿尔伯塔 10 月 19 日公投——76% 投票留在加拿大——凸显省能源利益与联邦气候目标冲突。", "url": "https://x.com/i/trending/2112341331209265163", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T14:11:05.000Z"}, {"id": "2112501506905710732", "domain": "国际", "title_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims", "title_zh": "英美波驳斥美防长「阿富汗盟友寥寥」说法", "hook_en": "Pete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.", "hook_zh": "皮特·赫格塞斯称真正并肩作战的国家寥寥无几，英波领导人反击。", "summary_en": "During a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks. Poland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "summary_zh": "英方指出英军阵亡 457 人，仅次于美国；波兰强调 44 名军人牺牲。非美联军死亡总计逾 1100 人。", "body_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims.\n\nPete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.\n\nDuring a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks.\n\nPoland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "body_zh": "英美波驳斥美防长「阿富汗盟友寥寥」说法。\n\n皮特·赫格塞斯称真正并肩作战的国家寥寥无几，英波领导人反击。\n\n英方指出英军阵亡 457 人，仅次于美国；波兰强调 44 名军人牺牲。非美联军死亡总计逾 1100 人。\n\n皮特·赫格塞斯称真正并肩作战的国家寥寥无几，英波领导人反击。\n\n综合以上信息，英美波驳斥美防长「阿富汗盟友寥寥」说法一事持续引发关注。\n\n英波方面强调盟友牺牲与集体安全义务，认为防长言论低估了联军贡献。", "url": "https://x.com/i/trending/2112501506905710732", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:10:22.000Z"}, {"id": "2112296384745631848", "domain": "国际", "title_en": "France Protests Spark Debate on Russian Interference Claims", "title_zh": "法国抗议潮引发「俄方干涉」说法之争", "hook_en": "Hundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.", "hook_zh": "10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。", "summary_en": "Demonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests. Estonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "summary_zh": "全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "body_en": "France Protests Spark Debate on Russian Interference Claims.\n\nHundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.\n\nDemonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests.\n\nEstonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "body_zh": "法国抗议潮引发「俄方干涉」说法之争。\n\n10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。\n\n全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。\n\n官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "url": "https://x.com/i/trending/2112296384745631848", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:03:55.000Z"}, {"id": "2112462431087939712", "domain": "国际", "title_en": "South Korea Withdraws Embassy Staff from Ukraine Over North Korean POW Dispute", "title_zh": "韩国因朝俘争端撤回驻乌克兰部分使馆人员", "hook_en": "Two North Korean soldiers captured in Ukraine's brutal fighting now sit at the heart of a deepening rift between Seoul and Kyiv, prompting a partial pullback of embassy staff.", "hook_zh": "两名在乌克兰战场被俘的朝鲜士兵，成为首尔与基辅裂痕核心，韩方部分撤回使馆人员。", "summary_en": "South Korea's Foreign Ministry announced it will withdraw about half its diplomatic personnel from Ukraine due to Kyiv's failure to resolve a dispute over two captured North Korean soldiers transferred to Seoul last month. The tensions erupted after President Zelenskyy publicly disclosed the transfer at the UN, which Seoul says breached a confidentiality agreement meant to protect the soldiers and their families. While consular services continue and channels for citizen evacuations remain open, the move underscores Seoul's frustration amid ongoing Russian airstrikes. Ukraine denies any secrecy pact and insists the issue is settled, keeping doors open for talks.", "summary_zh": "韩国外交部宣布，因基辅未能解决上月移交首尔的两名被俘朝鲜士兵争端，将撤回驻乌约半数外交人员。紧张在泽连斯基总统于联合国公开披露移交后升温，首尔称此举违反旨在保护士兵及其家属的保密约定。领事服务与公民撤离渠道仍保留。乌方否认存在保密协议，称问题已了结并愿继续对话；此举凸显首尔在俄持续空袭背景下的不满。", "body_en": "South Korea Withdraws Embassy Staff from Ukraine Over North Korean POW Dispute.\n\nTwo North Korean soldiers captured in Ukraine's brutal fighting now sit at the heart of a deepening rift between Seoul and Kyiv, prompting a partial pullback of embassy staff.\n\nSouth Korea's Foreign Ministry announced it will withdraw about half its diplomatic personnel from Ukraine due to Kyiv's failure to resolve a dispute over two captured North Korean soldiers transferred to Seoul last month.\n\nThe tensions erupted after President Zelenskyy publicly disclosed the transfer at the UN, which Seoul says breached a confidentiality agreement meant to protect the soldiers and their families. While consular services continue and channels for citizen evacuations remain open, the move underscores Seoul's frustration amid ongoing Russian airstrikes.Ukraine denies any secrecy pact and insists the issue is settled, keeping doors open for talks.", "body_zh": "韩国因朝俘争端撤回驻乌克兰部分使馆人员。\n\n两名在乌克兰战场被俘的朝鲜士兵，成为首尔与基辅裂痕核心，韩方部分撤回使馆人员。\n\n韩国外交部宣布，因基辅未能解决上月移交首尔的两名被俘朝鲜士兵争端，将撤回驻乌约半数外交人员。紧张在泽连斯基总统于联合国公开披露移交后升温，首尔称此举违反旨在保护士兵及其家属的保密约定。\n\n领事服务与公民撤离渠道仍保留。乌方否认存在保密协议，称问题已了结并愿继续对话；此举凸显首尔在俄持续空袭背景下的不满。", "url": "https://x.com/i/trending/2112462431087939712", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T13:25:27.000Z"}, {"id": "2112460842902151394", "domain": "国际", "title_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters", "title_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击", "hook_en": "U.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.", "hook_zh": "美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。", "summary_en": "Rep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep. Brian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "summary_zh": "民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "body_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters.\n\nU.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.\n\nRep.Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S.sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support.Rep.\n\nBrian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement.The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "body_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击。\n\n美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。\n\n民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。\n\n网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "url": "https://x.com/i/trending/2112460842902151394", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T08:32:59.000Z"}, {"id": "2112231064404193496", "domain": "国际", "title_en": "Mike Johnson Warns Voters on Energy Costs Ahead of Midterms", "title_zh": "迈克·约翰逊中期选举前就能源成本警告选民", "hook_en": "With oil prices hovering near $109 a barrel amid the U.S.-Iran conflict, House Speaker Mike Johnson is urging voters to stick with Republicans to avoid Democratic fossil fuel restrictions.", "hook_zh": "美伊冲突背景下油价徘徊每桶约 109 美元，众议院议长迈克·约翰逊敦促选民继续支持共和党，以免民主党限制化石燃料。", "summary_en": "As the November 3, 2026 midterm elections near, Johnson appeared on Fox News to contrast Republican economic fixes with what he calls Democrats' plans to ban fossil fuels, linking high Brent crude prices—recently settling at $109.55—to supply worries from the ongoing conflict that started earlier this year. Critics counter that current price hikes tie to Republican tariffs and the war, while earlier inflation under Biden stemmed from the global pandemic and stimulus. Republicans hold slim majorities (House 218-214, Senate 53-47), and Democrats need just a few seats to flip control as early voting begins.", "summary_zh": "临近 2026 年 11 月 3 日中期选举，约翰逊上福克斯新闻对比共和党经济方案与其所称民主党「禁化石燃料」计划，将近期结算约 109.55 美元的布伦特油价与今年早些时候开打的冲突带来的供应担忧挂钩。批评者反指当前涨价与共和党关税及战争有关，而拜登时期通胀更多来自全球疫情与刺激。共和党仅以微弱多数执政（众院 218–214，参院 53–47），民主党只需再拿数席即可翻转，提前投票已经开始。", "body_en": "Mike Johnson Warns Voters on Energy Costs Ahead of Midterms.\n\nWith oil prices hovering near $109 a barrel amid the U.S.-Iran conflict, House Speaker Mike Johnson is urging voters to stick with Republicans to avoid Democratic fossil fuel restrictions.\n\nAs the November 3, 2026 midterm elections near, Johnson appeared on Fox News to contrast Republican economic fixes with what he calls Democrats' plans to ban fossil fuels, linking high Brent crude prices—recently settling at $109.55—to supply worries from the ongoing conflict that started earlier this year.\n\nCritics counter that current price hikes tie to Republican tariffs and the war, while earlier inflation under Biden stemmed from the global pandemic and stimulus. Republicans hold slim majorities (House 218-214, Senate 53-47), and Democrats need just a few seats to flip control as early voting begins.", "body_zh": "迈克·约翰逊中期选举前就能源成本警告选民。\n\n美伊冲突背景下油价徘徊每桶约 109 美元，众议院议长迈克·约翰逊敦促选民继续支持共和党，以免民主党限制化石燃料。\n\n临近 2026 年 11 月 3 日中期选举，约翰逊上福克斯新闻对比共和党经济方案与其所称民主党「禁化石燃料」计划，将近期结算约 109.55 美元的布伦特油价与今年早些时候开打的冲突带来的供应担忧挂钩。批评者反指当前涨价与共和党关税及战争有关，而拜登时期通胀更多来自全球疫情与刺激。\n\n共和党仅以微弱多数执政（众院 218–214，参院 53–47），民主党只需再拿数席即可翻转，提前投票已经开始。", "url": "https://x.com/i/trending/2112231064404193496", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T02:45:28.000Z"}, {"id": "2112316607234277778", "domain": "国际", "title_en": "UK Presses Ahead with Chagos Islands Sovereignty Transfer Despite Trump Objections", "title_zh": "英国推进查戈斯群岛主权移交，尽管特朗普反对", "hook_en": "Defence Secretary Wes Streeting faced tough questions from MPs, standing firm on a deal he sees as vital for safeguarding a key UK-US military base on Diego Garcia.", "hook_zh": "国防大臣韦斯·斯特里廷面对议员质询仍坚持协议，称其关乎守护迪戈加西亚英美关键军事基地。", "summary_en": "Labour is moving forward with plans to hand sovereignty of the Chagos Islands to Mauritius, leasing back the strategic Diego Garcia atoll for 99 years at an annual cost starting at £165 million. The agreement, signed in May 2025, awaits US approval amid President Trump's strong objections and requires it to proceed. Critics label it a costly surrender of British territory, potentially totaling £35 billion over time, while the government insists it eliminates legal risks to the base's operations. Public backlash has been fierce, with calls for leadership change and opposition from figures like Nigel Farage.", "summary_zh": "工党推进将查戈斯群岛主权移交毛里求斯，并以约 1.65 亿英镑起年租金回租战略环礁迪戈加西亚 99 年。协议 2025 年 5 月签署，需美方批准方可推进，而特朗普总统强烈反对。批评者称其代价高昂的领土让渡，长期或达 350 亿英镑；政府坚称可消除基地运营法律风险。公众反弹强烈，有人要求换领导，尼格尔·法拉奇等亦反对。", "body_en": "UK Presses Ahead with Chagos Islands Sovereignty Transfer Despite Trump Objections.\n\nDefence Secretary Wes Streeting faced tough questions from MPs, standing firm on a deal he sees as vital for safeguarding a key UK-US military base on Diego Garcia.\n\nLabour is moving forward with plans to hand sovereignty of the Chagos Islands to Mauritius, leasing back the strategic Diego Garcia atoll for 99 years at an annual cost starting at £165 million.\n\nThe agreement, signed in May 2025, awaits US approval amid President Trump's strong objections and requires it to proceed. Critics label it a costly surrender of British territory, potentially totaling £35 billion over time, while the government insists it eliminates legal risks to the base's operations. Public backlash has been fierce, with calls for leadership change and opposition from figures like Nigel Farage.", "body_zh": "英国推进查戈斯群岛主权移交，尽管特朗普反对。\n\n国防大臣韦斯·斯特里廷面对议员质询仍坚持协议，称其关乎守护迪戈加西亚英美关键军事基地。\n\n工党推进将查戈斯群岛主权移交毛里求斯，并以约 1.65 亿英镑起年租金回租战略环礁迪戈加西亚 99 年。协议 2025 年 5 月签署，需美方批准方可推进，而特朗普总统强烈反对。\n\n批评者称其代价高昂的领土让渡，长期或达 350 亿英镑；政府坚称可消除基地运营法律风险。公众反弹强烈，有人要求换领导，尼格尔·法拉奇等亦反对。", "url": "https://x.com/i/trending/2112316607234277778", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-19T23:01:32.000Z"}, {"id": "2111606213733409230", "domain": "国际", "title_en": "House Republicans Threaten to Block Trump Pentagon Funding Over Russia Policy", "title_zh": "众院共和党人威胁因对俄政策拦下特朗普五角大楼拨款", "hook_en": "Rep. Don Bacon bluntly declared President Trump's lame-duck agenda 'dead' after the White House waived sanctions on Russia, leaving some GOP lawmakers ready to fight back.", "hook_zh": "众议员唐·培根直言，白宫豁免对俄制裁后，特朗普跛脚鸭议程已「死」，部分共和党人准备反击。", "summary_en": "A group of House Republicans, led by figures like Reps. Don Bacon and Brian Fitzpatrick, warns they will block $350 billion in Pentagon funding and other priorities unless Trump reinstates sanctions from the Lindsey O. Graham Sanctioning Russia and Iran Act of 2026 and eases restrictions on Ukraine. The waiver, issued just before the measures took effect, followed a deal allowing Russian diesel imports and drew criticism for propping up Russia's invasion while limiting Ukraine's access to U.S. satellite systems. Sen. Darline Graham voiced distrust of Putin and a preference for sustained pressure, underscoring GOP rifts on Russia policy in the brief lame-duck session.", "summary_zh": "以唐·培根、布赖恩·菲茨帕特里克等为首的众院共和党人警告，除非特朗普恢复《2026 年林赛·O·格雷厄姆制裁俄罗斯与伊朗法》相关制裁并放松对乌克兰限制，否则将拦下约 3500 亿美元五角大楼拨款及其他优先事项。制裁豁免在措施生效前夕发布，此前有允许进口俄柴油的安排，批评者指其支撑俄方进攻并限制乌克兰获取美卫星系统。参议员达林·格雷厄姆表示不信任普京、倾向持续施压，凸显共和党内部对俄政策裂痕。", "body_en": "House Republicans Threaten to Block Trump Pentagon Funding Over Russia Policy.\n\nRep. Don Bacon bluntly declared President Trump's lame-duck agenda 'dead' after the White House waived sanctions on Russia, leaving some GOP lawmakers ready to fight back.\n\nA group of House Republicans, led by figures like Reps.Don Bacon and Brian Fitzpatrick, warns they will block $350 billion in Pentagon funding and other priorities unless Trump reinstates sanctions from the Lindsey O.\n\nGraham Sanctioning Russia and Iran Act of 2026 and eases restrictions on Ukraine.The waiver, issued just before the measures took effect, followed a deal allowing Russian diesel imports and drew criticism for propping up Russia's invasion while limiting Ukraine's access to U.S. satellite systems.Sen.Darline Graham voiced distrust of Putin and a preference for sustained pressure, underscoring GOP rifts on Russia policy in the brief lame-duck session.", "body_zh": "众院共和党人威胁因对俄政策拦下特朗普五角大楼拨款。\n\n众议员唐·培根直言，白宫豁免对俄制裁后，特朗普跛脚鸭议程已「死」，部分共和党人准备反击。\n\n以唐·培根、布赖恩·菲茨帕特里克等为首的众院共和党人警告，除非特朗普恢复《2026 年林赛·O·格雷厄姆制裁俄罗斯与伊朗法》相关制裁并放松对乌克兰限制，否则将拦下约 3500 亿美元五角大楼拨款及其他优先事项。制裁豁免在措施生效前夕发布，此前有允许进口俄柴油的安排，批评者指其支撑俄方进攻并限制乌克兰获取美卫星系统。\n\n参议员达林·格雷厄姆表示不信任普京、倾向持续施压，凸显共和党内部对俄政策裂痕。", "url": "https://x.com/i/trending/2111606213733409230", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-19T22:52:00.000Z"}, {"id": "2112804232634187907", "domain": "体育", "title_en": "NBA Season Tips Off with Thunder Victory and Fan Joy", "title_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾", "hook_en": "Fans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.", "hook_zh": "2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。", "summary_en": "The season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch. Shai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama. Other games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "summary_zh": "赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "body_en": "NBA Season Tips Off with Thunder Victory and Fan Joy.\n\nFans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.\n\nThe season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch.\n\nShai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama.Other games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "body_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾。\n\n2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。\n\n赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。\n\n另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "url": "https://x.com/i/trending/2112804232634187907", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:17:07.000Z"}, {"id": "2112355020591046930", "domain": "体育", "title_en": "WNBA Teams Leave Court Before National Anthem in Finals", "title_zh": "WNBA 总决赛两队国歌前离场惹议", "hook_en": "Players from the Atlanta Dream and Golden State Valkyries stepped off the court just before the national anthem started in the WNBA Finals at Chase Center, following their usual pregame routines.", "hook_zh": "亚特兰大梦想与金州女武神在 Chase Center 总决赛中，按惯常赛前流程于国歌响起前走下球场。", "summary_en": "Both teams warmed up, left for the locker room prior to the anthems in Games 1 and 2, and returned right after— a practice the Valkyries have used since starting and the Dream for years, amid league norms since protocols loosened around 2017-2020. Critics like Sage Steele called it sprinting off in ignorance, while Clay Travis blamed identity politics for alienating Caitlin Clark fans; social media labeled players entitled given CBA salaries up to $1.4 million. The WNBA rulebook requires standing along the sidelines, but teams and the league offered no comment, with no discipline announced as Game 3 heads to Atlanta.", "summary_zh": "两队热身后天歌前进入更衣室，国歌后再返回——女武神自建队沿用，梦想亦多年如此，与联盟约 2017–2020 年放松相关规范后的常见做法一致。批评者如 Sage Steele 称「无知地冲下场」，Clay Travis 归咎身份政治疏远凯琳·克拉克球迷；社交媒体以 CBA 薪资可达 140 万美元指球员「 entitlement」。规则书要求沿边线站立，但球队与联盟未置评，亦未宣布纪律，系列赛第三场将转战亚特兰大。", "body_en": "WNBA Teams Leave Court Before National Anthem in Finals.\n\nPlayers from the Atlanta Dream and Golden State Valkyries stepped off the court just before the national anthem started in the WNBA Finals at Chase Center, following their usual pregame routines.\n\nBoth teams warmed up, left for the locker room prior to the anthems in Games 1 and 2, and returned right after— a practice the Valkyries have used since starting and the Dream for years, amid league norms since protocols loosened around 2017-2020.\n\nCritics like Sage Steele called it sprinting off in ignorance, while Clay Travis blamed identity politics for alienating Caitlin Clark fans; social media labeled players entitled given CBA salaries up to $1.4 million. The WNBA rulebook requires standing along the sidelines, but teams and the league offered no comment, with no discipline announced as Game 3 heads to Atlanta.", "body_zh": "WNBA 总决赛两队国歌前离场惹议。\n\n亚特兰大梦想与金州女武神在 Chase Center 总决赛中，按惯常赛前流程于国歌响起前走下球场。\n\n两队热身后天歌前进入更衣室，国歌后再返回——女武神自建队沿用，梦想亦多年如此，与联盟约 2017–2020 年放松相关规范后的常见做法一致。批评者如 Sage Steele 称「无知地冲下场」，Clay Travis 归咎身份政治疏远凯琳·克拉克球迷；社交媒体以 CBA 薪资可达 140 万美元指球员「 entitlement」。\n\n规则书要求沿边线站立，但球队与联盟未置评，亦未宣布纪律，系列赛第三场将转战亚特兰大。", "url": "https://x.com/i/trending/2112355020591046930", "category": "Sports", "topics": ["WNBA"], "updated_at": "2026-10-21T07:17:02.000Z"}, {"id": "2112801176995467757", "domain": "体育", "title_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts", "title_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相", "hook_en": "LeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.", "hook_zh": "勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。", "summary_en": "The Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration. Tyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "summary_zh": "费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "body_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts.\n\nLeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.\n\nThe Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration.\n\nTyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "body_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相。\n\n勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。\n\n费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。\n\n赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "url": "https://x.com/i/trending/2112801176995467757", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:06:29.000Z"}, {"id": "2112237568490389869", "domain": "体育", "title_en": "Brewers Timeless Ticket Holders Frustrated in World Series Debut", "title_zh": "酿酒人「永恒票」持有者世界大赛首秀遇挫", "hook_en": "Two brothers waited 11 years to cash in $1,000 tickets for the Brewers' first World Series in 44 years. Instead of prime seats, they got terrace or standing room.", "hook_zh": "两兄弟等了 11 年，才用 1000 美元门票兑现酿酒人 44 年来首进世界大赛；期待的好座位却变成露台或站票。", "summary_en": "Kevin and Kyle Deaton bought personalized Timeless Tickets in 2015, promised the best available seats for any home game including playoffs. When redeeming for this year's World Series at American Family Field, they received upper-level or standing options amid scarce premium seats. Brewers President Rick Schlesinger admitted the team fell short of the program's spirit due to internal miscommunications, offering fans both current tickets and future redemptions. The dispute has drawn mixed reactions, with some likening it to a disappointing *The Office* promise while others see the fix as fair given high demand and soaring prices over $2,700.", "summary_zh": "凯文与凯尔·迪顿 2015 年购买个性化「永恒票」，承诺含季后赛在内任意主场尽量给最佳可用座位。今年在美国家庭球场兑现世界大赛时，因优质座位稀缺只拿到上层或站票。总裁里克·施莱辛格承认未达项目精神，归因内部沟通不畅，并提供当场票与未来再次兑现。争议评价不一：有人比作令人失望的承诺，也有人觉在高需求与票价超 2700 美元背景下补救算公平。", "body_en": "Brewers Timeless Ticket Holders Frustrated in World Series Debut.\n\nTwo brothers waited 11 years to cash in $1,000 tickets for the Brewers' first World Series in 44 years. Instead of prime seats, they got terrace or standing room.\n\nKevin and Kyle Deaton bought personalized Timeless Tickets in 2015, promised the best available seats for any home game including playoffs.\n\nWhen redeeming for this year's World Series at American Family Field, they received upper-level or standing options amid scarce premium seats. Brewers President Rick Schlesinger admitted the team fell short of the program's spirit due to internal miscommunications, offering fans both current tickets and future redemptions. The dispute has drawn mixed reactions, with some likening it to a disappointing *The Office* promise while others see the fix as fair given high demand and soaring prices over $2,700.", "body_zh": "酿酒人「永恒票」持有者世界大赛首秀遇挫。\n\n两兄弟等了 11 年，才用 1000 美元门票兑现酿酒人 44 年来首进世界大赛；期待的好座位却变成露台或站票。\n\n凯文与凯尔·迪顿 2015 年购买个性化「永恒票」，承诺含季后赛在内任意主场尽量给最佳可用座位。今年在美国家庭球场兑现世界大赛时，因优质座位稀缺只拿到上层或站票。\n\n总裁里克·施莱辛格承认未达项目精神，归因内部沟通不畅，并提供当场票与未来再次兑现。争议评价不一：有人比作令人失望的承诺，也有人觉在高需求与票价超 2700 美元背景下补救算公平。", "url": "https://x.com/i/trending/2112237568490389869", "category": "Sports", "topics": ["Baseball"], "updated_at": "2026-10-21T06:34:08.000Z"}, {"id": "2112363184577191956", "domain": "体育", "title_en": "NFL Pushes Ahead with First France Game Amid Paris Unrest", "title_zh": "巴黎动荡中 NFL 仍推进法国首场常规赛", "hook_en": "As riots rage in Paris over rising costs and public services, the NFL stands firm on its historic game at Stade de France. Steelers star T.J. Watt's wife posted a headline questioning the decision with 'Tell me how this one make sense???'.", "hook_zh": "巴黎因生活成本与公共服务爆发骚乱，NFL 仍坚持法兰西体育场历史性比赛。钢人球星 T.J. 瓦特妻子发帖质问「这怎么说得通」。", "summary_en": "The Pittsburgh Steelers and New Orleans Saints are set to play the NFL's first regular-season game in France on October 25 at Stade de France in Saint-Denis, despite violent protests that erupted October 17-18, leading to arrests, fires, and curfews. League officials, including Roger Goodell, call the unrest 'mostly peaceful' and have ramped up security with local police, national authorities, and the U.S. State Department, confirming no plans to postpone. The Saints have arrived, Steelers are en route, and executives like Peter O’Reilly stress safety as the top priority, even as some players' families voice concerns.", "summary_zh": "匹兹堡钢人与新奥尔良圣徒定于 10 月 25 日在圣但尼法兰西体育场进行 NFL 法国首场常规赛，尽管 10 月 17–18 日暴力抗议导致逮捕、纵火与宵禁。包括罗杰·古德尔在内的联盟官员称动荡「大体和平」，并与地方警察、国家当局及美国国务院加强安保，暂无延期计划。圣徒已抵达、钢人在途，高管强调安全优先，部分球员家属仍表担忧。", "body_en": "NFL Pushes Ahead with First France Game Amid Paris Unrest.\n\nAs riots rage in Paris over rising costs and public services, the NFL stands firm on its historic game at Stade de France. Steelers star T.J. Watt's wife posted a headline questioning the decision with 'Tell me how this one make sense???'.\n\nThe Pittsburgh Steelers and New Orleans Saints are set to play the NFL's first regular-season game in France on October 25 at Stade de France in Saint-Denis, despite violent protests that erupted October 17-18, leading to arrests, fires, and curfews.\n\nLeague officials, including Roger Goodell, call the unrest 'mostly peaceful' and have ramped up security with local police, national authorities, and the U.S.State Department, confirming no plans to postpone. The Saints have arrived, Steelers are en route, and executives like Peter O’Reilly stress safety as the top priority, even as some players' families voice concerns.", "body_zh": "巴黎动荡中 NFL 仍推进法国首场常规赛。\n\n巴黎因生活成本与公共服务爆发骚乱，NFL 仍坚持法兰西体育场历史性比赛。钢人球星 T.J. 瓦特妻子发帖质问「这怎么说得通」。\n\n匹兹堡钢人与新奥尔良圣徒定于 10 月 25 日在圣但尼法兰西体育场进行 NFL 法国首场常规赛，尽管 10 月 17–18 日暴力抗议导致逮捕、纵火与宵禁。包括罗杰·古德尔在内的联盟官员称动荡「大体和平」，并与地方警察、国家当局及美国国务院加强安保，暂无延期计划。\n\n圣徒已抵达、钢人在途，高管强调安全优先，部分球员家属仍表担忧。", "url": "https://x.com/i/trending/2112363184577191956", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T05:34:34.000Z"}, {"id": "2112326602743050735", "domain": "体育", "title_en": "MLB Fans Debate Salary Cap as Small-Market Teams Reach World Series", "title_zh": "小球市进世界大赛，MLB 球迷再议薪资帽", "hook_en": "The Milwaukee Brewers swept the Dodgers in the NLCS, sending two low-spending teams to the World Series and fueling fresh talk about whether MLB needs a salary cap.", "hook_zh": "密尔沃基酿酒人横扫道奇进联盟冠军赛后，两支低支出球队会师世界大赛，重新点燃「大联盟要不要薪资帽」讨论。", "summary_en": "Brewers, with the 19th-ranked payroll, beat the high-spending Dodgers in four games, drawing 7.53 million viewers—the best LCS audience since 2015—and now face the Rays for a first-time champion. Owners propose a $245.3 million hard cap and $171.2 million floor starting 2027 to boost balance, but players reject it as a wage suppressor. Small-market fans like Pirates supporters cheer the idea to limit talent hoarding, while critics say location and culture still sway stars, and Brewers' run proves smart spending works amid wide payroll gaps like the Dodgers' $433 million projection.", "summary_zh": "薪资排名第 19 的酿酒人四场淘汰高支出道奇，联盟冠军赛收视 753 万——2015 年以来最佳，并将对阵光芒争夺首次总冠军。资方提议 2027 年起硬帽约 2.453 亿美元、下限约 1.712 亿以促平衡，球员指其压低工资加以拒绝。海盗等小球市球迷欢迎限制囤人；批评者称区位与文化仍左右球星去向，酿酒人此番证明精明开支可行，尽管与道奇预计约 4.33 亿薪资差距巨大。", "body_en": "MLB Fans Debate Salary Cap as Small-Market Teams Reach World Series.\n\nThe Milwaukee Brewers swept the Dodgers in the NLCS, sending two low-spending teams to the World Series and fueling fresh talk about whether MLB needs a salary cap.\n\nBrewers, with the 19th-ranked payroll, beat the high-spending Dodgers in four games, drawing 7.53 million viewers—the best LCS audience since 2015—and now face the Rays for a first-time champion.\n\nOwners propose a $245.3 million hard cap and $171.2 million floor starting 2027 to boost balance, but players reject it as a wage suppressor. Small-market fans like Pirates supporters cheer the idea to limit talent hoarding, while critics say location and culture still sway stars, and Brewers' run proves smart spending works amid wide payroll gaps like the Dodgers' $433 million projection.", "body_zh": "小球市进世界大赛，MLB 球迷再议薪资帽。\n\n密尔沃基酿酒人横扫道奇进联盟冠军赛后，两支低支出球队会师世界大赛，重新点燃「大联盟要不要薪资帽」讨论。\n\n薪资排名第 19 的酿酒人四场淘汰高支出道奇，联盟冠军赛收视 753 万——2015 年以来最佳，并将对阵光芒争夺首次总冠军。资方提议 2027 年起硬帽约 2.453 亿美元、下限约 1.712 亿以促平衡，球员指其压低工资加以拒绝。\n\n海盗等小球市球迷欢迎限制囤人；批评者称区位与文化仍左右球星去向，酿酒人此番证明精明开支可行，尽管与道奇预计约 4.33 亿薪资差距巨大。", "url": "https://x.com/i/trending/2112326602743050735", "category": "Sports", "topics": ["MLB"], "updated_at": "2026-10-21T05:20:54.000Z"}, {"id": "2112708824692084761", "domain": "体育", "title_en": "Brewers' Woodruff Faces Live Hitters, Eyes World Series Roster Spot", "title_zh": "酿酒人伍德拉夫面对活打者，觊觎世界大赛名单席位", "hook_en": "Brandon Woodruff stepped to the mound at American Family Field, firing 23 pitches at 90-92 mph to his teammates for the first time since his shoulder injury.", "hook_zh": "布兰登·伍德拉夫重返美国家庭球场投手丘，以 90–92 英里时速对队友投出 23 球——肩伤后首次。", "summary_en": "The 33-year-old right-hander, sidelined since July 4 with shoulder inflammation, threw a live batting practice session Tuesday ahead of the Brewers' World Series opener against the Rays on Friday. Woodruff told reporters he wants a roster spot but understands the tough call, given MLB rules that limit replacements for non-acute injuries and the risk of a setback. Fans buzz with excitement over his unexpected progress after skipping surgery, though the team weighs his limited workload against bullpen depth and the stakes of the franchise's first Series since 1982.", "summary_zh": "这名 33 岁右投自 7 月 4 日肩部炎症缺阵，周二在酿酒人周五对光芒的世界大赛揭幕战前完成活打者练习。他对媒体称想进名单但也理解艰难决定：大联盟对非急性伤限制替换，且有复发风险。球迷为其跳过手术后的意外进展兴奋；球队则权衡有限工作量、牛棚深度与队史自 1982 年来首进大赛的利害。", "body_en": "Brewers' Woodruff Faces Live Hitters, Eyes World Series Roster Spot.\n\nBrandon Woodruff stepped to the mound at American Family Field, firing 23 pitches at 90-92 mph to his teammates for the first time since his shoulder injury.\n\nThe 33-year-old right-hander, sidelined since July 4 with shoulder inflammation, threw a live batting practice session Tuesday ahead of the Brewers' World Series opener against the Rays on Friday.\n\nWoodruff told reporters he wants a roster spot but understands the tough call, given MLB rules that limit replacements for non-acute injuries and the risk of a setback. Fans buzz with excitement over his unexpected progress after skipping surgery, though the team weighs his limited workload against bullpen depth and the stakes of the franchise's first Series since 1982.", "body_zh": "酿酒人伍德拉夫面对活打者，觊觎世界大赛名单席位。\n\n布兰登·伍德拉夫重返美国家庭球场投手丘，以 90–92 英里时速对队友投出 23 球——肩伤后首次。\n\n这名 33 岁右投自 7 月 4 日肩部炎症缺阵，周二在酿酒人周五对光芒的世界大赛揭幕战前完成活打者练习。他对媒体称想进名单但也理解艰难决定：大联盟对非急性伤限制替换，且有复发风险。\n\n球迷为其跳过手术后的意外进展兴奋；球队则权衡有限工作量、牛棚深度与队史自 1982 年来首进大赛的利害。", "url": "https://x.com/i/trending/2112708824692084761", "category": "Sports", "topics": ["Baseball"], "updated_at": "2026-10-21T03:54:25.000Z"}, {"id": "2112527510105919970", "domain": "体育", "title_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs", "title_zh": "前 NFL 球员指控裁判「做局」帮酋长", "hook_en": "Breiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.", "hook_zh": "布雷登·费霍科在播客上点名他认为的酋长队末节关照，戳中许多对手球迷多年的挫败感。", "summary_en": "Former Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games. He pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs. Critics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof. The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "summary_zh": "前闪电队防守截锋布雷登·费霍科在杰森·惠特洛克播客上声称，裁判在第四节给堪萨斯城「幽灵哨」以扭转胶着局面，指落后时罚球常救酋长，称之「嘲弄」，并挑战裁判季后赛保持中立。批评者指出他仅打过一场对酋长、生涯出场 19 次经验有限；球迷则搬出 2022 年美联冠军赛等「证据」。辩论凸显对 NFL 执法的持续抱怨，但缺乏操纵的硬证据。", "body_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs.\n\nBreiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.\n\nFormer Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games.\n\nHe pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs. Critics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof.The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "body_zh": "前 NFL 球员指控裁判「做局」帮酋长。\n\n布雷登·费霍科在播客上点名他认为的酋长队末节关照，戳中许多对手球迷多年的挫败感。\n\n前闪电队防守截锋布雷登·费霍科在杰森·惠特洛克播客上声称，裁判在第四节给堪萨斯城「幽灵哨」以扭转胶着局面，指落后时罚球常救酋长，称之「嘲弄」，并挑战裁判季后赛保持中立。批评者指出他仅打过一场对酋长、生涯出场 19 次经验有限；球迷则搬出 2022 年美联冠军赛等「证据」。\n\n辩论凸显对 NFL 执法的持续抱怨，但缺乏操纵的硬证据。", "url": "https://x.com/i/trending/2112527510105919970", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T02:52:40.000Z"}, {"id": "2112588449140355241", "domain": "体育", "title_en": "LA Bar Group Hedges Dodgers Loss with $60K Bet, Doubles Money", "title_zh": "洛杉矶酒吧联盟押注道奇出局，6 万美元翻倍对冲空场损失", "hook_en": "When the Dodgers fell to the Brewers in the NLCS, a group of 25 bars near the stadium didn't sweat the empty seats—their clever $60,000 bet paid out $120,000 to cover the shortfall.", "hook_zh": "道奇在联盟冠军赛不敌酿酒人后，球场附近 25 家酒吧并未慌张——他们聪明的 6 万美元押注赔出 12 万，弥补少赛带来的缺口。", "summary_en": "The Los Angeles hospitality group bet on Kalshi that the Dodgers wouldn't reach the World Series, creating a perfect hedge against lost revenue from an early playoff exit. The wager doubled their money when the team lost, matching the extra business they expected from more games. This smart move highlights how prediction markets let businesses manage sports risks like custom insurance, with observers calling it 'pretty damn clever' and a win-win for crowd-dependent spots.", "summary_zh": "洛杉矶餐饮集团在 Kalshi 上押注道奇无法进世界大赛，完美对冲季后赛早早出局的营收损失。球队落败后赌注翻倍，大致匹配若多打几场本可多赚的生意。此举凸显预测市场可让依赖客流的商家像买定制保险一样管理体育风险，观察者称「相当聪明」、近乎双赢。", "body_en": "LA Bar Group Hedges Dodgers Loss with $60K Bet, Doubles Money.\n\nWhen the Dodgers fell to the Brewers in the NLCS, a group of 25 bars near the stadium didn't sweat the empty seats—their clever $60,000 bet paid out $120,000 to cover the shortfall.\n\nThe Los Angeles hospitality group bet on Kalshi that the Dodgers wouldn't reach the World Series, creating a perfect hedge against lost revenue from an early playoff exit.The wager doubled their money when the team lost, matching the extra business they expected from more games.\n\nThis smart move highlights how prediction markets let businesses manage sports risks like custom insurance, with observers calling it 'pretty damn clever' and a win-win for crowd-dependent spots.\n\nThe Los Angeles hospitality group bet on Kalshi that the Dodgers wouldn't reach the World Series, creating a perfect hedge against lost revenue from an early playoff exit. The wager doubled their money when the team lost, matching the extra business they expected from more games. This smart move highlights how prediction markets let businesses manage sports risks like custom insurance, with observers calling it 'pretty damn clever' and a win-win for crowd-dependent spots.", "body_zh": "洛杉矶酒吧联盟押注道奇出局，6 万美元翻倍对冲空场损失。\n\n道奇在联盟冠军赛不敌酿酒人后，球场附近 25 家酒吧并未慌张——他们聪明的 6 万美元押注赔出 12 万，弥补少赛带来的缺口。\n\n洛杉矶餐饮集团在 Kalshi 上押注道奇无法进世界大赛，完美对冲季后赛早早出局的营收损失。球队落败后赌注翻倍，大致匹配若多打几场本可多赚的生意。\n\n此举凸显预测市场可让依赖客流的商家像买定制保险一样管理体育风险，观察者称「相当聪明」、近乎双赢。", "url": "https://x.com/i/trending/2112588449140355241", "category": "News", "topics": ["Baseball"], "updated_at": "2026-10-21T01:55:22.000Z"}, {"id": "2112637280108335380", "domain": "体育", "title_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley", "title_zh": "NFL 裁判拉里·史密斯温布利非接触拉伤股四头肌，本季报销", "hook_en": "Larry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.", "hook_zh": "拉里·史密斯在死球阶段踩湿草滑倒，站起片刻后捂腿倒地——这一幕令这名裁判本季告别赛场。", "summary_en": "During the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties. A middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "summary_zh": "在温布利球场的休斯敦德州人队对杰克逊维尔美洲虎队比赛中，二年级 NFL 裁判拉里·史密斯于首节早段非接触滑倒，右股四头肌撕裂。两队训练员用球车将其抬离，组员以六人完成余场并分摊其职责。史密斯全职是堪萨斯城一名中学校长，2027 年前无法回归，联盟将物色替补。老将边线裁判卡尔·约翰逊脱帽跪其身侧似在祈祷，球迷对「裁判也进伤病名单」又惊又笑。", "body_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley.\n\nLarry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.\n\nDuring the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter.\n\nTrainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties. A middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "body_zh": "NFL 裁判拉里·史密斯温布利非接触拉伤股四头肌，本季报销。\n\n拉里·史密斯在死球阶段踩湿草滑倒，站起片刻后捂腿倒地——这一幕令这名裁判本季告别赛场。\n\n在温布利球场的休斯敦德州人队对杰克逊维尔美洲虎队比赛中，二年级 NFL 裁判拉里·史密斯于首节早段非接触滑倒，右股四头肌撕裂。两队训练员用球车将其抬离，组员以六人完成余场并分摊其职责。\n\n史密斯全职是堪萨斯城一名中学校长，2027 年前无法回归，联盟将物色替补。老将边线裁判卡尔·约翰逊脱帽跪其身侧似在祈祷，球迷对「裁判也进伤病名单」又惊又笑。", "url": "https://x.com/i/trending/2112637280108335380", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-20T20:16:29.000Z"}, {"id": "2112281281501528167", "domain": "体育", "title_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves", "title_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头", "hook_en": "Kyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.", "hook_zh": "凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。", "summary_en": "The Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No. 1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "summary_zh": "这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "body_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves.\n\nKyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.\n\nThe Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid.\n\nIrving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No.1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "body_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头。\n\n凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。\n\n这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。\n\n在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "url": "https://x.com/i/trending/2112281281501528167", "category": "Sports", "topics": [], "updated_at": "2026-10-20T15:54:00.000Z"}, {"id": "2112324176434368674", "domain": "体育", "title_en": "NFL Injury Analyst Dr. Jesse Morse Retires from Social Media Breakdowns", "title_zh": "NFL 伤病分析师杰西·莫尔斯医生退出社媒伤病解读", "hook_en": "Dr. Jesse Morse built a following breaking down NFL injuries since 2017, but the headaches and negativity finally pushed him to step away.", "hook_zh": "杰西·莫尔斯医生自 2017 年起靠拆解 NFL 伤病积累粉丝，但头痛与负面舆论最终令他抽身。", "summary_en": "Morse announced he's done with sports injury analysis on social media, calling it unsustainable due to constant stress, negative publicity, and a wish to focus on peptides, regenerative medicine, and his practice. The move follows backlash over his claim that the COVID-19 vaccine undoubtedly contributed to Eagles QB Jalen Hurts' blood clots, which progressed from a calf issue to serious lung emboli, sidelining him on blood thinners. Fans and fantasy players reacted with a mix of disappointment from those who valued his insights and relief or mockery from critics who saw his takes as unreliable.", "summary_zh": "莫尔斯宣布不再在社媒做体育伤病分析，称持续压力、负面曝光令其不可持续，希望专注肽类、再生医学与诊疗。此前他断言新冠疫苗「无疑」促成老鹰四分卫贾伦·赫茨血栓——由小腿问题发展为严重肺栓塞并需抗凝——引发反弹。幻想体育玩家有人惋惜其洞察，也有人松口气或嘲讽其判断不可靠。", "body_en": "NFL Injury Analyst Dr. Jesse Morse Retires from Social Media Breakdowns.\n\nDr. Jesse Morse built a following breaking down NFL injuries since 2017, but the headaches and negativity finally pushed him to step away.\n\nMorse announced he's done with sports injury analysis on social media, calling it unsustainable due to constant stress, negative publicity, and a wish to focus on peptides, regenerative medicine, and his practice.\n\nThe move follows backlash over his claim that the COVID-19 vaccine undoubtedly contributed to Eagles QB Jalen Hurts' blood clots, which progressed from a calf issue to serious lung emboli, sidelining him on blood thinners. Fans and fantasy players reacted with a mix of disappointment from those who valued his insights and relief or mockery from critics who saw his takes as unreliable.", "body_zh": "NFL 伤病分析师杰西·莫尔斯医生退出社媒伤病解读。\n\n杰西·莫尔斯医生自 2017 年起靠拆解 NFL 伤病积累粉丝，但头痛与负面舆论最终令他抽身。\n\n莫尔斯宣布不再在社媒做体育伤病分析，称持续压力、负面曝光令其不可持续，希望专注肽类、再生医学与诊疗。此前他断言新冠疫苗「无疑」促成老鹰四分卫贾伦·赫茨血栓——由小腿问题发展为严重肺栓塞并需抗凝——引发反弹。\n\n幻想体育玩家有人惋惜其洞察，也有人松口气或嘲讽其判断不可靠。", "url": "https://x.com/i/trending/2112324176434368674", "category": "Sports", "topics": ["Sports"], "updated_at": "2026-10-20T03:14:14.000Z"}, {"id": "2112324174198739085", "domain": "体育", "title_en": "Soccer vs. American Football Fan Debate Explodes Over Global Popularity Video", "title_zh": "足球与美式橄榄球球迷为「全球人气」视频激烈互怼", "hook_en": "A video ranking the world's top sports from 1900 to 2026 has fans fiercely defending their favorites, with soccer's massive global following clashing against the NFL's revenue dominance.", "hook_zh": "一段排列 1900–2026 世界热门运动的视频让粉丝力挺所爱：足球的全球拥趸对上 NFL 的营收统治力。", "summary_en": "The video shows soccer leading with 3.5 to 4 billion fans worldwide, while American football trails in the low hundreds of millions on fan count lists. Yet the NFL tops all sports in revenue, distributing over $14 billion annually, prompting arguments over whether global popularity or financial power defines a sport's success. Soccer supporters call the NFL a 'small regional sport' like badminton, while U.S. fans prioritize domestic viewership, high salaries, and market strength over international surveys. Both sides stick to their preferred metrics in this ongoing rivalry.", "summary_zh": "视频显示足球以全球约 35–40 亿粉丝领先，美式橄榄球粉丝量仅数亿级；但 NFL 营收居所有运动之首，年分账逾 140 亿美元，引发「人气还是金流定义成功」之争。足球拥趸称 NFL 像羽毛球般「区域小项」，美国粉丝则更看重国内收视、高薪与市场实力而非国际调查。双方各执偏好指标，恩怨难休。", "body_en": "Soccer vs. American Football Fan Debate Explodes Over Global Popularity Video.\n\nA video ranking the world's top sports from 1900 to 2026 has fans fiercely defending their favorites, with soccer's massive global following clashing against the NFL's revenue dominance.\n\nThe video shows soccer leading with 3.5 to 4 billion fans worldwide, while American football trails in the low hundreds of millions on fan count lists.\n\nYet the NFL tops all sports in revenue, distributing over $14 billion annually, prompting arguments over whether global popularity or financial power defines a sport's success.Soccer supporters call the NFL a 'small regional sport' like badminton, while U.S. fans prioritize domestic viewership, high salaries, and market strength over international surveys.Both sides stick to their preferred metrics in this ongoing rivalry.", "body_zh": "足球与美式橄榄球球迷为「全球人气」视频激烈互怼。\n\n一段排列 1900–2026 世界热门运动的视频让粉丝力挺所爱：足球的全球拥趸对上 NFL 的营收统治力。\n\n视频显示足球以全球约 35–40 亿粉丝领先，美式橄榄球粉丝量仅数亿级；但 NFL 营收居所有运动之首，年分账逾 140 亿美元，引发「人气还是金流定义成功」之争。足球拥趸称 NFL 像羽毛球般「区域小项」，美国粉丝则更看重国内收视、高薪与市场实力而非国际调查。\n\n双方各执偏好指标，恩怨难休。", "url": "https://x.com/i/trending/2112324174198739085", "category": "Sports", "topics": ["American Football"], "updated_at": "2026-10-19T23:30:44.000Z"}, {"id": "2112078869360726394", "domain": "娱乐", "title_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore", "title_zh": "邝玲玲亮相卡地亚新加坡「Into The Wild」活动", "hook_en": "Lingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.", "hook_zh": "邝玲玲身着闪亮黑色亮片礼服与戏剧感花卉手套，在丛林风布景前自信亮相。", "summary_en": "On October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry. She stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "summary_zh": "10 月 19 日，泰国演员邝玲玲出席卡地亚新加坡「Into The Wild」活动，呼应品牌黑豹与动物主题珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配银色链条、手镯与夸张耳环。粉丝称赞其笑容与气质。沉浸式体验 10 月 21–25 日对公众开放于 Rochester Park 17 号，部分展陈延续至 ION Orchard 至 11 月初。", "body_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore.\n\nLingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.\n\nOn October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry.\n\nShe stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "body_zh": "邝玲玲亮相卡地亚新加坡「Into The Wild」活动。\n\n邝玲玲身着闪亮黑色亮片礼服与戏剧感花卉手套，在丛林风布景前自信亮相。\n\n10 月 19 日，泰国演员邝玲玲出席卡地亚新加坡「Into The Wild」活动，呼应品牌黑豹与动物主题珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配银色链条、手镯与夸张耳环。\n\n粉丝称赞其笑容与气质。沉浸式体验 10 月 21–25 日对公众开放于 Rochester Park 17 号，部分展陈延续至 ION Orchard 至 11 月初。", "url": "https://x.com/i/trending/2112078869360726394", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T06:02:16.000Z"}, {"id": "2112350415979446623", "domain": "娱乐", "title_en": "Whalefall Movie Mixes Survival Thrills with Father-Son Grief", "title_zh": "电影《Whalefall》交织求生惊悚与父子哀恸", "hook_en": "Imagine being swallowed by a sperm whale, fighting for breath while flashbacks reveal a son's longing for his dad's acceptance. That's the raw emotional pull at the heart of Whalefall.", "hook_zh": "想象被抹香鲸吞入、挣扎求生，闪回却是儿子渴望父亲认可——这是《Whalefall》的情感内核。", "summary_en": "Released October 16, 2026, by 20th Century Studios, the film stars Austin Abrams as scuba diver Jay, who gets trapped inside a massive whale searching for his father's remains, with Josh Brolin appearing in poignant flashbacks. It blends tense survival horror from Daniel Kraus's novel with themes of grief and reconciliation, earning praise for heartfelt father-son moments amid mixed reviews on emotional pacing. Opening weekend brought in $17.5M worldwide against a $60M budget, while viewers connect deeply to scenes like Jay hallucinating his whale-formed dad asking about his life.", "summary_zh": "二十世纪影业 2026 年 10 月 16 日发行，奥斯汀·艾布拉姆斯饰潜水员杰伊，为寻父遗骸困于巨鲸体内，乔什·布洛林于闪回中现身。影片融丹尼尔·克劳斯小说的幽闭求生与哀恸和解主题，父子戏获赞。北美首周末约 800 万美元、全球约 1750 万（预算约 6000 万）。小岛秀夫称赞鲸鱼设定与特效；艾布拉姆斯自述拍摄后外观狼狈到曾惊动安保。", "body_en": "Whalefall Movie Mixes Survival Thrills with Father-Son Grief.\n\nImagine being swallowed by a sperm whale, fighting for breath while flashbacks reveal a son's longing for his dad's acceptance. That's the raw emotional pull at the heart of Whalefall.\n\nReleased October 16, 2026, by 20th Century Studios, the film stars Austin Abrams as scuba diver Jay, who gets trapped inside a massive whale searching for his father's remains, with Josh Brolin appearing in poignant flashbacks.\n\nIt blends tense survival horror from Daniel Kraus's novel with themes of grief and reconciliation, earning praise for heartfelt father-son moments amid mixed reviews on emotional pacing. Opening weekend brought in $17.5M worldwide against a $60M budget, while viewers connect deeply to scenes like Jay hallucinating his whale-formed dad asking about his life.", "body_zh": "电影《Whalefall》交织求生惊悚与父子哀恸。\n\n想象被抹香鲸吞入、挣扎求生，闪回却是儿子渴望父亲认可——这是《Whalefall》的情感内核。\n\n二十世纪影业 2026 年 10 月 16 日发行，奥斯汀·艾布拉姆斯饰潜水员杰伊，为寻父遗骸困于巨鲸体内，乔什·布洛林于闪回中现身。影片融丹尼尔·克劳斯小说的幽闭求生与哀恸和解主题，父子戏获赞。\n\n北美首周末约 800 万美元、全球约 1750 万（预算约 6000 万）。小岛秀夫称赞鲸鱼设定与特效；艾布拉姆斯自述拍摄后外观狼狈到曾惊动安保。", "url": "https://x.com/i/trending/2112350415979446623", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T05:49:41.000Z"}, {"id": "2112743486222905714", "domain": "娱乐", "title_en": "Skarsgård Brothers Shine Arm-in-Arm at Wicker Premiere", "title_zh": "史卡斯加德兄弟挽臂亮相《Wicker》首映", "hook_en": "Bill and Alexander Skarsgård linked arms on the red carpet, grinning for fans in sharply contrasting outfits that turned heads.", "hook_zh": "比尔与亚历山大·史卡斯加德红毯挽臂微笑，造型反差鲜明，引得围观者侧目。", "summary_en": "At the Los Angeles premiere of romantic fantasy comedy Wicker, Bill arrived in a tailored burgundy suit while Alexander rocked a black top with a bold half-and-half plaid skirt by Chopova Lowena. The brothers' heartwarming pose drew cheers, and Alexander later shared on the Q&A panel how fun it was to play a tender-hearted husband in the wicker suit—a nice change from his usual roles. Directed by Alex Huston Fischer and Eleanor Wilson, the Sundance-acclaimed film follows a fisherwoman's wicker-made husband sparking romance and chaos; it hits limited U.S. theaters October 23, 2026, with stars like Olivia Colman and Peter Dinklage.", "summary_zh": "浪漫奇幻喜剧《Wicker》洛杉矶首映上，比尔身着酒红定制西装，亚历山大则穿黑色上衣搭配 Chopova Lowena 半边格纹裙。兄弟温馨合影赢得欢呼；亚历山大在问答环节称饰演柳条服里温柔丈夫很有趣，有别于以往角色。影片由 Alex Huston Fischer 与 Eleanor Wilson 执导，圣丹斯好评，讲述渔妇的柳条丈夫引发爱情与混乱，奥利维娅·科尔曼、彼得·丁拉基等出演，2026 年 10 月 23 日美国有限上映。", "body_en": "Skarsgård Brothers Shine Arm-in-Arm at Wicker Premiere.\n\nBill and Alexander Skarsgård linked arms on the red carpet, grinning for fans in sharply contrasting outfits that turned heads.\n\nAt the Los Angeles premiere of romantic fantasy comedy Wicker, Bill arrived in a tailored burgundy suit while Alexander rocked a black top with a bold half-and-half plaid skirt by Chopova Lowena.\n\nThe brothers' heartwarming pose drew cheers, and Alexander later shared on the Q&A panel how fun it was to play a tender-hearted husband in the wicker suit—a nice change from his usual roles. Directed by Alex Huston Fischer and Eleanor Wilson, the Sundance-acclaimed film follows a fisherwoman's wicker-made husband sparking romance and chaos; it hits limited U.S.theaters October 23, 2026, with stars like Olivia Colman and Peter Dinklage.", "body_zh": "史卡斯加德兄弟挽臂亮相《Wicker》首映。\n\n比尔与亚历山大·史卡斯加德红毯挽臂微笑，造型反差鲜明，引得围观者侧目。\n\n浪漫奇幻喜剧《Wicker》洛杉矶首映上，比尔身着酒红定制西装，亚历山大则穿黑色上衣搭配 Chopova Lowena 半边格纹裙。兄弟温馨合影赢得欢呼；亚历山大在问答环节称饰演柳条服里温柔丈夫很有趣，有别于以往角色。\n\n影片由 Alex Huston Fischer 与 Eleanor Wilson 执导，圣丹斯好评，讲述渔妇的柳条丈夫引发爱情与混乱，奥利维娅·科尔曼、彼得·丁拉基等出演，2026 年 10 月 23 日美国有限上映。", "url": "https://x.com/i/trending/2112743486222905714", "category": "Entertainment", "topics": ["Movies & TV", "Celebrity"], "updated_at": "2026-10-21T05:49:11.000Z"}, {"id": "2112653365356433717", "domain": "娱乐", "title_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk", "title_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论", "hook_en": "A post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.", "hook_zh": "有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。", "summary_en": "Ariana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office. Seyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "summary_zh": "爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "body_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk.\n\nA post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.\n\nAriana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M.Chu's hit musical films, which have pulled in hundreds of millions at the box office.\n\nSeyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate.The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "body_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论。\n\n有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。\n\n爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。\n\n粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "url": "https://x.com/i/trending/2112653365356433717", "category": "Entertainment", "topics": ["Movies & TV", "Celebrity"], "updated_at": "2026-10-21T00:31:26.000Z"}, {"id": "2112623564083876203", "domain": "娱乐", "title_en": "Hudson Williams Embraces New Role in 'Yaga' with Fan Support", "title_zh": "哈德森·威廉姆斯新剧《Yaga》获粉丝力挺", "hook_en": "Hudson Williams felt a wave of relief when fans cheered his leap from steamy hockey romance to supernatural thriller. Their excitement for 'Yaga' showed his appeal goes beyond one hit role.", "hook_zh": "哈德森·威廉姆斯从火热冰球爱情戏跳到超自然惊悚，粉丝欢呼令他松口气——说明魅力不止于一个爆款角色。", "summary_en": "The 25-year-old Canadian actor, known for Shane Hollander in 'Heated Rivalry,' stars in dual roles as Henry Park and Logan in the upcoming Crave and AMC+ series 'Yaga,' premiering October 23. The show reimagines Slavic folklore with Baba Yaga in a modern mystery thriller featuring desire, ancient magic, and leads like Carrie-Anne Moss and Noah Reid. On set, Williams shared laughs with 'Heated Rivalry' nods, while opening up about fame's challenges like privacy invasions, yet crediting fans for keeping his work alive. Their warm responses highlight his growing, versatile draw.", "summary_zh": "这名 25 岁加拿大演员因《Heated Rivalry》中 Shane Hollander 知名，将在 Crave 与 AMC+ 剧集《Yaga》中分饰 Henry Park 与 Logan，10 月 23 日首播。剧集以现代神秘惊悚重塑斯拉夫民间 Baba Yaga，含欲望与古老魔法，卡丽-安·莫斯、诺亚·里德等主演。片场他笑谈《Heated Rivalry》梗，并谈及成名后隐私被侵等挑战，感谢粉丝让作品保持生命力。", "body_en": "Hudson Williams Embraces New Role in 'Yaga' with Fan Support.\n\nHudson Williams felt a wave of relief when fans cheered his leap from steamy hockey romance to supernatural thriller. Their excitement for 'Yaga' showed his appeal goes beyond one hit role.\n\nThe 25-year-old Canadian actor, known for Shane Hollander in 'Heated Rivalry,' stars in dual roles as Henry Park and Logan in the upcoming Crave and AMC+ series 'Yaga,' premiering October 23.\n\nThe show reimagines Slavic folklore with Baba Yaga in a modern mystery thriller featuring desire, ancient magic, and leads like Carrie-Anne Moss and Noah Reid. On set, Williams shared laughs with 'Heated Rivalry' nods, while opening up about fame's challenges like privacy invasions, yet crediting fans for keeping his work alive.Their warm responses highlight his growing, versatile draw.", "body_zh": "哈德森·威廉姆斯新剧《Yaga》获粉丝力挺。\n\n哈德森·威廉姆斯从火热冰球爱情戏跳到超自然惊悚，粉丝欢呼令他松口气——说明魅力不止于一个爆款角色。\n\n这名 25 岁加拿大演员因《Heated Rivalry》中 Shane Hollander 知名，将在 Crave 与 AMC+ 剧集《Yaga》中分饰 Henry Park 与 Logan，10 月 23 日首播。剧集以现代神秘惊悚重塑斯拉夫民间 Baba Yaga，含欲望与古老魔法，卡丽-安·莫斯、诺亚·里德等主演。\n\n片场他笑谈《Heated Rivalry》梗，并谈及成名后隐私被侵等挑战，感谢粉丝让作品保持生命力。", "url": "https://x.com/i/trending/2112623564083876203", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T23:00:33.000Z"}, {"id": "2112504739321512216", "domain": "娱乐", "title_en": "Mile Phakphum Shines at REM Hotel's Grand Opening in Macau", "title_zh": "Mile Phakphum 亮相澳门 REM 酒店盛大开业", "hook_en": "Mile Phakphum stepped into the spotlight at REM's grand opening, his crisp white suit and red rose boutonniere turning heads amid dreamlike red balloon-dog sculptures.", "hook_zh": "Mile Phakphum 现身 REM 开业典礼，白色西装配红玫瑰襟花，在梦幻红色气球狗雕塑间成为焦点。", "summary_en": "On October 20, Thai actor and singer Mile Phakphum attended the full launch of REM, a new luxury hotel at City of Dreams Macau, after its soft opening in August. He posed confidently in a white suit jacket with black trousers, accented by a vibrant red rose and blue cord, while mingling with fans and chatting about the hotel's creative spaces. The REM property, inspired by REM sleep, offers 149 suite-style rooms in a red-and-metallic palette, including a top-floor villa with a rotating bed and suspended pool. Fans praised his handsome, standout presence as social media filled with photos from the high-energy event.", "summary_zh": "10 月 20 日，泰国演员兼歌手 Mile Phakphum 出席澳门新濠天地全新奢华酒店 REM 正式开业（8 月曾软开）。他着白西装外套配黑裤，红玫瑰与蓝绳点缀，与粉丝互动并聊酒店创意空间。REM 以快速眼动睡眠为灵感，149 间套房式客房红金属色调，顶层别墅含旋转床与悬浮泳池。粉丝盛赞其出众气场，社交平台晒照不断。", "body_en": "Mile Phakphum Shines at REM Hotel's Grand Opening in Macau.\n\nMile Phakphum stepped into the spotlight at REM's grand opening, his crisp white suit and red rose boutonniere turning heads amid dreamlike red balloon-dog sculptures.\n\nOn October 20, Thai actor and singer Mile Phakphum attended the full launch of REM, a new luxury hotel at City of Dreams Macau, after its soft opening in August.\n\nHe posed confidently in a white suit jacket with black trousers, accented by a vibrant red rose and blue cord, while mingling with fans and chatting about the hotel's creative spaces. The REM property, inspired by REM sleep, offers 149 suite-style rooms in a red-and-metallic palette, including a top-floor villa with a rotating bed and suspended pool.Fans praised his handsome, standout presence as social media filled with photos from the high-energy event.", "body_zh": "Mile Phakphum 亮相澳门 REM 酒店盛大开业。\n\nMile Phakphum 现身 REM 开业典礼，白色西装配红玫瑰襟花，在梦幻红色气球狗雕塑间成为焦点。\n\n10 月 20 日，泰国演员兼歌手 Mile Phakphum 出席澳门新濠天地全新奢华酒店 REM 正式开业（8 月曾软开）。他着白西装外套配黑裤，红玫瑰与蓝绳点缀，与粉丝互动并聊酒店创意空间。\n\nREM 以快速眼动睡眠为灵感，149 间套房式客房红金属色调，顶层别墅含旋转床与悬浮泳池。粉丝盛赞其出众气场，社交平台晒照不断。", "url": "https://x.com/i/trending/2112504739321512216", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T20:42:51.000Z"}, {"id": "2112605676610478278", "domain": "娱乐", "title_en": "Jaafar Jackson Wins Actor Award for Michael Jackson Role in 'Michael'", "title_zh": "贾法尔·杰克逊凭《Michael》迈克尔·杰克逊一角获演员奖", "hook_en": "Jaafar Jackson, nephew of the King of Pop, steps into the spotlight with a Critics Choice honor for his feature debut as Michael Jackson.", "hook_zh": "「流行之王」侄子贾法尔·杰克逊凭长片处女作饰演迈克尔·杰克逊，获评论选择荣誉，站上聚光灯。", "summary_en": "The Critics Choice Association named Jaafar Jackson the Actor Award – Film recipient at the 9th Annual Celebration of Black Cinema & Television for his portrayal in Lionsgate's 'Michael,' the first biopic to top $1 billion worldwide and Lionsgate's biggest release ever. Directed by Antoine Fuqua, the film traces Michael Jackson's rise and drew strong box-office success since opening in April. The ceremony happens November 16, 2026, at Fairmont Century Plaza in Los Angeles, with others like Debbie Allen receiving honors too. Fans celebrated the news, praising his acclaimed performance.", "summary_zh": "评论选择协会将第 9 届黑人电影与电视庆典「电影演员奖」授予贾法尔·杰克逊，表彰其在狮门《Michael》中的演绎——该片为全球票房破 10 亿美元的首部传记片，亦是狮门史上最大发行。安东尼·福奎阿执导，追溯杰克逊崛起，4 月上映后票房强劲。典礼 2026 年 11 月 16 日在洛杉矶 Fairmont Century Plaza 举行，黛比·艾伦等亦获表彰。粉丝庆祝并称赞其获好评的表演。", "body_en": "Jaafar Jackson Wins Actor Award for Michael Jackson Role in 'Michael'.\n\nJaafar Jackson, nephew of the King of Pop, steps into the spotlight with a Critics Choice honor for his feature debut as Michael Jackson.\n\nThe Critics Choice Association named Jaafar Jackson the Actor Award – Film recipient at the 9th Annual Celebration of Black Cinema & Television for his portrayal in Lionsgate's 'Michael,' the first biopic to top $1 billion worldwide and Lionsgate's biggest release ever.\n\nDirected by Antoine Fuqua, the film traces Michael Jackson's rise and drew strong box-office success since opening in April.The ceremony happens November 16, 2026, at Fairmont Century Plaza in Los Angeles, with others like Debbie Allen receiving honors too. Fans celebrated the news, praising his acclaimed performance.", "body_zh": "贾法尔·杰克逊凭《Michael》迈克尔·杰克逊一角获演员奖。\n\n「流行之王」侄子贾法尔·杰克逊凭长片处女作饰演迈克尔·杰克逊，获评论选择荣誉，站上聚光灯。\n\n评论选择协会将第 9 届黑人电影与电视庆典「电影演员奖」授予贾法尔·杰克逊，表彰其在狮门《Michael》中的演绎——该片为全球票房破 10 亿美元的首部传记片，亦是狮门史上最大发行。安东尼·福奎阿执导，追溯杰克逊崛起，4 月上映后票房强劲。\n\n典礼 2026 年 11 月 16 日在洛杉矶 Fairmont Century Plaza 举行，黛比·艾伦等亦获表彰。粉丝庆祝并称赞其获好评的表演。", "url": "https://x.com/i/trending/2112605676610478278", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T18:15:13.000Z"}, {"id": "2112506238923608157", "domain": "娱乐", "title_en": "Fans Adore Pooh Krittin and Pavel Naret's Grim Reaper Promo Photos", "title_zh": "粉丝热捧 Pooh 与 Pavel《死神恋人》宣传照", "hook_en": "Pooh Krittin channels a brooding grim reaper with flowing dark hair and moody blue lighting, while Pavel Naret contrasts in a crisp white shirt—their chemistry already leaping off the screen.", "hook_zh": "Pooh Krittin 黑发阴郁死神造型配冷蓝光，Pavel Naret 白衬衫对比鲜明——化学反应已溢出屏幕。", "summary_en": "The promotional images for the upcoming fantasy romance series 'The Grim Lover' showcase Pooh as the grim reaper Sibsi (aka Fourteen or Rafah) and Pavel as grieving anesthesiologist Vivorn Assarak (Won), adapted from a web novel blending boys' love, fantasy, romance, and drama. Fans rave about the 'lethal visuals' and 'insane' pairing chemistry, with one calling Pooh 'the handsomest Reaper' ever. Produced by Change2561, the series airs on One 31 and streams globally on Netflix, with a fan event 'ROAD TO THE GRIM LOVER' set for November 18, 2026, at ICONSIAM Hall in Bangkok—tickets on sale October 30.", "summary_zh": "奇幻爱情剧《The Grim Lover》宣传照中，Pooh 饰死神 Sibsi（Fourteen/Rafah），Pavel 饰哀悼中的麻醉医生 Vivorn Assarak（Won），改编融合 BL、奇幻、爱情与戏剧的网络小说。粉丝狂赞「致命视觉」与「疯狂」配对，有人称 Pooh「史上最帅死神」。Change2561 制作，One 31 播出、Netflix 全球上线；粉丝活动 ROAD TO THE GRIM LOVER 定于 2026 年 11 月 18 日曼谷 ICONSIAM Hall，门票 10 月 30 日开售。", "body_en": "Fans Adore Pooh Krittin and Pavel Naret's Grim Reaper Promo Photos.\n\nPooh Krittin channels a brooding grim reaper with flowing dark hair and moody blue lighting, while Pavel Naret contrasts in a crisp white shirt—their chemistry already leaping off the screen.\n\nThe promotional images for the upcoming fantasy romance series 'The Grim Lover' showcase Pooh as the grim reaper Sibsi (aka Fourteen or Rafah) and Pavel as grieving anesthesiologist Vivorn Assarak (Won), adapted from a web novel blending boys' love, fantasy, romance, and drama.\n\nFans rave about the 'lethal visuals' and 'insane' pairing chemistry, with one calling Pooh 'the handsomest Reaper' ever. Produced by Change2561, the series airs on One 31 and streams globally on Netflix, with a fan event 'ROAD TO THE GRIM LOVER' set for November 18, 2026, at ICONSIAM Hall in Bangkok—tickets on sale October 30.", "body_zh": "粉丝热捧 Pooh 与 Pavel《死神恋人》宣传照。\n\nPooh Krittin 黑发阴郁死神造型配冷蓝光，Pavel Naret 白衬衫对比鲜明——化学反应已溢出屏幕。\n\n奇幻爱情剧《The Grim Lover》宣传照中，Pooh 饰死神 Sibsi（Fourteen/Rafah），Pavel 饰哀悼中的麻醉医生 Vivorn Assarak（Won），改编融合 BL、奇幻、爱情与戏剧的网络小说。粉丝狂赞「致命视觉」与「疯狂」配对，有人称 Pooh「史上最帅死神」。\n\nChange2561 制作，One 31 播出、Netflix 全球上线；粉丝活动 ROAD TO THE GRIM LOVER 定于 2026 年 11 月 18 日曼谷 ICONSIAM Hall，门票 10 月 30 日开售。", "url": "https://x.com/i/trending/2112506238923608157", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T11:32:52.000Z"}, {"id": "2112465474994737570", "domain": "娱乐", "title_en": "The Grim Lover Unveils Striking Visuals and Bangkok Fansign Event", "title_zh": "《The Grim Lover》释出吸睛视觉，曼谷粉丝见面会将办", "hook_en": "Pooh Krittin channels a mysterious grim reaper with flowing black hair, while Pavel Naret stands poised as a doctor in white – fans can't get enough of their chemistry.", "hook_zh": "Pooh Krittin 饰神秘黑发死神，Pavel Naret 饰白衣医生，粉丝对他们的化学反应欲罢不能。", "summary_en": "The Thai BL series The Grim Lover, starring Krittin as grim reaper Sibsi (Fourteen or Rafah) and Naret as anesthesiologist Vivorn Assarak (Won), adapts a web novel blending fantasy, romance, and drama. It follows Won, who loses his partner in an accident, faces murder accusations, and connects with a reaper bearing his love's face. The show premieres November 28, 2026, on One 31 in Thailand and Netflix worldwide, with a ROAD TO THE GRIM LOVER fansign on November 18 at ICONSIAM HALL in Bangkok – tickets on sale October 30 via THAITICKETMAJOR, featuring meet-and-greets and games. Fans praise the actors' 'lethal visuals' and pairing as 'FourteenWon supremacy.'", "summary_zh": "泰国 BL 剧《The Grim Lover》由 Krittin 饰死神 Sibsi（Fourteen/Rafah）、Naret 饰麻醉医生 Vivorn Assarak（Won），改编融合奇幻、爱情与戏剧的网络小说。故事中 Won 因事故失去伴侣、面临谋杀指控，并与一张酷似爱人面孔的死神产生纠葛。剧集 2026 年 11 月 28 日在泰国 One 31 首播、Netflix 全球上线；11 月 18 日曼谷 ICONSIAM HALL 举办 ROAD TO THE GRIM LOVER 粉丝签名会，门票 10 月 30 日起经 THAITICKETMAJOR 开售。粉丝称视觉「致命」、配对「FourteenWon 至上」。", "body_en": "The Grim Lover Unveils Striking Visuals and Bangkok Fansign Event.\n\nPooh Krittin channels a mysterious grim reaper with flowing black hair, while Pavel Naret stands poised as a doctor in white – fans can't get enough of their chemistry.\n\nThe Thai BL series The Grim Lover, starring Krittin as grim reaper Sibsi (Fourteen or Rafah) and Naret as anesthesiologist Vivorn Assarak (Won), adapts a web novel blending fantasy, romance, and drama.\n\nIt follows Won, who loses his partner in an accident, faces murder accusations, and connects with a reaper bearing his love's face. The show premieres November 28, 2026, on One 31 in Thailand and Netflix worldwide, with a ROAD TO THE GRIM LOVER fansign on November 18 at ICONSIAM HALL in Bangkok – tickets on sale October 30 via THAITICKETMAJOR, featuring meet-and-greets and games. Fans praise the actors' 'lethal visuals' and pairing as 'FourteenWon supremacy.'", "body_zh": "《The Grim Lover》释出吸睛视觉，曼谷粉丝见面会将办。\n\nPooh Krittin 饰神秘黑发死神，Pavel Naret 饰白衣医生，粉丝对他们的化学反应欲罢不能。\n\n泰国 BL 剧《The Grim Lover》由 Krittin 饰死神 Sibsi（Fourteen/Rafah）、Naret 饰麻醉医生 Vivorn Assarak（Won），改编融合奇幻、爱情与戏剧的网络小说。故事中 Won 因事故失去伴侣、面临谋杀指控，并与一张酷似爱人面孔的死神产生纠葛。", "url": "https://x.com/i/trending/2112465474994737570", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T08:52:08.000Z"}, {"id": "2111997785189093552", "domain": "娱乐", "title_en": "Netflix's Norm Macdonald Documentary Draws Laughs and Mixed Views", "title_zh": "Netflix 诺曼·麦克唐纳纪录片引笑声与分歧评价", "hook_en": "Five years after Norm Macdonald's death at 61, fans are revisiting his deadpan genius through a new Netflix film that mixes laughs with heartfelt memories.", "hook_zh": "诺曼·麦克唐纳 61 岁去世五年后，粉丝通过 Netflix 新片重温其冷面天才，笑声夹杂深情回忆。", "summary_en": "Directed by Judd Apatow, 'Norm: The Tale of Norm Macdonald' premiered October 16 and runs two hours, using archival clips, home videos, photos, and his own audiobook narration instead of new interviews. Viewers praise it as a worthy tribute to his SNL Weekend Update days, O.J. jokes, and legendary timing, with some left laughing and crying over the man they miss. Others call it a clip show lacking fresh insight or his edgier routines, like certain 9/11 bits, though it highlights his private cancer battle and uncompromised style. The responses reflect his enduring, divisive impact on comedy.", "summary_zh": "贾德·阿帕图执导的《Norm: The Tale of Norm Macdonald》10 月 16 日首播，长约两小时，以档案片段、家庭录像、照片及其有声书旁白取代新采访。观众赞其为对 SNL 周末更新、O.J. 笑话与传奇节奏感的得体致敬，有人又笑又哭；亦有人觉像剪辑秀、缺新洞见或其更锐利段子。影片亦触及他私下抗癌与不妥协风格，反映其喜剧遗产的持久与争议。", "body_en": "Netflix's Norm Macdonald Documentary Draws Laughs and Mixed Views.\n\nFive years after Norm Macdonald's death at 61, fans are revisiting his deadpan genius through a new Netflix film that mixes laughs with heartfelt memories.\n\nDirected by Judd Apatow, 'Norm: The Tale of Norm Macdonald' premiered October 16 and runs two hours, using archival clips, home videos, photos, and his own audiobook narration instead of new interviews.Viewers praise it as a worthy tribute to his SNL Weekend Update days, O.J.\n\njokes, and legendary timing, with some left laughing and crying over the man they miss.Others call it a clip show lacking fresh insight or his edgier routines, like certain 9/11 bits, though it highlights his private cancer battle and uncompromised style. The responses reflect his enduring, divisive impact on comedy.", "body_zh": "Netflix 诺曼·麦克唐纳纪录片引笑声与分歧评价。\n\n诺曼·麦克唐纳 61 岁去世五年后，粉丝通过 Netflix 新片重温其冷面天才，笑声夹杂深情回忆。\n\n贾德·阿帕图执导的《Norm: The Tale of Norm Macdonald》10 月 16 日首播，长约两小时，以档案片段、家庭录像、照片及其有声书旁白取代新采访。观众赞其为对 SNL 周末更新、O.J. 笑话与传奇节奏感的得体致敬，有人又笑又哭；亦有人觉像剪辑秀、缺新洞见或其更锐利段子。\n\n影片亦触及他私下抗癌与不妥协风格，反映其喜剧遗产的持久与争议。", "url": "https://x.com/i/trending/2111997785189093552", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T05:10:09.000Z"}, {"id": "2111698777392250940", "domain": "娱乐", "title_en": "Jenna Ortega Wows Fans in Stylish Klara and the Sun Tour", "title_zh": "珍娜·奥尔特加《克拉拉与太阳》宣传造型圈粉", "hook_en": "Jenna Ortega turned heads at film festivals, rocking a vintage Pierre Cardin dress with a bullseye motif that perfectly matched the movie's solar vibe.", "hook_zh": "珍娜·奥尔特加亮相电影节，复古皮尔·卡丹靶心纹连衣裙完美呼应影片「太阳」气质。", "summary_en": "She's been promoting Taika Waititi's adaptation of Kazuo Ishiguro’s novel, hitting the Rome Film Festival in that iconic 1966 mod dress and a New York screening on October 19 at Crosby Street Hotel alongside co-stars. Fans shared red-carpet glamour like her sparkling fringed gown and pink strapless dress, plus candid clips of her talking with her hands and a heartfelt fan sign saying 'JENNA YOU’RE SO LOVED' with an Italian flag heart. Playful reactions poured in, from calling her 'the people’s princess' to one post joking 'tears running down my thighs,' as the film nears its October 23 release.", "summary_zh": "她为塔伊加·维迪提改编石黑一雄小说的影片宣传，罗马电影节着 1966 年经典摩登裙，10 月 19 日纽约 Crosby Street Hotel 与联合主演出席放映。粉丝分享流苏闪光礼服、粉色抹胸等红毯造型，以及她说话时比手势的花絮和写着「JENNA YOU'RE SO LOVED」配意大利心旗的粉丝牌。有人呼「人民公主」，影片将于 10 月 23 日上映。", "body_en": "Jenna Ortega Wows Fans in Stylish Klara and the Sun Tour.\n\nJenna Ortega turned heads at film festivals, rocking a vintage Pierre Cardin dress with a bullseye motif that perfectly matched the movie's solar vibe.\n\nShe's been promoting Taika Waititi's adaptation of Kazuo Ishiguro’s novel, hitting the Rome Film Festival in that iconic 1966 mod dress and a New York screening on October 19 at Crosby Street Hotel alongside co-stars.\n\nFans shared red-carpet glamour like her sparkling fringed gown and pink strapless dress, plus candid clips of her talking with her hands and a heartfelt fan sign saying 'JENNA YOU’RE SO LOVED' with an Italian flag heart. Playful reactions poured in, from calling her 'the people’s princess' to one post joking 'tears running down my thighs,' as the film nears its October 23 release.", "body_zh": "珍娜·奥尔特加《克拉拉与太阳》宣传造型圈粉。\n\n珍娜·奥尔特加亮相电影节，复古皮尔·卡丹靶心纹连衣裙完美呼应影片「太阳」气质。\n\n她为塔伊加·维迪提改编石黑一雄小说的影片宣传，罗马电影节着 1966 年经典摩登裙，10 月 19 日纽约 Crosby Street Hotel 与联合主演出席放映。粉丝分享流苏闪光礼服、粉色抹胸等红毯造型，以及她说话时比手势的花絮和写着「JENNA YOU'RE SO LOVED」配意大利心旗的粉丝牌。\n\n有人呼「人民公主」，影片将于 10 月 23 日上映。", "url": "https://x.com/i/trending/2111698777392250940", "category": "Entertainment", "topics": ["Movies & TV", "Celebrity"], "updated_at": "2026-10-20T03:36:02.000Z"}, {"id": "2111675291110088931", "domain": "娱乐", "title_en": "Taylor Swift Shines in Custom Dior at 2026 Academy Museum Gala", "title_zh": "泰勒·斯威夫特定制迪奥惊艳 2026 电影学院博物馆晚会", "hook_en": "Taylor Swift stepped onto the red carpet in a custom icy-blue Dior gown, its soft pleats and sparkling bow catching every eye under the lights.", "hook_zh": "泰勒·斯威夫特红毯亮相冰蓝色定制迪奥礼服，柔褶与闪亮蝴蝶结在灯光下抢尽目光。", "summary_en": "The 2026 Academy Museum Gala on October 17 in Los Angeles raised over $14 million, honoring Charlize Theron, Colman Domingo, and John Carpenter. Swift performed hits like “Blank Space” and “Love Story” in her first full-band show since the Eras Tour, while Sabrina Carpenter and Rosé wowed in ruffled corsets and fringed gowns. Hannah Waddingham shared a warm selfie with Swift, praising her talent, as British Vogue called her the evening's belle in Chopard diamonds topping 40 carats. The horror-themed décor tied into the museum's new exhibition, blending fashion, music, and tributes into a standout night.", "summary_zh": "2026 年 10 月 17 日洛杉矶电影学院博物馆晚会筹得逾 1400 万美元，表彰查理兹·塞隆、科尔曼·多明戈与约翰·卡朋特。斯威夫特自 Eras 巡演后首度全乐队演出《Blank Space》《Love Story》等；Sabrina Carpenter 与 Rosé 也以荷叶边胸衣、流苏礼服惊艳。汉娜·瓦丁厄姆晒与斯威夫特自拍并赞其才华；《英国 Vogue》称其当晚焦点，肖邦钻石超 40 克拉。恐怖主题装饰呼应馆内新展，时尚、音乐与致敬融于一夜。", "body_en": "Taylor Swift Shines in Custom Dior at 2026 Academy Museum Gala.\n\nTaylor Swift stepped onto the red carpet in a custom icy-blue Dior gown, its soft pleats and sparkling bow catching every eye under the lights.\n\nThe 2026 Academy Museum Gala on October 17 in Los Angeles raised over $14 million, honoring Charlize Theron, Colman Domingo, and John Carpenter.\n\nSwift performed hits like “Blank Space” and “Love Story” in her first full-band show since the Eras Tour, while Sabrina Carpenter and Rosé wowed in ruffled corsets and fringed gowns. Hannah Waddingham shared a warm selfie with Swift, praising her talent, as British Vogue called her the evening's belle in Chopard diamonds topping 40 carats. The horror-themed décor tied into the museum's new exhibition, blending fashion, music, and tributes into a standout night.", "body_zh": "泰勒·斯威夫特定制迪奥惊艳 2026 电影学院博物馆晚会。\n\n泰勒·斯威夫特红毯亮相冰蓝色定制迪奥礼服，柔褶与闪亮蝴蝶结在灯光下抢尽目光。\n\n2026 年 10 月 17 日洛杉矶电影学院博物馆晚会筹得逾 1400 万美元，表彰查理兹·塞隆、科尔曼·多明戈与约翰·卡朋特。斯威夫特自 Eras 巡演后首度全乐队演出《Blank Space》《Love Story》等；Sabrina Carpenter 与 Rosé 也以荷叶边胸衣、流苏礼服惊艳。\n\n汉娜·瓦丁厄姆晒与斯威夫特自拍并赞其才华；《英国 Vogue》称其当晚焦点，肖邦钻石超 40 克拉。恐怖主题装饰呼应馆内新展，时尚、音乐与致敬融于一夜。", "url": "https://x.com/i/trending/2111675291110088931", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T03:07:04.000Z"}, {"id": "2112302141629177877", "domain": "娱乐", "title_en": "La Bola Negra Draws Crowds and Debate in U.S. Theaters", "title_zh": "《La Bola Negra》进军美国院线，口碑与争议并存", "hook_en": "A sweeping Spanish epic about gay lives amid war and persecution is pulling in audiences with its emotional depth and stellar performances from Penélope Cruz and Glenn Close.", "hook_zh": "这部讲述战争与迫害中同志人生的西班牙史诗，以情感深度及佩内洛普·克鲁兹、格伦·克洛斯等演技吸引观众。", "summary_en": "Directed by Javier Calvo and Javier Ambrossi, known as Los Javis, La Bola Negra weaves stories of gay men across 1932, 1937 during the Spanish Civil War, and 2017, inspired by Federico García Lorca's unfinished play. The film, which won Best Director at 2026 Cannes and Spain's Oscar entry nod, has grossed over €28 million in Spain on a €15 million budget and expands in U.S. theaters after October 16 limited release. Viewers praise its intertwined timelines and acting, though some online critics question its take on fascism while others defend its depiction of bombings, torture, and generational trauma rooted in Spanish history.", "summary_zh": "由「Los Javis」哈维尔·卡尔沃与哈维尔·安布罗西执导，《La Bola Negra》交织 1932、西班牙内战 1937 与 2017 年同志故事，灵感来自加西亚·洛尔迦未完成剧本。影片获 2026 戛纳最佳导演并成西班牙奥斯卡报名片，西班牙票房逾 2800 万欧元（成本约 1500 万），10 月 16 日美国有限上映后扩映。观众赞时间线交织与演技；网上亦有人质疑其对法西斯的处理，另有人辩护其呈现轰炸、酷刑与代际创伤植根西班牙历史。", "body_en": "La Bola Negra Draws Crowds and Debate in U.S. Theaters.\n\nA sweeping Spanish epic about gay lives amid war and persecution is pulling in audiences with its emotional depth and stellar performances from Penélope Cruz and Glenn Close.\n\nDirected by Javier Calvo and Javier Ambrossi, known as Los Javis, La Bola Negra weaves stories of gay men across 1932, 1937 during the Spanish Civil War, and 2017, inspired by Federico García Lorca's unfinished play.\n\nThe film, which won Best Director at 2026 Cannes and Spain's Oscar entry nod, has grossed over €28 million in Spain on a €15 million budget and expands in U.S.theaters after October 16 limited release. Viewers praise its intertwined timelines and acting, though some online critics question its take on fascism while others defend its depiction of bombings, torture, and generational trauma rooted in Spanish history.", "body_zh": "《La Bola Negra》进军美国院线，口碑与争议并存。\n\n这部讲述战争与迫害中同志人生的西班牙史诗，以情感深度及佩内洛普·克鲁兹、格伦·克洛斯等演技吸引观众。\n\n由「Los Javis」哈维尔·卡尔沃与哈维尔·安布罗西执导，《La Bola Negra》交织 1932、西班牙内战 1937 与 2017 年同志故事，灵感来自加西亚·洛尔迦未完成剧本。影片获 2026 戛纳最佳导演并成西班牙奥斯卡报名片，西班牙票房逾 2800 万欧元（成本约 1500 万），10 月 16 日美国有限上映后扩映。\n\n观众赞时间线交织与演技；网上亦有人质疑其对法西斯的处理，另有人辩护其呈现轰炸、酷刑与代际创伤植根西班牙历史。", "url": "https://x.com/i/trending/2112302141629177877", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-19T22:09:17.000Z"}, {"id": "2112771430316404992", "domain": "科学", "title_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living", "title_zh": "生物圈 2 号实验再引「自给生存」讨论", "hook_en": "Eight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.", "hook_zh": "1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。", "summary_en": "The $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages. A popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "summary_zh": "耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "body_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living.\n\nEight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.\n\nThe $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps.\n\nChallenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages. A popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups.The dome near Tucson now serves as a University of Arizona research site for ecology.", "body_zh": "生物圈 2 号实验再引「自给生存」讨论。\n\n1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。\n\n耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。\n\n热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "url": "https://x.com/i/trending/2112771430316404992", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T07:36:09.000Z"}, {"id": "2112802744491000212", "domain": "科学", "title_en": "UN Report: 1.5°C Limit Overshoot Now Unavoidable But Reversible", "title_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转", "hook_en": "The UN has delivered sobering news: decades of slow climate action mean we'll temporarily exceed the 1.5°C warming limit. But leaders say urgent steps can still pull temperatures back by century's end.", "hook_zh": "联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。", "summary_en": "The UN Environment Programme's 2026 Emissions Gap Report warns current policies head toward 2.8°C warming, with national pledges limiting it to 2.6°C. Even optimistic paths see 1.7-1.8°C by mid-century before a potential return to 1.5°C by 2100, requiring emissions cuts of 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels plus massive carbon removal. UNEP chief Inger Andersen and Secretary-General António Guterres stress that minimizing the overshoot demands pulling out all stops now, building on rapid renewable growth amid rising emissions from coal, oil, and gas.", "summary_zh": "联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。UNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "body_en": "UN Report: 1.5°C Limit Overshoot Now Unavoidable But Reversible.\n\nThe UN has delivered sobering news: decades of slow climate action mean we'll temporarily exceed the 1.5°C warming limit. But leaders say urgent steps can still pull temperatures back by century's end.\n\nThe UN Environment Programme's 2026 Emissions Gap Report warns current policies head toward 2.8°C warming, with national pledges limiting it to 2.6°C.\n\nEven optimistic paths see 1.7-1.8°C by mid-century before a potential return to 1.5°C by 2100, requiring emissions cuts of 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels plus massive carbon removal. UNEP chief Inger Andersen and Secretary-General António Guterres stress that minimizing the overshoot demands pulling out all stops now, building on rapid renewable growth amid rising emissions from coal, oil, and gas.", "body_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转。\n\n联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。\n\n联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。\n\nUNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "url": "https://x.com/i/trending/2112802744491000212", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T07:10:45.000Z"}, {"id": "2112660061256335405", "domain": "科学", "title_en": "Florida Poly Police Debut First U.S. eVTOL for Campus Patrols", "title_zh": "佛州理工警方启用美国校园首架 eVTOL 巡逻", "hook_en": "Imagine a compact flying machine zipping over a sunny campus, letting officers reach remote spots faster than ever. Florida Polytechnic University just made that real with their new electric aircraft named Astro.", "hook_zh": "紧凑电动飞行器掠过阳光校园，警员更快抵达偏远角落。佛罗里达理工大学用名为 Astro 的新电动飞行器把它变成现实。", "summary_en": "The Florida Polytechnic University Police Department introduced the Jetson ONE eVTOL, a single-seat electric flyer reaching 63 mph with 20 minutes of flight time, for surveillance, emergencies, and accessing hard-to-reach areas on the Lakeland campus. Police Chief Aaron Murray called it a proactive step into advanced air mobility, with plans to partner with other agencies once FAA approval comes through. The $150,000 vehicle doubles as an educational tool for the school's aerospace engineering students, amid mixed reactions from excitement over innovation to worries about sky-high surveillance.", "summary_zh": "佛罗里达理工大学警察局推出 Jetson ONE eVTOL：单座电动飞行器时速可达 63 英里、续航约 20 分钟，用于莱克兰校园监控、应急与抵达难达区域。警察局长 Aaron Murray 称迈向先进空中交通的主动一步，获 FAA 批准后拟与其他机构合作。造价约 15 万美元的载具亦作航空航天学生教具；反应既有对创新的兴奋，也有对「空中监控」的担忧。", "body_en": "Florida Poly Police Debut First U.S. eVTOL for Campus Patrols.\n\nImagine a compact flying machine zipping over a sunny campus, letting officers reach remote spots faster than ever. Florida Polytechnic University just made that real with their new electric aircraft named Astro.\n\nThe Florida Polytechnic University Police Department introduced the Jetson ONE eVTOL, a single-seat electric flyer reaching 63 mph with 20 minutes of flight time, for surveillance, emergencies, and accessing hard-to-reach areas on the Lakeland campus.\n\nPolice Chief Aaron Murray called it a proactive step into advanced air mobility, with plans to partner with other agencies once FAA approval comes through. The $150,000 vehicle doubles as an educational tool for the school's aerospace engineering students, amid mixed reactions from excitement over innovation to worries about sky-high surveillance.", "body_zh": "佛州理工警方启用美国校园首架 eVTOL 巡逻。\n\n紧凑电动飞行器掠过阳光校园，警员更快抵达偏远角落。佛罗里达理工大学用名为 Astro 的新电动飞行器把它变成现实。\n\n佛罗里达理工大学警察局推出 Jetson ONE eVTOL：单座电动飞行器时速可达 63 英里、续航约 20 分钟，用于莱克兰校园监控、应急与抵达难达区域。警察局长 Aaron Murray 称迈向先进空中交通的主动一步，获 FAA 批准后拟与其他机构合作。\n\n造价约 15 万美元的载具亦作航空航天学生教具；反应既有对创新的兴奋，也有对「空中监控」的担忧。", "url": "https://x.com/i/trending/2112660061256335405", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-21T03:00:44.000Z"}, {"id": "2112453611825377473", "domain": "科学", "title_en": "Japan Launches MMX Spacecraft for First Phobos Sample Return", "title_zh": "日本发射 MMX：首次火卫一样本返回任务启程", "hook_en": "Mission controllers in Japan cheered as the MMX probe separated from its rocket, kicking off a decade-long quest to grab samples from Mars' potato-shaped moon Phobos.", "hook_zh": "日本任务控制欢呼 MMX 与火箭分离，开启长达约十年的火卫一采样之旅。", "summary_en": "Japan's uncrewed MMX spacecraft lifted off Tuesday from Tanegashima Space Center aboard an H3 rocket, embarking on a 10-month trip to Mars to study Phobos and return at least 10 grams of its surface material by 2031. The mission will orbit Mars starting in 2027, deploy a rover from France and Germany around 2029, and attempt up to two landings, with NASA providing key instruments like the P-Sampler for quick sample collection. Scientists aim to learn if Phobos is a captured asteroid or impact debris, shedding light on solar system origins and future Mars exploration.", "summary_zh": "无人探测器 MMX 周二由 H3 火箭从种子岛升空，约 10 个月飞往火星，研究火卫一并计划 2031 年前带回至少 10 克表层样本。任务将于 2027 年入轨火星，约 2029 年释放法德联合火星车，并尝试最多两次着陆；NASA 提供快速采样等关键仪器。科学家希望弄清火卫一是捕获小行星还是撞击碎片，以服务太阳系起源与未来火星探测。", "body_en": "Japan Launches MMX Spacecraft for First Phobos Sample Return.\n\nMission controllers in Japan cheered as the MMX probe separated from its rocket, kicking off a decade-long quest to grab samples from Mars' potato-shaped moon Phobos.\n\nJapan's uncrewed MMX spacecraft lifted off Tuesday from Tanegashima Space Center aboard an H3 rocket, embarking on a 10-month trip to Mars to study Phobos and return at least 10 grams of its surface material by 2031.\n\nThe mission will orbit Mars starting in 2027, deploy a rover from France and Germany around 2029, and attempt up to two landings, with NASA providing key instruments like the P-Sampler for quick sample collection. Scientists aim to learn if Phobos is a captured asteroid or impact debris, shedding light on solar system origins and future Mars exploration.", "body_zh": "日本发射 MMX：首次火卫一样本返回任务启程。\n\n日本任务控制欢呼 MMX 与火箭分离，开启长达约十年的火卫一采样之旅。\n\n无人探测器 MMX 周二由 H3 火箭从种子岛升空，约 10 个月飞往火星，研究火卫一并计划 2031 年前带回至少 10 克表层样本。任务将于 2027 年入轨火星，约 2029 年释放法德联合火星车，并尝试最多两次着陆；NASA 提供快速采样等关键仪器。\n\n科学家希望弄清火卫一是捕获小行星还是撞击碎片，以服务太阳系起源与未来火星探测。", "url": "https://x.com/i/trending/2112453611825377473", "category": "News", "topics": ["Space"], "updated_at": "2026-10-21T02:12:34.000Z"}, {"id": "2112620323275485557", "domain": "科学", "title_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides", "title_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学", "hook_en": "Cancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.", "hook_zh": "同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。", "summary_en": "Holon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests. In tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "summary_zh": "Holon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "body_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides.\n\nCancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.\n\nHolon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests.\n\nIn tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "body_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学。\n\n同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。\n\nHolon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。\n\n联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "url": "https://x.com/i/trending/2112620323275485557", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T01:29:19.000Z"}, {"id": "2112160143613874580", "domain": "科学", "title_en": "Trump Signs Order for NIH Women’s Health Division and Task Force", "title_zh": "特朗普签署行政令，设立 NIH 女性健康分部与白宫工作组", "hook_en": "First Lady Melania Trump stood beside President Trump as he signed the executive order, calling it a transformative moment for women's health in America.", "hook_zh": "第一夫人梅拉尼娅陪同总统签署面向女性健康的行政令。", "summary_en": "On October 19, President Donald Trump signed an executive order establishing a new Women’s Health Division at the National Institutes of Health and a White House task force co-led by Chief of Staff Susie Wiles and HHS Secretary Robert F. Kennedy Jr. The initiative targets research gaps in conditions like osteoporosis, Alzheimer’s, heart disease, endometriosis, and maternal health, with the division to launch within 90 days. Melania Trump outlined five pillars for innovation, including AI-driven discoveries and affordable therapies, while Wiles shared how her breast cancer experience made early detection personal.", "summary_zh": "行政令设立 NIH 女性健康分部与白宫工作组，聚焦骨质疏松、阿尔茨海默病、心脏病、子宫内膜异位症与孕产妇健康等。", "body_en": "Trump Signs Order for NIH Women’s Health Division and Task Force.\n\nFirst Lady Melania Trump stood beside President Trump as he signed the executive order, calling it a transformative moment for women's health in America.\n\nOn October 19, President Donald Trump signed an executive order establishing a new Women’s Health Division at the National Institutes of Health and a White House task force co-led by Chief of Staff Susie Wiles and HHS Secretary Robert F.Kennedy Jr.\n\nThe initiative targets research gaps in conditions like osteoporosis, Alzheimer’s, heart disease, endometriosis, and maternal health, with the division to launch within 90 days. Melania Trump outlined five pillars for innovation, including AI-driven discoveries and affordable therapies, while Wiles shared how her breast cancer experience made early detection personal.", "body_zh": "特朗普签署行政令，设立 NIH 女性健康分部与白宫工作组。\n\n第一夫人梅拉尼娅陪同总统签署面向女性健康的行政令。\n\n行政令设立 NIH 女性健康分部与白宫工作组，聚焦骨质疏松、阿尔茨海默病、心脏病、子宫内膜异位症与孕产妇健康等。\n\n第一夫人梅拉尼娅陪同总统签署面向女性健康的行政令。\n\n综合以上信息，特朗普签署行政令，设立 NIH 女性健康分部与白宫工作组一事持续引发关注。", "url": "https://x.com/i/trending/2112160143613874580", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T01:11:38.000Z"}, {"id": "2112623559876952326", "domain": "科学", "title_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test", "title_zh": "Reflect Orbital 在加州沙漠模拟「轨道阳光」", "hook_en": "In a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.", "hook_zh": "惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。", "summary_en": "On October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams. The demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "summary_zh": "Reflect Orbital 用地面灯具照亮约三英里范围，测试搜救用途；并预告将发射带镜子的卫星星座，向目标区域投送定向阳光。", "body_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test.\n\nIn a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.\n\nOn October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams.\n\nThe demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.\n\nOn October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams. The demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "body_zh": "Reflect Orbital 在加州沙漠模拟「轨道阳光」。\n\n惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。\n\nReflect Orbital 用地面灯具照亮约三英里范围，测试搜救用途；并预告将发射带镜子的卫星星座，向目标区域投送定向阳光。\n\n综合以上信息，Reflect Orbital 在加州沙漠模拟「轨道阳光」一事持续引发关注。", "url": "https://x.com/i/trending/2112623559876952326", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-21T00:18:52.000Z"}, {"id": "2112433199888679267", "domain": "科学", "title_en": "AI Predicts Cancer Survival from Face Photos", "title_zh": "AI 凭面部照片预测癌症生存风险", "hook_en": "Doctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.", "hook_zh": "医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。", "summary_en": "Researchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation. While promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "summary_zh": "麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "body_en": "AI Predicts Cancer Survival from Face Photos.\n\nDoctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.\n\nResearchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients.\n\nIn tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation. While promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet.Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "body_zh": "AI 凭面部照片预测癌症生存风险。\n\n医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。\n\n麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。\n\n工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "url": "https://x.com/i/trending/2112433199888679267", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T21:07:35.000Z"}, {"id": "2112552619117891920", "domain": "科学", "title_en": "Review Identifies 37 Anticancer Mechanisms for Ivermectin and Mebendazole Combo", "title_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制", "hook_en": "A detailed scientific review uncovers 37 ways ivermectin and mebendazole team up against cancer cells across 25 human types, drawing from over 100 lab and animal studies.", "hook_zh": "详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。", "summary_en": "Researchers at the McCullough Foundation, including Nicolas Hulscher, Peter A. McCullough, and Harvey Risch, synthesized preclinical evidence showing the drugs disrupt cancer cell division, trigger cell death, block energy and blood vessel growth, and more. The 44-page paper notes their low cost, off-patent status, and long safety record in humans, with overlapping effects on key cancer processes. While calling for large clinical trials, it references limited human reports like a Polish woman's normalized markers after using the combo, though experts stress the need for randomized trials amid some study retractions.", "summary_zh": "McCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "body_en": "Review Identifies 37 Anticancer Mechanisms for Ivermectin and Mebendazole Combo.\n\nA detailed scientific review uncovers 37 ways ivermectin and mebendazole team up against cancer cells across 25 human types, drawing from over 100 lab and animal studies.\n\nResearchers at the McCullough Foundation, including Nicolas Hulscher, Peter A.McCullough, and Harvey Risch, synthesized preclinical evidence showing the drugs disrupt cancer cell division, trigger cell death, block energy and blood vessel growth, and more.\n\nThe 44-page paper notes their low cost, off-patent status, and long safety record in humans, with overlapping effects on key cancer processes. While calling for large clinical trials, it references limited human reports like a Polish woman's normalized markers after using the combo, though experts stress the need for randomized trials amid some study retractions.", "body_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制。\n\n详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。\n\nMcCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。\n\n作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "url": "https://x.com/i/trending/2112552619117891920", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-20T20:43:03.000Z"}, {"id": "2112640445633499411", "domain": "科学", "title_en": "Electric Plant Launches Bombadil AI to Read Plant Electrical Signals", "title_zh": "Electric Plant 推出 Bombadil：解读植物电信号的 AI", "hook_en": "Imagine slipping a tiny sensor into a plant and getting a real-time readout of its health, just like monitoring brainwaves. Electric Plant's new AI, Bombadil, makes that possible by decoding subtle electrical signals from living plants.", "hook_zh": "像监测脑电一样，把微型传感器接入植物即可实时读健康——Bombadil 解码活体植物微弱电信号。", "summary_en": "The startup pairs low-cost Bud sensors with Bombadil, a foundation model trained on over seven million hours of data from 125 plant species, to track stress, water needs, photosynthesis efficiency, and more. Co-founder Justin Mast says it could cut water use by 20 percent or more for growers by enabling precise irrigation based on individual plant signals rather than soil alone. Backed by an $11.2 million seed round, the team—from neuroscientists to AI experts—built it after years of recording signals in labs, forests, and orchards, with early enthusiasm for its potential in farming and climate tech.", "summary_zh": "初创公司将低成本 Bud 传感器与在 125 种植物、逾 700 万小时数据上训练的基础模型 Bombadil 组合，追踪胁迫、需水、光合效率等。联合创始人 Justin Mast 称，按单株信号而非仅土壤精准灌溉，种植者用水或可降 20% 以上。种子轮 1120 万美元；团队含神经科学家与 AI 专家，经年在实验室、森林与果园记录信号，农业与气候科技前景获早期热捧。", "body_en": "Electric Plant Launches Bombadil AI to Read Plant Electrical Signals.\n\nImagine slipping a tiny sensor into a plant and getting a real-time readout of its health, just like monitoring brainwaves. Electric Plant's new AI, Bombadil, makes that possible by decoding subtle electrical signals from living plants.\n\nThe startup pairs low-cost Bud sensors with Bombadil, a foundation model trained on over seven million hours of data from 125 plant species, to track stress, water needs, photosynthesis efficiency, and more.\n\nCo-founder Justin Mast says it could cut water use by 20 percent or more for growers by enabling precise irrigation based on individual plant signals rather than soil alone. Backed by an $11.2 million seed round, the team—from neuroscientists to AI experts—built it after years of recording signals in labs, forests, and orchards, with early enthusiasm for its potential in farming and climate tech.", "body_zh": "Electric Plant 推出 Bombadil：解读植物电信号的 AI。\n\n像监测脑电一样，把微型传感器接入植物即可实时读健康——Bombadil 解码活体植物微弱电信号。\n\n初创公司将低成本 Bud 传感器与在 125 种植物、逾 700 万小时数据上训练的基础模型 Bombadil 组合，追踪胁迫、需水、光合效率等。联合创始人 Justin Mast 称，按单株信号而非仅土壤精准灌溉，种植者用水或可降 20% 以上。\n\n种子轮 1120 万美元；团队含神经科学家与 AI 专家，经年在实验室、森林与果园记录信号，农业与气候科技前景获早期热捧。", "url": "https://x.com/i/trending/2112640445633499411", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-20T20:33:11.000Z"}, {"id": "2112514540671730138", "domain": "科学", "title_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight", "title_zh": "路透调查：热风暴已连续 18 年覆盖全球某处", "hook_en": "Imagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.", "hook_zh": "路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。", "summary_en": "Reuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade. People share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "summary_zh": "路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "body_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight.\n\nImagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.\n\nReuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s.\n\nSince July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade. People share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "body_zh": "路透调查：热风暴已连续 18 年覆盖全球某处。\n\n路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。\n\n路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。\n\n人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "url": "https://x.com/i/trending/2112514540671730138", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T17:06:35.000Z"}, {"id": "2111892089000915435", "domain": "科学", "title_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds", "title_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道", "hook_en": "Thousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.", "hook_zh": "10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。", "summary_en": "Ruto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units. He inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "summary_zh": "鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "body_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds.\n\nThousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.\n\nRuto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units.\n\nHe inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "body_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道。\n\n10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。\n\n鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。\n\n行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "url": "https://x.com/i/trending/2111892089000915435", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-20T06:36:12.000Z"}, {"id": "2112414671194009776", "domain": "科学", "title_en": "Rocket Lab Videos Automated Machine Building Neutron Rocket Dome", "title_zh": "火箭实验室晒自动铺丝机制作 Neutron 整流罩穹顶", "hook_en": "Thousands of hair-thin carbon fibers whip into place at blistering speeds, forming the massive forward dome for Neutron's Stage 1 tank. It's a glimpse into the precision powering Rocket Lab's next big leap.", "hook_zh": "成千上万根发丝般碳纤维高速铺就 Neutron 一级贮箱巨大前穹顶。", "summary_en": "Rocket Lab released footage of its automated fiber placement machine at the Maryland facility laying down carbon strands up to 100 meters per minute on custom molds for the Neutron rocket's large composite forward dome. This step follows last week's news of a 2027 first-launch target after fixing voids in a prior manual dome, with CEO Peter Beck confirming refined processes and a successful aft dome. Investors and fans praised the update for building excitement around production progress toward a reusable rocket carrying 13,000 kg to orbit, with upcoming tests ahead.", "summary_zh": "火箭实验室公布马里兰工厂自动铺丝机画面：以最高约每分钟 100 米在定制模具上铺碳丝，制作 Neutron 大型复合材料前穹顶。此前手工穹顶空隙问题已修复，CEO 彼得·贝克确认工艺改进与后穹顶成功，首飞目标 2027 年。投资者与粉丝为可复用、运力约 1.3 万公斤入轨的火箭量产进展叫好，后续测试将至。", "body_en": "Rocket Lab Videos Automated Machine Building Neutron Rocket Dome.\n\nThousands of hair-thin carbon fibers whip into place at blistering speeds, forming the massive forward dome for Neutron's Stage 1 tank. It's a glimpse into the precision powering Rocket Lab's next big leap.\n\nRocket Lab released footage of its automated fiber placement machine at the Maryland facility laying down carbon strands up to 100 meters per minute on custom molds for the Neutron rocket's large composite forward dome.\n\nThis step follows last week's news of a 2027 first-launch target after fixing voids in a prior manual dome, with CEO Peter Beck confirming refined processes and a successful aft dome. Investors and fans praised the update for building excitement around production progress toward a reusable rocket carrying 13,000 kg to orbit, with upcoming tests ahead.", "body_zh": "火箭实验室晒自动铺丝机制作 Neutron 整流罩穹顶。\n\n成千上万根发丝般碳纤维高速铺就 Neutron 一级贮箱巨大前穹顶。\n\n火箭实验室公布马里兰工厂自动铺丝机画面：以最高约每分钟 100 米在定制模具上铺碳丝，制作 Neutron 大型复合材料前穹顶。此前手工穹顶空隙问题已修复，CEO 彼得·贝克确认工艺改进与后穹顶成功，首飞目标 2027 年。\n\n投资者与粉丝为可复用、运力约 1.3 万公斤入轨的火箭量产进展叫好，后续测试将至。", "url": "https://x.com/i/trending/2112414671194009776", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-20T05:28:17.000Z"}]};
